                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .size(40.dp)
                    .background(
                        color = if (isEnabled) NoteTheme.Primary.copy(alpha = 0.12f)
                        else NoteTheme.OnSurfaceVariant.copy(alpha = 0.08f),
                        shape = RoundedCornerShape(12.dp)
                    )
            ) {
                Icon(
                    Icons.Default.AutoAwesome,
