    )
}

package com.amvarpvtltd.swiftNote.ai

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.checklist.ChecklistParser
import com.amvarpvtltd.swiftNote.richtext.RichTextBridge
import com.amvarpvtltd.swiftNote.security.GeminiKeyManager
import com.amvarpvtltd.swiftNote.utils.AutoTitleGenerator
import com.google.ai.client.generativeai.GenerativeModel
import com.google.ai.client.generativeai.type.GenerationConfig
import com.google.ai.client.generativeai.type.content
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.net.HttpURLConnection
import java.net.URL
import org.json.JSONArray
import org.json.JSONObject

/**
 * AI-powered title generator using LLMs (Gemini, Groq, OpenAI-compatible).
 *
 * Strategy: Try LLM first → fall back to rule-based [AutoTitleGenerator] on failure.
 *
 * Supports:
 * - Google Gemini (via official SDK, using user's stored API key)
 * - Groq (via OpenAI-compatible REST API)
 * - Any OpenAI-compatible endpoint (custom base URL)
 *
 * Rate-limited to avoid burning free-tier quotas on title generation.
 * Title generation uses minimal tokens (~50 output tokens max).
 */
class AITitleGenerator private constructor(private val context: Context) {

    companion object {
        private const val TAG = "AITitleGenerator"

        @Volatile
        private var INSTANCE: AITitleGenerator? = null

        fun getInstance(context: Context): AITitleGenerator {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: AITitleGenerator(context.applicationContext).also { INSTANCE = it }
            }
        }

        // Rate limit: max 5 title generation calls per minute (conservative to preserve quota)
        private const val MAX_TITLE_CALLS_PER_MINUTE = 5
        private val titleCallTimestamps = mutableListOf<Long>()

        // Groq free API endpoint
        private const val GROQ_API_URL = "https://api.groq.com/openai/v1/chat/completions"
        private const val GROQ_MODEL = "llama-3.1-8b-instant"

        // Default timeout for LLM calls (title generation should be fast)
        private const val LLM_TIMEOUT_MS = 8000L
    }

    private var geminiModel: GenerativeModel? = null
    private var cachedGeminiKey: String? = null

    // ──────────────────── PUBLIC API ────────────────────

    /**
     * Generate a title using LLM first, falling back to rules.
     * Call from a coroutine (IO dispatcher recommended).
     *
     * @param description Raw note description (HTML, checklist, or plain text)
     * @return Generated title (never empty if description has content)
     */
    suspend fun generate(description: String): String {
        if (description.isBlank()) {
            Log.d(TAG, "⚠️ Description is blank, skipping AI title generation")
            return ""
        }

        // Get plain text for the LLM prompt
        val plainText = getPlainText(description)
        if (plainText.isBlank()) {
            Log.d(TAG, "⚠️ Plain text extraction resulted in blank, skipping")
            return ""
        }

        Log.d(TAG, " AI Title Generator triggered. Text length: ${plainText.length}")
        Log.d(TAG, " Gemini enabled: ${GeminiKeyManager.isEnabled(context)}, " +
            "Gemini key configured: ${GeminiKeyManager.isConfigured(context)}, " +
            "Gemini key blank: ${GeminiKeyManager.getActiveApiKey(context).isBlank()}, " +
            "Groq key present: ${getGroqApiKey().isNotBlank()}")

        // Try LLM if within rate limits — check availability inside tryLLMGeneration
        if (!canMakeLLMCall()) {
            Log.w(TAG, "⚠️ Rate limit reached (${MAX_TITLE_CALLS_PER_MINUTE}/min), using rules")
        } else {
            val llmTitle = tryLLMGeneration(plainText)
            if (!llmTitle.isNullOrBlank() && llmTitle.length >= 3) {
                Log.d(TAG, "✨ AI title generated: \"$llmTitle\"")
                return llmTitle
            }
            Log.d(TAG, "⚠️ LLM returned empty/null/short result, falling back to rules")
        }

        // Fallback to rule-based
        Log.d(TAG, " Falling back to rule-based title generation")
        return AutoTitleGenerator.generate(description)
    }

    /**
     * Check if any LLM provider is available for title generation.
     * More lenient than GeminiKeyManager.isEnabled() — just checks if a key exists.
     */
    fun isAvailable(): Boolean {
        return GeminiKeyManager.getActiveApiKey(context).isNotBlank() || getGroqApiKey().isNotBlank()
    }

    // ──────────────────── LLM ORCHESTRATION ────────────────────

    /**
     * Try LLM providers in order: Gemini → Groq → null (falls back to rules).
     */
    private suspend fun tryLLMGeneration(plainText: String): String? {
        // Strategy 1: Gemini (via SDK)
        // Use isConfigured + hasKey check (more lenient than isEnabled which requires explicit toggle)
        val geminiKey = GeminiKeyManager.getActiveApiKey(context)
        if (geminiKey.isNotBlank()) {
            Log.d(TAG, " Attempting Gemini title generation...")
            val geminiResult = tryGemini(plainText)
            if (!geminiResult.isNullOrBlank()) {
                Log.d(TAG, " Gemini succeeded: \"$geminiResult\"")
                return geminiResult
            }
            Log.d(TAG, " Gemini returned null/blank")
        } else {
            Log.d(TAG, " Gemini skipped — no active API key")
        }

        // Strategy 2: Groq (via REST, free tier)
        val groqKey = getGroqApiKey()
        if (groqKey.isNotBlank()) {
            Log.d(TAG, " Attempting Groq title generation...")
            val groqResult = tryGroq(plainText, groqKey)
            if (!groqResult.isNullOrBlank()) {
                Log.d(TAG, " Groq succeeded: \"$groqResult\"")
                return groqResult
            }
            Log.d(TAG, " Groq returned null/blank")
        } else {
            Log.d(TAG, " Groq skipped — no API key with 'groq' label found")
        }

        return null
    }

    // ──────────────────── GEMINI (SDK) ────────────────────

    private suspend fun tryGemini(plainText: String): String? = withContext(Dispatchers.IO) {
        try {
            val model = getOrCreateGeminiModel()
            if (model == null) {
                Log.w(TAG, "❌ Gemini model creation failed (key issue?)")
                return@withContext null
            }

            recordCall()
            GeminiKeyManager.recordUsage(context)

            val prompt = buildTitlePrompt(plainText)
            Log.d(TAG, " Gemini prompt sent (${prompt.length} chars)")

            val response = withTimeoutOrNull(LLM_TIMEOUT_MS) {
                model.generateContent(content { text(prompt) })
            }

            if (response == null) {
                Log.w(TAG, "❌ Gemini request timed out (${LLM_TIMEOUT_MS}ms)")
                return@withContext null
            }

            val raw = response.text?.trim()
            if (raw.isNullOrBlank()) {
                Log.w(TAG, "❌ Gemini returned empty response text")
                return@withContext null
            }

            Log.d(TAG, " Gemini raw response: \"$raw\"")
            return@withContext cleanLLMResponse(raw)

        } catch (e: Exception) {
            Log.e(TAG, "❌ Gemini title generation failed: ${e.message}", e)
            return@withContext null
        }
    }

    private fun getOrCreateGeminiModel(): GenerativeModel? {
        val userKey = GeminiKeyManager.getActiveApiKey(context)
        if (userKey.isBlank()) return null

        if (userKey != cachedGeminiKey) {
            cachedGeminiKey = userKey
            geminiModel = GenerativeModel(
                modelName = "gemini-2.0-flash",
                apiKey = userKey,
                generationConfig = GenerationConfig.Builder().apply {
                    temperature = 0.3f  // Slightly creative for titles
                    maxOutputTokens = 30  // Titles are short — save tokens
                    topP = 0.9f
                }.build()
            )
        }
        return geminiModel
    }

    // ──────────────────── GROQ (REST API) ────────────────────

    private suspend fun tryGroq(plainText: String, apiKey: String): String? = withContext(Dispatchers.IO) {
        try {
            recordCall()

            val prompt = buildTitlePrompt(plainText)
            val requestBody = JSONObject().apply {
                put("model", GROQ_MODEL)
                put("messages", JSONArray().apply {
                    put(JSONObject().apply {
                        put("role", "system")
                        put("content", SYSTEM_PROMPT)
                    })
                    put(JSONObject().apply {
                        put("role", "user")
                        put("content", prompt)
                    })
                })
                put("max_tokens", 30)
                put("temperature", 0.3)
            }

            val result = withTimeoutOrNull(LLM_TIMEOUT_MS) {
                makeHttpPost(GROQ_API_URL, apiKey, requestBody.toString())
            } ?: return@withContext null

            // Parse OpenAI-compatible response
            val json = JSONObject(result)
            val content = json.getJSONArray("choices")
                .getJSONObject(0)
                .getJSONObject("message")
                .getString("content")
                .trim()

            return@withContext cleanLLMResponse(content)

        } catch (e: Exception) {
            Log.w(TAG, "Groq title generation failed: ${e.message}")
            return@withContext null
        }
    }

    // ──────────────────── HTTP HELPER ────────────────────

    private fun makeHttpPost(url: String, apiKey: String, body: String): String {
        val connection = (URL(url).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            setRequestProperty("Content-Type", "application/json")
            setRequestProperty("Authorization", "Bearer $apiKey")
            connectTimeout = 5000
            readTimeout = 5000
            doOutput = true
        }

        try {
            OutputStreamWriter(connection.outputStream).use { it.write(body) }

            if (connection.responseCode != 200) {
                val error = connection.errorStream?.bufferedReader()?.readText() ?: "Unknown error"
                Log.w(TAG, "HTTP ${connection.responseCode}: $error")
                return ""
            }

            return BufferedReader(InputStreamReader(connection.inputStream)).use { it.readText() }
        } finally {
            connection.disconnect()
        }
    }

    // ──────────────────── PROMPT ────────────────────

    private val SYSTEM_PROMPT = """You are a note title generator. Given note content, respond with ONLY a short title (2-6 words). Rules:
- Maximum 5-6 words
- No quotes, no punctuation at end (unless it's a question)
- Capture the core topic/action
- Use title case
- If it's a task/action, start with the verb
- If it's a list, name the category
- Never say "Note about..." or "Untitled" 
- Respond with ONLY the title, nothing else"""

    private fun buildTitlePrompt(plainText: String): String {
        // Send only first 300 chars to keep token usage minimal
        val truncatedContent = if (plainText.length > 300) {
            plainText.take(300) + "..."
        } else {
            plainText
        }

        return """Generate a short title (2-6 words) for this note:

$truncatedContent

Title:"""
    }

    // ──────────────────── RESPONSE CLEANING ────────────────────

    private fun cleanLLMResponse(raw: String): String? {
        var cleaned = raw
            .removePrefix("Title:")
            .removePrefix("title:")
            .trim()
            .removeSurrounding("\"")
            .removeSurrounding("'")
            .removeSurrounding("`")
            .trim()
            // Remove trailing period (unless question mark)
            .replace(Regex("\\.$"), "")
            .trim()

        // Reject if too long, too short, or looks like a sentence/explanation
        if (cleaned.length < 3 || cleaned.length > 50) {
            Log.d(TAG, " Cleaned response rejected (length=${cleaned.length}): \"$cleaned\"")
            return null
        }
        if (cleaned.contains("\n")) cleaned = cleaned.lines().first().trim()
        if (cleaned.split(" ").size > 8) {
            Log.d(TAG, " Cleaned response rejected (too many words: ${cleaned.split(" ").size}): \"$cleaned\"")
            return null
        }
        if (cleaned.lowercase().startsWith("here")) {
            Log.d(TAG, " Cleaned response rejected (starts with 'here'): \"$cleaned\"")
            return null
        }
        if (cleaned.lowercase().startsWith("note about")) {
            Log.d(TAG, " Cleaned response rejected (starts with 'note about'): \"$cleaned\"")
            return null
        }

        Log.d(TAG, " Cleaned LLM response: \"$cleaned\"")
        // Enforce max title length
        return AutoTitleGenerator.truncate(cleaned)
    }

    // ──────────────────── RATE LIMITING ────────────────────

    private fun canMakeLLMCall(): Boolean {
        val now = System.currentTimeMillis()
        titleCallTimestamps.removeAll { now - it > 60_000 }
        return titleCallTimestamps.size < MAX_TITLE_CALLS_PER_MINUTE
    }

    private fun recordCall() {
        titleCallTimestamps.add(System.currentTimeMillis())
    }

    // ──────────────────── KEY MANAGEMENT ────────────────────

    /**
     * Get Groq API key from shared preferences.
     * Stored alongside Gemini keys in GeminiKeyManager with label "groq".
     * Users can add a Groq key via AI Settings with label containing "groq".
     */
    private fun getGroqApiKey(): String {
        val allKeys = GeminiKeyManager.getAllKeys(context)
        return allKeys.firstOrNull { it.label.lowercase().contains("groq") }?.apiKey ?: ""
    }

    // ──────────────────── UTILS ────────────────────

    private fun getPlainText(description: String): String {
        if (ChecklistParser.isChecklistContent(description)) {
            val items = ChecklistParser.parseItems(description)
            return items.filter { it.text.isNotBlank() }
                .joinToString("\n") { "- ${it.text}" }
        }

        val result = if (RichTextBridge.containsHtml(description)) {
            RichTextBridge.stripHtmlToPlainText(description)
        } else {
            description
        }.trim()

        Log.d(TAG, " getPlainText: input length=${description.length}, " +
            "containsHtml=${RichTextBridge.containsHtml(description)}, " +
            "output length=${result.length}, " +
            "preview=\"${result.take(80)}\"")
        return result
    }
