            }
        }
        Log.e(TAG, " All Gemini models exhausted")
        return null
    }

    private suspend fun validateGeminiKey(apiKey: String): KeyValidationResult =
        withContext(Dispatchers.IO) {
            // Quick format sanity check — real Gemini keys start with "AIza" and are ~39 chars.
            val trimmed = apiKey.trim()
            if (trimmed.length < 30 || !trimmed.startsWith("AIza")) {
                return@withContext KeyValidationResult.Failed(
                    "Invalid API key format. Gemini keys start with \"AIza\" and are ~39 characters long."
                )
            }

            var sawAuthError = false
            var lastError: String? = null

            for (modelName in LlmModels.GEMINI_MODELS) {
                try {
                    val testModel = GenerativeModel(
                        modelName = modelName,
                        apiKey = trimmed,
                        generationConfig = GenerationConfig.Builder().apply {
                            temperature = 0.1f
                            maxOutputTokens = 32
                        }.build()
                    )
                    val response = withTimeoutOrNull(TIMEOUT_MS) {
                        testModel.generateContent(content { text("Reply with just: OK") })
                    } ?: run {
                        lastError = "timeout"
                        continue
                    }
                    if (!response.text.isNullOrBlank()) {
                        saveLastGoodModel(modelName, LlmProvider.GEMINI)
                        return@withContext KeyValidationResult.Success
                    }
                } catch (e: Exception) {
                    if (e is kotlinx.coroutines.CancellationException) throw e
                    val msg = e.message?.lowercase() ?: ""
                    lastError = e.message?.take(120)
                    when {
                        msg.contains("resource_exhausted") || msg.contains("429") ||
                        msg.contains("quota") || msg.contains("rate limit") -> {
                            return@withContext KeyValidationResult.Success // Key is valid, just rate-limited
                        }
                        // Auth/key errors — match every realistic variant Gemini returns.
                        msg.contains("api key not valid") ||           // ← most common real-world response
                        msg.contains("invalid api key") ||
                        msg.contains("api_key_invalid") ||
                        msg.contains("api key expired") ||
                        msg.contains("permission_denied") ||
                        msg.contains("permission denied") ||
                        msg.contains("unauthenticated") ||
                        msg.contains("unauthorized") ||
                        msg.contains("401") ||
                        msg.contains("403") -> {
                            return@withContext KeyValidationResult.Failed(
                                "Invalid API key. Please check it and try again. (Get one at aistudio.google.com/apikey)"
                            )
                        }
                        msg.contains("400") || msg.contains("bad request") -> {
                            // 400 from the Gemini endpoint almost always means a malformed/invalid key.
                            sawAuthError = true
                            continue
                        }
                        msg.contains("not found") || msg.contains("404") -> continue
                        msg.contains("network") || msg.contains("unable to resolve") ||
                        msg.contains("timeout") || msg.contains("unreachable") ||
                        msg.contains("connection") -> {
                            return@withContext KeyValidationResult.Failed(
                                "Network error. Check your internet connection and try again."
                            )
                        }
                        else -> continue
                    }
                }
            }
            if (sawAuthError) {
                KeyValidationResult.Failed(
                    "Invalid API key. Please check it and try again. (Get one at aistudio.google.com/apikey)"
                )
            } else {
                KeyValidationResult.Failed(
                    "Could not validate key against any model. " +
                    (lastError?.let { "Last error: $it. " } ?: "") +
                    "Check your internet connection and that the key is correct."
                )
            }
        }

    // ────────────────────────── GROQ ──────────────────────────────────────────

    private suspend fun tryGroqModels(
        apiKey: String,
        prompt: String,
        systemPrompt: String?,
        temperature: Float,
        maxTokens: Int
    ): String? {
        val lastGood = prefs.getString(KEY_LAST_GOOD_MODEL, null)
            ?.takeIf { it in LlmModels.GROQ_MODELS }
        val orderedModels = if (lastGood != null) {
            listOf(lastGood) + LlmModels.GROQ_MODELS.filter { it != lastGood }
        } else LlmModels.GROQ_MODELS

        for (modelName in orderedModels) {
            try {
                Log.d(TAG, " Trying Groq/$modelName…")
                val text = GroqClient.generateContent(
                    apiKey = apiKey,
                    model = modelName,
                    systemPrompt = systemPrompt,
                    userMessage = prompt,
                    temperature = temperature,
                    maxTokens = maxTokens
                )
                if (text.isNotBlank()) {
                    saveLastGoodModel(modelName, LlmProvider.GROQ)
                    return text
                }
            } catch (e: GroqApiException) {
                when {
                    e.statusCode == 429 -> {
                        Log.w(TAG, "⏳ Groq/$modelName: rate limited → next")
                        continue
                    }
                    e.statusCode == 401 || e.statusCode == 403 -> {
                        Log.e(TAG, " Groq auth error — aborting")
                        return null
                    }
                    e.statusCode == 404 -> {
                        Log.w(TAG, "⚠️ Groq/$modelName: not found → next")
                        continue
                    }
                    else -> {
                        Log.w(TAG, "❌ Groq/$modelName: ${e.message?.take(80)} → next")
                        continue
                    }
                }
            } catch (e: Exception) {
                if (e is kotlinx.coroutines.CancellationException) throw e
                Log.w(TAG, "❌ Groq/$modelName: ${e.message?.take(80)} → next")
                continue
            }
        }
        Log.e(TAG, " All Groq models exhausted")
        return null
    }

    private suspend fun validateGroqKey(apiKey: String): KeyValidationResult {
        return when (val result = GroqClient.validateKey(apiKey)) {
            is GroqClient.ValidationResult.Success -> KeyValidationResult.Success
            is GroqClient.ValidationResult.QuotaButValid -> KeyValidationResult.Success
            is GroqClient.ValidationResult.AuthError -> KeyValidationResult.Failed(
                "Invalid Groq API key: ${result.message}"
            )
            is GroqClient.ValidationResult.AllModelsFailed -> KeyValidationResult.Failed(
                "Could not validate key. Check your internet connection."
            )
        }
    }

    // ────────────────────────── HELPERS ────────────────────────────────────────

    private fun saveLastGoodModel(model: String, provider: LlmProvider) {
        prefs.edit {
            putString(KEY_LAST_GOOD_MODEL, model)
            putString(KEY_LAST_GOOD_PROVIDER, provider.name)
        }
    }

    private fun canMakeCall(): Boolean {
        val now = System.currentTimeMillis()
        callTimestamps.removeAll { now - it > 60_000 }
        if (callTimestamps.size >= MAX_CALLS_PER_MINUTE) return false

        val today = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
        val savedDay = prefs.getString(KEY_DAY, "")
        val dayCount = if (savedDay == today) prefs.getInt(KEY_DAY_COUNT, 0)
        else {
            prefs.edit { putString(KEY_DAY, today); putInt(KEY_DAY_COUNT, 0) }
            0
        }

        return dayCount < MAX_CALLS_PER_DAY
    }

    private fun recordCall() {
        callTimestamps.add(System.currentTimeMillis())
        val today = SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date())
        val savedDay = prefs.getString(KEY_DAY, "")
        val current = if (savedDay == today) prefs.getInt(KEY_DAY_COUNT, 0) else 0
        prefs.edit { putString(KEY_DAY, today); putInt(KEY_DAY_COUNT, current + 1) }
    }
}

/**
 * Result of validating an API key.
 */
sealed class KeyValidationResult {
    object Success : KeyValidationResult()
    data class Failed(val errorMessage: String) : KeyValidationResult()
}

package com.amvarpvtltd.swiftNote.repository

import android.content.Context
import android.util.Log
import androidx.core.content.edit
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.isBlank
import com.amvarpvtltd.swiftNote.isDecryptFailed
import com.amvarpvtltd.swiftNote.offline.OfflineNoteManager
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import com.amvarpvtltd.swiftNote.utils.NetworkManager
import com.google.firebase.database.DatabaseReference
import com.google.firebase.database.FirebaseDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext

class NoteRepository(val context: Context? = null) {
    private val database = FirebaseDatabase.getInstance()
    // BUG-018 FIX: Cache OfflineNoteManager instance — avoids re-creating per call
    private val offlineManager: OfflineNoteManager? = context?.let { OfflineNoteManager(it) }

    companion object {
        private const val TAG = "NoteRepository"
        // Mutex to prevent concurrent sync operations from colliding
        private val syncMutex = Mutex()

        // BUG-040 FIX: Singleton instance to avoid redundant repository/manager creation
        @Volatile
        private var INSTANCE: NoteRepository? = null

        fun getInstance(context: Context): NoteRepository {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: NoteRepository(context.applicationContext).also { INSTANCE = it }
            }
        }

        /**
         * SharedPreferences key written by the Start Fresh flow.
         * When present-and-true, [syncFromCloudInBackground] skips the cloud-download step once
         * so that old Firebase notes cannot be pulled back immediately after a wipe.
         */
        private const val PREFS_SYNC = "note_repo_prefs"
        private const val KEY_SKIP_CLOUD_PULL = "skip_cloud_pull_once"

        /** Call from the Start Fresh handler (after wipe, before navigation). */
        fun markSkipNextCloudPull(context: Context) {
            context.getSharedPreferences(PREFS_SYNC, Context.MODE_PRIVATE)
                .edit { putBoolean(KEY_SKIP_CLOUD_PULL, true) }
        }
    }

    /**
     * Resolve the Firebase path for notes:
     * users/{accountId}/notes/{deviceId}
     * accountId = stored passphrase if present, otherwise deviceId
     */
    private fun resolveNotesRef(): DatabaseReference {
        val ctx = context ?: throw IllegalStateException("Context required to resolve notesRef")
        val deviceId = DeviceManager.getOrCreateDeviceId(ctx)
        val accountId = PassphraseManager.getStoredPassphrase(ctx).takeIf { !it.isNullOrEmpty() } ?: deviceId
        return database.getReference("users").child(accountId).child("notes").child(deviceId)
    }

    /**
     * Observe all notes reactively via Room Flow.
     * The list updates automatically when the database changes.
     */
    fun observeNotes(): Flow<List<dataclass>> {
        require(context != null) { "No context available for observeNotes" }
        val db = AppDatabase.getInstance(context)
        return db.noteDao().observeAllNotes()
            .map { entities -> entities.map { NoteEntityMapper.toDomain(it) } }
            .flowOn(Dispatchers.IO)
    }

    /**
     * Observe archived notes reactively via Room Flow.
     */
    fun observeArchivedNotes(): Flow<List<dataclass>> {
        require(context != null) { "No context available for observeArchivedNotes" }
        val db = AppDatabase.getInstance(context)
        return db.noteDao().observeArchivedNotes()
            .map { entities -> entities.map { NoteEntityMapper.toDomain(it) } }
            .flowOn(Dispatchers.IO)
    }

    /**
     * Toggle pin status for a note.
     */
    suspend fun togglePin(noteId: String, isPinned: Boolean) = withContext(Dispatchers.IO) {
        val ctx = context ?: return@withContext
        val db = AppDatabase.getInstance(ctx)
        db.noteDao().updatePinStatus(noteId, isPinned)
        // Try to sync updated note to cloud
        syncSingleNote(noteId)
        // Phase 5B: Refresh widget to reflect pin change
        com.amvarpvtltd.swiftNote.widget.WidgetUpdateWorker.refreshNow(ctx)
    }

    /**
     * Toggle archive status for a note.
     */
    suspend fun toggleArchive(noteId: String, isArchived: Boolean) = withContext(Dispatchers.IO) {
        val ctx = context ?: return@withContext
        val db = AppDatabase.getInstance(ctx)
        db.noteDao().updateArchiveStatus(noteId, isArchived)
        syncSingleNote(noteId)
    }

    /**
     * Update category for a note.
     */
    suspend fun updateCategory(noteId: String, category: String) = withContext(Dispatchers.IO) {
        val ctx = context ?: return@withContext
        val db = AppDatabase.getInstance(ctx)
        db.noteDao().updateCategory(noteId, category)
        syncSingleNote(noteId)
    }

    /**
     * Sync a single note to Firebase after local update.
     */
    private suspend fun syncSingleNote(noteId: String) {
        val ctx = context ?: return
        val networkManager = NetworkManager.getInstance(ctx)
        if (networkManager.isConnected()) {
            try {
                val db = AppDatabase.getInstance(ctx)
                val entity = db.noteDao().getNoteById(noteId) ?: return
                val note = NoteEntityMapper.toDomain(entity)
                val encryptedNote = note.toEncryptedData()
                resolveNotesRef().child(noteId).setValue(encryptedNote).await()
                db.noteDao().update(entity.copy(synced = true))
            } catch (e: Exception) {
                Log.w(TAG, "Failed to sync note $noteId after update: ${e.message}")
            }
        }
    }

    /**
     * Save a new note or update an existing one - OFFLINE FIRST
     * Always saves to Room database first, then attempts cloud sync
     */
    suspend fun saveNote(
        title: String,
        description: String,
        noteId: String? = null,
        context: Context,
        category: String? = null
    ): Result<String> {
        val existingNote = noteId?.let { id ->
            offlineManager?.getNoteById(id)
                ?: loadExistingNoteFromDb(id, context) // pass context param so isPinned/isArchived are preserved
        }
        val now = System.currentTimeMillis()
        val note = (existingNote ?: dataclass()).copy(
            title = title.trim(),
            description = description.trim(),
            id = noteId ?: existingNote?.id ?: dataclass().id,
            mymobiledeviceid = DeviceManager.getOrCreateDeviceId(context),
            timestamp = existingNote?.timestamp ?: now,
            updatedAt = now,
            category = category ?: existingNote?.category.orEmpty(),
            // Explicitly preserve pin/archive state so editing never silently resets them
            isPinned = existingNote?.isPinned ?: false,
            isArchived = existingNote?.isArchived ?: false
        )
        // Ensure note carries the current device id

        // ALWAYS save to Room database first (offline-first)
        val manager = offlineManager ?: return Result.failure(Exception("No context available"))
        val offlineResult = manager.saveNoteOffline(note)

        if (offlineResult.isFailure) {
            Log.e(TAG, "Failed to save note offline: ${offlineResult.exceptionOrNull()?.message}")
            return offlineResult
        }

        Log.d(TAG, "Note saved offline successfully: ${note.id}")

        // Try to sync to cloud in background if online
        val networkManager = NetworkManager.getInstance(context)
        if (networkManager.isConnected()) {
            try {
                val encryptedNote = note.toEncryptedData()
                resolveNotesRef().child(note.id).setValue(encryptedNote).await()
                Log.d(TAG, "Note synced to cloud successfully: ${note.id}")

                // Mark as synced in local database
                offlineManager.markNoteAsSynced(note.id)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to sync note to cloud (will retry later): ${e.message}")
                // Note is still saved offline, so this is acceptable
            }
        } else {
            Log.d(TAG, "Offline mode - note will sync when connection is restored")
        }

        return Result.success(note.id)
    }

    private suspend fun loadExistingNoteFromDb(noteId: String, override: Context? = null): dataclass? = withContext(Dispatchers.IO) {
        val ctx = override ?: context ?: return@withContext null
        AppDatabase.getInstance(ctx)
            .noteDao()
            .getNoteById(noteId)
            ?.let(NoteEntityMapper::toDomain)
    }

    /**
     * Load a note by ID - OFFLINE FIRST
     * Always loads from Room database first
     */
    suspend fun loadNote(noteId: String, context: Context? = null): Result<dataclass> {
        Log.d(TAG, "Loading note with ID: $noteId")

        // Always try offline storage first (offline-first)
        val manager = offlineManager
        if (manager != null) {
            try {
                Log.d(TAG, "Attempting to load note from offline storage: $noteId")
                val offlineNote = manager.getNoteById(noteId)
                if (offlineNote != null) {
                    Log.d(TAG, "Note loaded successfully from offline storage: $noteId")
                    return Result.success(offlineNote)
                } else {
                    Log.w(TAG, "Note NOT found in offline storage: $noteId")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error accessing offline storage for note: $noteId", e)
            }
        } else {
            Log.w(TAG, "No context/offlineManager available for offline storage access")
        }

        // Fallback to online storage only if not found offline and online
        val networkManager = context?.let { NetworkManager.getInstance(it) }
        val isOnline = networkManager?.isConnected() == true

        if (isOnline) {
            Log.d(TAG, "Attempting to load note from cloud: $noteId")
            return try {
                val snapshot = resolveNotesRef().child(noteId).get().await()
                if (snapshot.exists()) {
                    val encryptedNote = snapshot.getValue(dataclass::class.java)
                    if (encryptedNote != null) {
                        val decryptedNote = dataclass.fromEncryptedData(encryptedNote)
                        Log.d(TAG, "Note loaded from cloud: $noteId")

                        // Save to offline storage for future access
                        try {
                            offlineManager?.saveNoteOffline(decryptedNote, synced = true)
                        } catch (e: Exception) {
                            Log.w(TAG, "Failed to cache note offline: ${e.message}")
                        }

                        Result.success(decryptedNote)
                    } else {
                        Result.failure(Exception("Note data is null"))
                    }
                } else {
                    Result.failure(Exception("Note not found in cloud"))
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to load note from cloud: ${e.message}", e)
                Result.failure(e)
            }
        } else {
            return Result.failure(Exception("Note not found offline and device is offline. Please check your internet connection or ensure the note exists locally."))
        }
    }

    /**
     * Delete a note by ID - OFFLINE FIRST
     */
    suspend fun deleteNote(noteId: String, context: Context): Result<String> {
        // Always delete from offline storage first
        val manager = offlineManager ?: return Result.failure(Exception("No context available"))
        val offlineResult = manager.deleteNoteOffline(noteId)

        if (offlineResult.isFailure) {
            Log.e(TAG, "Failed to delete note offline: ${offlineResult.exceptionOrNull()?.message}")
            return offlineResult
        }

        Log.d(TAG, "Note deleted offline successfully: $noteId")

        // Try to delete from cloud if online
        val networkManager = NetworkManager.getInstance(context)
        if (networkManager.isConnected()) {
            try {
                resolveNotesRef().child(noteId).removeValue().await()
                Log.d(TAG, "Note deleted from cloud successfully: $noteId")

                // Mark deletion as synced (remove from pending deletions)
                offlineManager.markDeletionAsSynced(noteId)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to delete note from cloud (will retry later): ${e.message}")
                // Note is already deleted offline and marked for sync, which is acceptable
            }
        } else {
            Log.d(TAG, "Offline mode - note deleted locally and will sync deletion when online")
        }

        return Result.success(noteId)
    }

    /**
     * Get all notes - OFFLINE FIRST
     * Always loads from Room database for immediate display
     */
    suspend fun fetchNotes(): Result<List<dataclass>> {
        return try {
            // ALWAYS load from offline storage first for immediate display
            val manager = offlineManager
            if (manager != null) {
                val offlineNotes = manager.getAllNotes()
                Log.d(TAG, "Loaded ${offlineNotes.size} notes from offline storage")

                // Background sync from cloud if online
                val ctx = context!!
                val networkManager = NetworkManager.getInstance(ctx)
                if (networkManager.isConnected()) {
                    try {
                        syncFromCloudInBackground(manager)
                    } catch (e: Exception) {
                        Log.e(TAG, "Error in background cloud sync", e)
                    }
                }

                Result.success(offlineNotes)
            } else {
                Result.failure(Exception("No context available"))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to fetch notes: ${e.message}", e)
            Result.failure(e)
        }
    }

    /**
     * Background sync from cloud to update local database.
     * Handles pending deletions first, then downloads cloud data.
     * Uses timestamp-based conflict resolution: local edits (newer) win over cloud (older).
     *
     * Skips the cloud-download phase if the "fresh_start" preference flag is set — that
     * flag is written by the Start Fresh flow to prevent old Firebase notes from being
     * pulled back during the very first fetchNotes() call after the wipe.
     */
    private suspend fun syncFromCloudInBackground(offlineManager: OfflineNoteManager) {
        try {
            Log.d(TAG, "Starting background sync from cloud...")

            // FIRST: Process pending deletions before downloading from cloud
            val pendingDeletions = offlineManager.getPendingDeletions()
            Log.d(TAG, "Found ${pendingDeletions.size} pending deletions to process")

            pendingDeletions.forEach { pendingDeletion ->
                try {
                    resolveNotesRef().child(pendingDeletion.noteId).removeValue().await()
                    offlineManager.markDeletionAsSynced(pendingDeletion.noteId)
                    Log.d(TAG, "Successfully deleted from Firebase: ${pendingDeletion.noteId}")
                } catch (e: Exception) {
                    Log.e(TAG, "Failed to delete from Firebase: ${pendingDeletion.noteId}", e)
                }
            }

            // SECOND: Get current local notes to check for conflicts
            // IMPORTANT: Use getAllNotesIncludingArchived() so archived notes appear in the map.
            // Without this, archived notes are invisible and cloud data overwrites them with isArchived=false.
            val localNotes = offlineManager.getAllNotesIncludingArchived()
            val localNoteMap = localNotes.associateBy { it.id }
            val pendingDeletionIds = pendingDeletions.map { it.noteId }.toSet()

            // Also get pending (unsynced) note IDs — these represent local edits that should NOT be overwritten
            val pendingSyncNotes = offlineManager.getPendingSyncNotes()
            val pendingSyncIds = pendingSyncNotes.map { it.id }.toSet()

            // THIRD: Download from Firebase
            // Skip this phase once after a Start Fresh — the flag was set to prevent old
            // Firebase notes (which may not have been fully deleted yet on slow connections)
            // from being pulled back into local storage immediately after the wipe.
            val ctx = context
            val skipFlag = ctx?.getSharedPreferences(PREFS_SYNC, Context.MODE_PRIVATE)
                ?.getBoolean(KEY_SKIP_CLOUD_PULL, false) ?: false
            if (skipFlag) {
                // Clear the flag so normal sync resumes on the next call
                ctx?.getSharedPreferences(PREFS_SYNC, Context.MODE_PRIVATE)
                    ?.edit { putBoolean(KEY_SKIP_CLOUD_PULL, false) }
                Log.i(TAG, "Skipping cloud-download phase (Start Fresh flag set) — local is authoritative")
                return
            }

            val snapshot = resolveNotesRef().get().await()
            val cloudNotes = mutableListOf<dataclass>()
            // Track every note ID present in the cloud snapshot (regardless of whether
            // it passes the conflict-resolution filters below). This set drives
            // remote-deletion reconciliation in Phase FIFTH — a note that exists locally
            // but is NOT in this set must have been deleted from Firebase by another
            // device, so we mirror that deletion locally.
            val cloudNoteIds = mutableSetOf<String>()

            snapshot.children.forEach { childSnapshot ->
                try {
                    val encryptedNote = childSnapshot.getValue(dataclass::class.java)
                    if (encryptedNote != null) {
                        val decryptedNote = dataclass.fromEncryptedData(encryptedNote)

                        // GUARD: Drop blank / failed-decrypt notes and actively purge them
                        // from Firebase so they stop spreading to other devices on next sync.
                        if (decryptedNote.isBlank() || decryptedNote.isDecryptFailed()) {
                            Log.w(TAG, "Purging blank/failed cloud note ${childSnapshot.key} from Firebase")
                            try {
                                childSnapshot.ref.removeValue()
                            } catch (e: Exception) {
                                Log.w(TAG, "Failed to purge blank cloud note: ${e.message}")
                            }
                            return@forEach
                        }

                        // Record the cloud ID BEFORE any skip checks — it exists in cloud,
                        // so it must not be reconciled as a remote deletion.
                        cloudNoteIds.add(decryptedNote.id)

                        // Skip cloud notes that are pending local deletion
                        if (pendingDeletionIds.contains(decryptedNote.id)) {
                            Log.d(TAG, "Skipping cloud note ${decryptedNote.id} - pending deletion")
                            return@forEach
                        }

                        // CONFLICT RESOLUTION: If note exists locally with pending changes,
                        // keep the local version (last-write-wins by user intent).
                        // The local pending change will be uploaded on next sync.
                        if (pendingSyncIds.contains(decryptedNote.id)) {
                            Log.d(TAG, "Skipping cloud note ${decryptedNote.id} - local pending edit takes priority")
                            return@forEach
                        }

                        // Timestamp-based conflict resolution for synced notes:
                        // Only overwrite if cloud is newer than local
                        val localNote = localNoteMap[decryptedNote.id]
                        if (localNote != null && localNote.timestamp > decryptedNote.timestamp) {
                            Log.d(TAG, "Skipping cloud note ${decryptedNote.id} - local is newer (${localNote.timestamp} > ${decryptedNote.timestamp})")
                            return@forEach
                        }

                        cloudNotes.add(decryptedNote)
                    }
                } catch (e: Exception) {
                    Log.e(TAG, "Error decrypting note: ${childSnapshot.key}", e)
                }
            }

            // FOURTH: Update local database with cloud notes that passed conflict checks
            // IMPORTANT: Preserve local pin/archive/category state during cloud sync.
            // These are user-intent fields that should never be overwritten by stale cloud data.
            cloudNotes.forEach { note ->
                val localNote = localNoteMap[note.id]
                val mergedNote = if (localNote != null) {
                    // Preserve local pin/archive/category - they may have been updated locally
                    // but not yet synced to cloud (race condition protection)
                    note.copy(
                        isPinned = localNote.isPinned,
                        isArchived = localNote.isArchived,
                        category = localNote.category.ifBlank { note.category },
                        colorKey = localNote.colorKey ?: note.colorKey
                    )
                } else {
                    note
                }
                offlineManager.saveNoteOffline(mergedNote, synced = true)
            }

            Log.d(TAG, "Background sync completed: ${cloudNotes.size} notes from cloud, ${pendingDeletions.size} deletions processed")
        } catch (e: Exception) {
            Log.w(TAG, "Background sync from cloud failed: ${e.message}")
        }
    }

    /**
     * Sync offline notes and deletions to Firebase.
     * Protected by syncMutex to prevent concurrent sync operations.
     * Each item is synced individually — if app crashes mid-sync, already-synced items
     * are safely marked, and remaining items will retry on next sync (idempotent).
     */
    suspend fun syncOfflineNotes(context: Context): Result<String> = withContext(Dispatchers.IO) {
        syncMutex.withLock {
            val manager = offlineManager ?: return@withContext Result.failure(Exception("No context"))
            val pendingNotes = manager.getPendingSyncNotes()
            val pendingDeletions = manager.getPendingDeletions()

            if (pendingNotes.isEmpty() && pendingDeletions.isEmpty()) {
                return@withContext Result.success("No changes to sync")
            }

            return@withContext try {
                var syncedNotesCount = 0
                var syncedDeletionsCount = 0

                // Sync pending note additions/updates — each marked as synced immediately after success
                // This ensures crash between items doesn't re-sync already completed ones
                pendingNotes.forEach { note ->
                    try {
                        // GUARD: never upload blank/failed notes. Mark them synced anyway so they
                        // don't keep retrying; also purge from Firebase in case a stale copy exists.
                        if (note.isBlank() || note.isDecryptFailed()) {
                            Log.w(TAG, "Skipping upload of blank/failed note ${note.id}; purging from Firebase")
                            try { resolveNotesRef().child(note.id).removeValue().await() } catch (_: Exception) {}
                            offlineManager.markNoteAsSynced(note.id)
                            return@forEach
                        }
                        val encryptedNote = note.toEncryptedData()
                        resolveNotesRef().child(note.id).setValue(encryptedNote).await()
                        // Mark immediately after successful upload — crash-safe
                        offlineManager.markNoteAsSynced(note.id)
                        syncedNotesCount++
                        Log.d(TAG, "Synced note to cloud: ${note.id}")
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to sync note: ${note.id}", e)
                        // Continue with next note — don't fail entire batch
                    }
                }

                // Sync pending deletions — each cleared immediately after success
                pendingDeletions.forEach { pendingDeletion ->
                    try {
                        resolveNotesRef().child(pendingDeletion.noteId).removeValue().await()
                        // Mark immediately after successful deletion — crash-safe
                        offlineManager.markDeletionAsSynced(pendingDeletion.noteId)
                        syncedDeletionsCount++
                        Log.d(TAG, "Synced deletion to cloud: ${pendingDeletion.noteId}")
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to sync deletion: ${pendingDeletion.noteId}", e)
                        // Continue with next deletion — don't fail entire batch
                    }
                }

                val resultMessage = buildString {
                    if (syncedNotesCount > 0) {
                        append("Synced $syncedNotesCount note${if (syncedNotesCount != 1) "s" else ""}")
                    }
                    if (syncedDeletionsCount > 0) {
                        if (syncedNotesCount > 0) append(" and ")
                        append("deleted $syncedDeletionsCount note${if (syncedDeletionsCount != 1) "s" else ""}")
                    }
                }

                Log.d(TAG, "Sync completed: $resultMessage")
                Result.success(resultMessage)
            } catch (e: Exception) {
                Log.e(TAG, "Sync failed: ${e.message}", e)
                Result.failure(e)
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.repository

import android.content.Context
import android.util.Log
import androidx.core.content.edit
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.isBlank
import com.amvarpvtltd.swiftNote.isDecryptFailed
import com.amvarpvtltd.swiftNote.offline.OfflineNoteManager
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import com.amvarpvtltd.swiftNote.utils.NetworkManager
import com.google.firebase.database.DatabaseReference
import com.google.firebase.database.FirebaseDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext

class NoteRepository(val context: Context? = null) {
    private val database = FirebaseDatabase.getInstance()
    // BUG-018 FIX: Cache OfflineNoteManager instance — avoids re-creating per call
    private val offlineManager: OfflineNoteManager? = context?.let { OfflineNoteManager(it) }

    companion object {
        private const val TAG = "NoteRepository"
        // Mutex to prevent concurrent sync operations from colliding
        private val syncMutex = Mutex()

        // BUG-040 FIX: Singleton instance to avoid redundant repository/manager creation
        @Volatile
        private var INSTANCE: NoteRepository? = null

        fun getInstance(context: Context): NoteRepository {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: NoteRepository(context.applicationContext).also { INSTANCE = it }
            }
        }

        /**
         * SharedPreferences key written by the Start Fresh flow.
         * When present-and-true, [syncFromCloudInBackground] skips the cloud-download step once
         * so that old Firebase notes cannot be pulled back immediately after a wipe.
         */
        private const val PREFS_SYNC = "note_repo_prefs"
        private const val KEY_SKIP_CLOUD_PULL = "skip_cloud_pull_once"

        /** Call from the Start Fresh handler (after wipe, before navigation). */
        fun markSkipNextCloudPull(context: Context) {
            context.getSharedPreferences(PREFS_SYNC, Context.MODE_PRIVATE)
                .edit { putBoolean(KEY_SKIP_CLOUD_PULL, true) }
        }
    }

    /**
     * Resolve the Firebase path for notes:
     * users/{accountId}/notes/{deviceId}
     * accountId = stored passphrase if present, otherwise deviceId
     */
    private fun resolveNotesRef(): DatabaseReference {
        val ctx = context ?: throw IllegalStateException("Context required to resolve notesRef")
        val deviceId = DeviceManager.getOrCreateDeviceId(ctx)
        val accountId = PassphraseManager.getStoredPassphrase(ctx).takeIf { !it.isNullOrEmpty() } ?: deviceId
        return database.getReference("users").child(accountId).child("notes").child(deviceId)
    }

    /**
     * Observe all notes reactively via Room Flow.
     * The list updates automatically when the database changes.
     */
    fun observeNotes(): Flow<List<dataclass>> {
        require(context != null) { "No context available for observeNotes" }
        val db = AppDatabase.getInstance(context)
        return db.noteDao().observeAllNotes()
            .map { entities -> entities.map { NoteEntityMapper.toDomain(it) } }
            .flowOn(Dispatchers.IO)
    }

    /**
     * Observe archived notes reactively via Room Flow.
     */
    fun observeArchivedNotes(): Flow<List<dataclass>> {
        require(context != null) { "No context available for observeArchivedNotes" }
        val db = AppDatabase.getInstance(context)
        return db.noteDao().observeArchivedNotes()
            .map { entities -> entities.map { NoteEntityMapper.toDomain(it) } }
            .flowOn(Dispatchers.IO)
    }

    /**
     * Toggle pin status for a note.
     */
    suspend fun togglePin(noteId: String, isPinned: Boolean) = withContext(Dispatchers.IO) {
        val ctx = context ?: return@withContext
        val db = AppDatabase.getInstance(ctx)
        db.noteDao().updatePinStatus(noteId, isPinned)
        // Try to sync updated note to cloud
        syncSingleNote(noteId)
        // Phase 5B: Refresh widget to reflect pin change
        com.amvarpvtltd.swiftNote.widget.WidgetUpdateWorker.refreshNow(ctx)
    }

    /**
     * Toggle archive status for a note.
     */
    suspend fun toggleArchive(noteId: String, isArchived: Boolean) = withContext(Dispatchers.IO) {
        val ctx = context ?: return@withContext
        val db = AppDatabase.getInstance(ctx)
        db.noteDao().updateArchiveStatus(noteId, isArchived)
        syncSingleNote(noteId)
    }

    /**
     * Update category for a note.
     */
    suspend fun updateCategory(noteId: String, category: String) = withContext(Dispatchers.IO) {
        val ctx = context ?: return@withContext
        val db = AppDatabase.getInstance(ctx)
        db.noteDao().updateCategory(noteId, category)
        syncSingleNote(noteId)
    }

    /**
     * Sync a single note to Firebase after local update.
     */
    private suspend fun syncSingleNote(noteId: String) {
        val ctx = context ?: return
        val networkManager = NetworkManager.getInstance(ctx)
        if (networkManager.isConnected()) {
            try {
                val db = AppDatabase.getInstance(ctx)
                val entity = db.noteDao().getNoteById(noteId) ?: return
                val note = NoteEntityMapper.toDomain(entity)
                val encryptedNote = note.toEncryptedData()
                resolveNotesRef().child(noteId).setValue(encryptedNote).await()
                db.noteDao().update(entity.copy(synced = true))
            } catch (e: Exception) {
                Log.w(TAG, "Failed to sync note $noteId after update: ${e.message}")
            }
        }
    }

    /**
     * Save a new note or update an existing one - OFFLINE FIRST
     * Always saves to Room database first, then attempts cloud sync
     */
    suspend fun saveNote(
        title: String,
        description: String,
        noteId: String? = null,
        context: Context,
        category: String? = null
    ): Result<String> {
        val existingNote = noteId?.let { id ->
            offlineManager?.getNoteById(id)
                ?: loadExistingNoteFromDb(id, context) // pass context param so isPinned/isArchived are preserved
        }
        val now = System.currentTimeMillis()
        val note = (existingNote ?: dataclass()).copy(
            title = title.trim(),
            description = description.trim(),
            id = noteId ?: existingNote?.id ?: dataclass().id,
            mymobiledeviceid = DeviceManager.getOrCreateDeviceId(context),
            timestamp = existingNote?.timestamp ?: now,
            updatedAt = now,
            category = category ?: existingNote?.category.orEmpty(),
            // Explicitly preserve pin/archive state so editing never silently resets them
            isPinned = existingNote?.isPinned ?: false,
            isArchived = existingNote?.isArchived ?: false
        )
        // Ensure note carries the current device id

        // ALWAYS save to Room database first (offline-first)
        val manager = offlineManager ?: return Result.failure(Exception("No context available"))
        val offlineResult = manager.saveNoteOffline(note)

        if (offlineResult.isFailure) {
            Log.e(TAG, "Failed to save note offline: ${offlineResult.exceptionOrNull()?.message}")
            return offlineResult
        }

        Log.d(TAG, "Note saved offline successfully: ${note.id}")

        // Try to sync to cloud in background if online
        val networkManager = NetworkManager.getInstance(context)
        if (networkManager.isConnected()) {
            try {
                val encryptedNote = note.toEncryptedData()
                resolveNotesRef().child(note.id).setValue(encryptedNote).await()
                Log.d(TAG, "Note synced to cloud successfully: ${note.id}")

                // Mark as synced in local database
                offlineManager.markNoteAsSynced(note.id)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to sync note to cloud (will retry later): ${e.message}")
                // Note is still saved offline, so this is acceptable
            }
        } else {
            Log.d(TAG, "Offline mode - note will sync when connection is restored")
        }

        return Result.success(note.id)
    }

    private suspend fun loadExistingNoteFromDb(noteId: String, override: Context? = null): dataclass? = withContext(Dispatchers.IO) {
        val ctx = override ?: context ?: return@withContext null
        AppDatabase.getInstance(ctx)
            .noteDao()
            .getNoteById(noteId)
            ?.let(NoteEntityMapper::toDomain)
    }

    /**
     * Load a note by ID - OFFLINE FIRST
     * Always loads from Room database first
     */
    suspend fun loadNote(noteId: String, context: Context? = null): Result<dataclass> {
        Log.d(TAG, "Loading note with ID: $noteId")

        // Always try offline storage first (offline-first)
        val manager = offlineManager
        if (manager != null) {
            try {
                Log.d(TAG, "Attempting to load note from offline storage: $noteId")
                val offlineNote = manager.getNoteById(noteId)
                if (offlineNote != null) {
                    Log.d(TAG, "Note loaded successfully from offline storage: $noteId")
                    return Result.success(offlineNote)
                } else {
                    Log.w(TAG, "Note NOT found in offline storage: $noteId")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error accessing offline storage for note: $noteId", e)
            }
        } else {
            Log.w(TAG, "No context/offlineManager available for offline storage access")
        }

        // Fallback to online storage only if not found offline and online
        val networkManager = context?.let { NetworkManager.getInstance(it) }
        val isOnline = networkManager?.isConnected() == true

        if (isOnline) {
            Log.d(TAG, "Attempting to load note from cloud: $noteId")
            return try {
                val snapshot = resolveNotesRef().child(noteId).get().await()
                if (snapshot.exists()) {
                    val encryptedNote = snapshot.getValue(dataclass::class.java)
                    if (encryptedNote != null) {
                        val decryptedNote = dataclass.fromEncryptedData(encryptedNote)
                        Log.d(TAG, "Note loaded from cloud: $noteId")

                        // Save to offline storage for future access
                        try {
                            offlineManager?.saveNoteOffline(decryptedNote, synced = true)
                        } catch (e: Exception) {
                            Log.w(TAG, "Failed to cache note offline: ${e.message}")
                        }

                        Result.success(decryptedNote)
                    } else {
                        Result.failure(Exception("Note data is null"))
                    }
                } else {
                    Result.failure(Exception("Note not found in cloud"))
                }
            } catch (e: Exception) {
                Log.e(TAG, "Failed to load note from cloud: ${e.message}", e)
                Result.failure(e)
            }
        } else {
            return Result.failure(Exception("Note not found offline and device is offline. Please check your internet connection or ensure the note exists locally."))
        }
    }

    /**
     * Delete a note by ID - OFFLINE FIRST
     */
    suspend fun deleteNote(noteId: String, context: Context): Result<String> {
        // Always delete from offline storage first
        val manager = offlineManager ?: return Result.failure(Exception("No context available"))
        val offlineResult = manager.deleteNoteOffline(noteId)

        if (offlineResult.isFailure) {
            Log.e(TAG, "Failed to delete note offline: ${offlineResult.exceptionOrNull()?.message}")
            return offlineResult
        }

        Log.d(TAG, "Note deleted offline successfully: $noteId")

        // Try to delete from cloud if online
        val networkManager = NetworkManager.getInstance(context)
        if (networkManager.isConnected()) {
            try {
                resolveNotesRef().child(noteId).removeValue().await()
                Log.d(TAG, "Note deleted from cloud successfully: $noteId")

                // Mark deletion as synced (remove from pending deletions)
                offlineManager.markDeletionAsSynced(noteId)
            } catch (e: Exception) {
                Log.w(TAG, "Failed to delete note from cloud (will retry later): ${e.message}")
                // Note is already deleted offline and marked for sync, which is acceptable
            }
        } else {
            Log.d(TAG, "Offline mode - note deleted locally and will sync deletion when online")
        }

        return Result.success(noteId)
    }

    /**
     * Get all notes - OFFLINE FIRST
     * Always loads from Room database for immediate display
     */
    suspend fun fetchNotes(): Result<List<dataclass>> {
        return try {
            // ALWAYS load from offline storage first for immediate display
            val manager = offlineManager
            if (manager != null) {
                val offlineNotes = manager.getAllNotes()
                Log.d(TAG, "Loaded ${offlineNotes.size} notes from offline storage")

                // Background sync from cloud if online
                val ctx = context!!
                val networkManager = NetworkManager.getInstance(ctx)
                if (networkManager.isConnected()) {
                    try {
                        syncFromCloudInBackground(manager)
                    } catch (e: Exception) {
                        Log.e(TAG, "Error in background cloud sync", e)
                    }
                }

                Result.success(offlineNotes)
            } else {
                Result.failure(Exception("No context available"))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Failed to fetch notes: ${e.message}", e)
            Result.failure(e)
        }
    }

    /**
     * Background sync from cloud to update local database.
     * Handles pending deletions first, then downloads cloud data.
     * Uses timestamp-based conflict resolution: local edits (newer) win over cloud (older).
     *
     * Skips the cloud-download phase if the "fresh_start" preference flag is set — that
     * flag is written by the Start Fresh flow to prevent old Firebase notes from being
     * pulled back during the very first fetchNotes() call after the wipe.
     */
    private suspend fun syncFromCloudInBackground(offlineManager: OfflineNoteManager) {
        try {
            Log.d(TAG, "Starting background sync from cloud...")

            // FIRST: Process pending deletions before downloading from cloud
            val pendingDeletions = offlineManager.getPendingDeletions()
            Log.d(TAG, "Found ${pendingDeletions.size} pending deletions to process")

            pendingDeletions.forEach { pendingDeletion ->
                try {
                    resolveNotesRef().child(pendingDeletion.noteId).removeValue().await()
                    offlineManager.markDeletionAsSynced(pendingDeletion.noteId)
                    Log.d(TAG, "Successfully deleted from Firebase: ${pendingDeletion.noteId}")
                } catch (e: Exception) {
                    Log.e(TAG, "Failed to delete from Firebase: ${pendingDeletion.noteId}", e)
                }
            }

            // SECOND: Get current local notes to check for conflicts
            // IMPORTANT: Use getAllNotesIncludingArchived() so archived notes appear in the map.
            // Without this, archived notes are invisible and cloud data overwrites them with isArchived=false.
            val localNotes = offlineManager.getAllNotesIncludingArchived()
            val localNoteMap = localNotes.associateBy { it.id }
            val pendingDeletionIds = pendingDeletions.map { it.noteId }.toSet()

            // Also get pending (unsynced) note IDs — these represent local edits that should NOT be overwritten
            val pendingSyncNotes = offlineManager.getPendingSyncNotes()
            val pendingSyncIds = pendingSyncNotes.map { it.id }.toSet()

            // THIRD: Download from Firebase
            // Skip this phase once after a Start Fresh — the flag was set to prevent old
            // Firebase notes (which may not have been fully deleted yet on slow connections)
            // from being pulled back into local storage immediately after the wipe.
            val ctx = context
            val skipFlag = ctx?.getSharedPreferences(PREFS_SYNC, Context.MODE_PRIVATE)
                ?.getBoolean(KEY_SKIP_CLOUD_PULL, false) ?: false
            if (skipFlag) {
                // Clear the flag so normal sync resumes on the next call
                ctx?.getSharedPreferences(PREFS_SYNC, Context.MODE_PRIVATE)
                    ?.edit { putBoolean(KEY_SKIP_CLOUD_PULL, false) }
                Log.i(TAG, "Skipping cloud-download phase (Start Fresh flag set) — local is authoritative")
                return
            }

            val snapshot = resolveNotesRef().get().await()
            val cloudNotes = mutableListOf<dataclass>()
            // Track every note ID present in the cloud snapshot (regardless of whether
            // it passes the conflict-resolution filters below). This set drives
            // remote-deletion reconciliation in Phase FIFTH — a note that exists locally
            // but is NOT in this set must have been deleted from Firebase by another
            // device, so we mirror that deletion locally.
            val cloudNoteIds = mutableSetOf<String>()

            snapshot.children.forEach { childSnapshot ->
                try {
                    val encryptedNote = childSnapshot.getValue(dataclass::class.java)
                    if (encryptedNote != null) {
                        val decryptedNote = dataclass.fromEncryptedData(encryptedNote)

                        // GUARD: Drop blank / failed-decrypt notes and actively purge them
                        // from Firebase so they stop spreading to other devices on next sync.
                        if (decryptedNote.isBlank() || decryptedNote.isDecryptFailed()) {
                            Log.w(TAG, "Purging blank/failed cloud note ${childSnapshot.key} from Firebase")
                            try {
                                childSnapshot.ref.removeValue()
                            } catch (e: Exception) {
                                Log.w(TAG, "Failed to purge blank cloud note: ${e.message}")
                            }
                            return@forEach
                        }

                        // Record the cloud ID BEFORE any skip checks — it exists in cloud,
                        // so it must not be reconciled as a remote deletion.
                        cloudNoteIds.add(decryptedNote.id)

                        // Skip cloud notes that are pending local deletion
                        if (pendingDeletionIds.contains(decryptedNote.id)) {
                            Log.d(TAG, "Skipping cloud note ${decryptedNote.id} - pending deletion")
                            return@forEach
                        }

                        // CONFLICT RESOLUTION: If note exists locally with pending changes,
                        // keep the local version (last-write-wins by user intent).
                        // The local pending change will be uploaded on next sync.
                        if (pendingSyncIds.contains(decryptedNote.id)) {
                            Log.d(TAG, "Skipping cloud note ${decryptedNote.id} - local pending edit takes priority")
                            return@forEach
                        }

                        // Timestamp-based conflict resolution for synced notes:
                        // Only overwrite if cloud is newer than local
                        val localNote = localNoteMap[decryptedNote.id]
                        if (localNote != null && localNote.timestamp > decryptedNote.timestamp) {
                            Log.d(TAG, "Skipping cloud note ${decryptedNote.id} - local is newer (${localNote.timestamp} > ${decryptedNote.timestamp})")
                            return@forEach
                        }

                        cloudNotes.add(decryptedNote)
                    }
                } catch (e: Exception) {
                    Log.e(TAG, "Error decrypting note: ${childSnapshot.key}", e)
                }
            }

            // FOURTH: Update local database with cloud notes that passed conflict checks
            // IMPORTANT: Preserve local pin/archive/category state during cloud sync.
            // These are user-intent fields that should never be overwritten by stale cloud data.
            cloudNotes.forEach { note ->
                val localNote = localNoteMap[note.id]
                val mergedNote = if (localNote != null) {
                    // Preserve local pin/archive/category - they may have been updated locally
                    // but not yet synced to cloud (race condition protection)
                    note.copy(
                        isPinned = localNote.isPinned,
                        isArchived = localNote.isArchived,
                        category = localNote.category.ifBlank { note.category },
                        colorKey = localNote.colorKey ?: note.colorKey
                    )
                } else {
                    note
                }
                offlineManager.saveNoteOffline(mergedNote, synced = true)
            }

            // FIFTH: Reconcile remote deletions.
            // Any local note that was previously synced to cloud (synced=true) but is no
            // longer present in the cloud snapshot must have been deleted from another
            // device. Mirror that deletion locally so the home screen UI stops showing it.
            //
            // Guards:
            //  - Skip notes still pending upload (synced=false) — they may simply not have
            //    been pushed to cloud yet; deleting them would lose user data.
            //  - Skip notes already in the pending-deletion queue (handled in Phase FIRST).
            //  - Skip notes with pending local edits (treated as authoritative above).
            //  - Only run when the cloud snapshot actually had children OR was explicitly
            //    empty — `snapshot.exists()` distinguishes a missing path from an empty one.
            try {
                val cloudPathExists = snapshot.exists() || snapshot.childrenCount == 0L
                if (cloudPathExists) {
                    val pendingSyncIdSet = pendingSyncIds
                    val pendingDeletionIdSet = pendingDeletionIds
                    val localSyncedIds = localNotes
                        .filter { localNote ->
                            // Only consider notes that have been synced to cloud at least once.
                            // We re-query the entity to check `synced` because `dataclass` does
                            // not carry that flag.
                            val entity = try {
                                offlineManager.getNoteById(localNote.id)
                            } catch (_: Exception) { null }
                            entity != null
                        }
                        .map { it.id }
                        .toSet()

                    val staleLocalIds = localSyncedIds
                        .asSequence()
                        .filter { it !in cloudNoteIds }
                        .filter { it !in pendingSyncIdSet }
                        .filter { it !in pendingDeletionIdSet }
                        .toList()

                    if (staleLocalIds.isNotEmpty()) {
                        Log.i(TAG, "Reconciling ${staleLocalIds.size} remote deletion(s) from cloud")
                        staleLocalIds.forEach { staleId ->
                            try {
                                offlineManager.deleteNoteLocalOnly(staleId)
                            } catch (e: Exception) {
                                Log.w(TAG, "Failed to reconcile remote deletion for $staleId", e)
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                Log.w(TAG, "Remote-deletion reconciliation failed: ${e.message}", e)
            }

            Log.d(TAG, "Background sync completed: ${cloudNotes.size} notes from cloud, ${pendingDeletions.size} deletions processed")
        } catch (e: Exception) {
            Log.w(TAG, "Background sync from cloud failed: ${e.message}")
        }
    }

    /**
     * Sync offline notes and deletions to Firebase.
     * Protected by syncMutex to prevent concurrent sync operations.
     * Each item is synced individually — if app crashes mid-sync, already-synced items
     * are safely marked, and remaining items will retry on next sync (idempotent).
     */
    suspend fun syncOfflineNotes(context: Context): Result<String> = withContext(Dispatchers.IO) {
        syncMutex.withLock {
            val manager = offlineManager ?: return@withContext Result.failure(Exception("No context"))
            val pendingNotes = manager.getPendingSyncNotes()
            val pendingDeletions = manager.getPendingDeletions()

            if (pendingNotes.isEmpty() && pendingDeletions.isEmpty()) {
                return@withContext Result.success("No changes to sync")
            }

            return@withContext try {
                var syncedNotesCount = 0
                var syncedDeletionsCount = 0

                // Sync pending note additions/updates — each marked as synced immediately after success
                // This ensures crash between items doesn't re-sync already completed ones
                pendingNotes.forEach { note ->
                    try {
                        // GUARD: never upload blank/failed notes. Mark them synced anyway so they
                        // don't keep retrying; also purge from Firebase in case a stale copy exists.
                        if (note.isBlank() || note.isDecryptFailed()) {
                            Log.w(TAG, "Skipping upload of blank/failed note ${note.id}; purging from Firebase")
                            try { resolveNotesRef().child(note.id).removeValue().await() } catch (_: Exception) {}
                            offlineManager.markNoteAsSynced(note.id)
                            return@forEach
                        }
                        val encryptedNote = note.toEncryptedData()
                        resolveNotesRef().child(note.id).setValue(encryptedNote).await()
                        // Mark immediately after successful upload — crash-safe
                        offlineManager.markNoteAsSynced(note.id)
                        syncedNotesCount++
                        Log.d(TAG, "Synced note to cloud: ${note.id}")
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to sync note: ${note.id}", e)
                        // Continue with next note — don't fail entire batch
                    }
                }

                // Sync pending deletions — each cleared immediately after success
                pendingDeletions.forEach { pendingDeletion ->
                    try {
                        resolveNotesRef().child(pendingDeletion.noteId).removeValue().await()
                        // Mark immediately after successful deletion — crash-safe
                        offlineManager.markDeletionAsSynced(pendingDeletion.noteId)
                        syncedDeletionsCount++
                        Log.d(TAG, "Synced deletion to cloud: ${pendingDeletion.noteId}")
                    } catch (e: Exception) {
                        Log.e(TAG, "Failed to sync deletion: ${pendingDeletion.noteId}", e)
                        // Continue with next deletion — don't fail entire batch
                    }
                }

                val resultMessage = buildString {
                    if (syncedNotesCount > 0) {
                        append("Synced $syncedNotesCount note${if (syncedNotesCount != 1) "s" else ""}")
                    }
                    if (syncedDeletionsCount > 0) {
                        if (syncedNotesCount > 0) append(" and ")
                        append("deleted $syncedDeletionsCount note${if (syncedDeletionsCount != 1) "s" else ""}")
                    }
                }

                Log.d(TAG, "Sync completed: $resultMessage")
                Result.success(resultMessage)
            } catch (e: Exception) {
                Log.e(TAG, "Sync failed: ${e.message}", e)
                Result.failure(e)
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.viewmodel

import android.app.Application
import android.util.Log
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.repository.NoteRepository
import com.amvarpvtltd.swiftNote.sync.SyncManager
import com.amvarpvtltd.swiftNote.utils.AutoSyncManager
import com.amvarpvtltd.swiftNote.utils.Constants
import com.amvarpvtltd.swiftNote.utils.NetworkManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * ViewModel for the Notes list screen.
 * Uses Flow-based reactive observation from Room (Phase 0).
 * Supports undo-delete via pendingDelete state (Phase 0).
 */
class NotesViewModel(application: Application) : AndroidViewModel(application) {

    private val TAG = "NotesViewModel"
    private val context = application.applicationContext

    val noteRepository = NoteRepository.getInstance(context)
    val networkManager = NetworkManager.getInstance(context)
    val autoSyncManager = AutoSyncManager.getInstance(context, noteRepository)

    // Phase 0.3: Flow-based reactive notes from Room — auto-updates on DB changes
    val notes: StateFlow<List<dataclass>> = noteRepository.observeNotes()
        .catch { e ->
            Log.e(TAG, "Error observing notes", e)
            emit(emptyList())
        }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5000),
            initialValue = emptyList()
        )

    private val _isLoading = MutableStateFlow(true)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _isRefreshing = MutableStateFlow(false)
    val isRefreshing: StateFlow<Boolean> = _isRefreshing.asStateFlow()

    // Phase 0.4: Undo-delete support
    private val _pendingDelete = MutableStateFlow<dataclass?>(null)
    val pendingDelete: StateFlow<dataclass?> = _pendingDelete.asStateFlow()
    private var undoDeleteJob: Job? = null

    // One-shot UI events (toasts, navigation) — collected once, never replayed
    private val _uiEvent = MutableSharedFlow<UiEvent>()
    val uiEvent: SharedFlow<UiEvent> = _uiEvent.asSharedFlow()

    sealed class UiEvent {
        data class ShowToast(val message: String) : UiEvent()
        object NavigateToMain : UiEvent()
    }

    init {
        // Initial data load for first-time display + mark loading complete
        viewModelScope.launch {
            // Small delay to allow Flow to emit first value
            delay(Constants.LOADING_DELAY)
            _isLoading.value = false
        }
        startAutoSync()
        attemptOneTimeRemoteImport()
    }

    /**
     * Manually refresh notes from the repository (triggers background cloud sync).
     * The Flow will automatically pick up any changes written to the DB.
     */
    fun refreshNotes() {
        viewModelScope.launch {
            _isRefreshing.value = true
            try {
                // Trigger a fetch which syncs from cloud to local DB
                withContext(Dispatchers.IO) { noteRepository.fetchNotes() }
            } finally {
                _isRefreshing.value = false
            }
        }
    }

    /**
     * Phase 0.4: Delete with undo support.
     * Holds the note for 4 seconds before permanent deletion.
     */
    fun deleteNote(noteId: String) {
        // Find the note in current list to hold for undo
        val noteToDelete = notes.value.find { it.id == noteId }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.deleteNote(noteId, context)
                if (result.isSuccess) {
                    if (noteToDelete != null) {
                        // Set pending delete for undo
                        _pendingDelete.value = noteToDelete
                        // Cancel any previous undo timer
                        undoDeleteJob?.cancel()
                        // Start timer to clear pending state
                        undoDeleteJob = viewModelScope.launch {
                            delay(4000L) // 4 second undo window
                            _pendingDelete.value = null
                        }
                    }
                    if (!networkManager.isConnected()) {
                        _uiEvent.emit(UiEvent.ShowToast(" Note deleted offline. Will sync when online."))
                    }
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast(Constants.ERROR_DELETING_MESSAGE))
            }
        }
    }

    /**
     * Phase 0.4: Undo the last delete.
     * Re-saves the note that was pending deletion.
     */
    fun undoDelete() {
        val note = _pendingDelete.value ?: return
        undoDeleteJob?.cancel()
        _pendingDelete.value = null

        viewModelScope.launch(Dispatchers.IO) {
            try {
                noteRepository.saveNote(
                    title = note.title,
                    description = note.description,
                    noteId = note.id,
                    context = context
                )
            } catch (e: Exception) {
                Log.e(TAG, "Failed to undo delete", e)
                _uiEvent.emit(UiEvent.ShowToast("❌ Failed to restore note"))
            }
        }
    }

    fun syncNotes() {
        if (!networkManager.isConnected()) {
            viewModelScope.launch { _uiEvent.emit(UiEvent.ShowToast("❌ Can't sync while offline")) }
            return
        }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.syncOfflineNotes(context)
                if (result.isSuccess) {
                    _uiEvent.emit(UiEvent.ShowToast("✅ Sync completed"))
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast("❌ Sync failed"))
            }
        }
    }

    private fun startAutoSync() {
        autoSyncManager.startAutoSync()
    }

    fun stopAutoSync() {
        autoSyncManager.stopAutoSync()
    }

    private fun attemptOneTimeRemoteImport() {
        if (!networkManager.isConnected()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val accountId = PassphraseManager.getStoredPassphrase(context)
                    ?: DeviceManager.getOrCreateDeviceId(context)
                val res = SyncManager.syncDataFromPassphrase(context, accountId, accountId)
                if (res.isSuccess) {
                    // Flow will auto-update, no manual refresh needed
                    Log.d(TAG, "One-time remote import succeeded")
                } else {
                    Log.d(TAG, "One-time remote import failed: ${res.exceptionOrNull()?.message}")
                }
            } catch (e: Exception) {
                Log.d(TAG, "One-time remote import failed", e)
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        autoSyncManager.stopAutoSync()
    }
}

