import kotlinx.coroutines.withContext

/**
 * ViewModel for the Notes list screen.
 * Uses Flow-based reactive observation from Room (Phase 0).
 * Supports undo-delete via pendingDelete state (Phase 0).
 */
class NotesViewModel(application: Application) : AndroidViewModel(application) {

    private val TAG = "NotesViewModel"
    private val context = application.applicationContext

    val noteRepository = NoteRepository.getInstance(context)
    val networkManager = NetworkManager.getInstance(context)
    val autoSyncManager = AutoSyncManager.getInstance(context, noteRepository)

    // Phase 0.3: Flow-based reactive notes from Room — always active (Eagerly) so cached
    // data is available instantly on navigation back without Room requery lag
    val notes: StateFlow<List<dataclass>> = noteRepository.observeNotes()
        .catch { e ->
            Log.e(TAG, "Error observing notes", e)
            emit(emptyList())
        }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.Eagerly, // never stops — keeps data hot for instant nav-back
            initialValue = emptyList()
        )

    private val _isLoading = MutableStateFlow(true)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    private val _isRefreshing = MutableStateFlow(false)
    val isRefreshing: StateFlow<Boolean> = _isRefreshing.asStateFlow()

    // Phase 0.4: Undo-delete support
    private val _pendingDelete = MutableStateFlow<dataclass?>(null)
    val pendingDelete: StateFlow<dataclass?> = _pendingDelete.asStateFlow()
    private var undoDeleteJob: Job? = null

    // One-shot UI events (toasts, navigation) — collected once, never replayed
    private val _uiEvent = MutableSharedFlow<UiEvent>()
    val uiEvent: SharedFlow<UiEvent> = _uiEvent.asSharedFlow()

    sealed class UiEvent {
        data class ShowToast(val message: String) : UiEvent()
        object NavigateToMain : UiEvent()
    }

    init {
        // Initial data load for first-time display + mark loading complete
        viewModelScope.launch {
            // Small delay to allow Flow to emit first value
            delay(Constants.LOADING_DELAY)
            _isLoading.value = false
        }
        startAutoSync()
        attemptOneTimeRemoteImport()
    }

    /**
     * Manually refresh notes from the repository (triggers background cloud sync).
     * The Flow will automatically pick up any changes written to the DB.
     */
    fun refreshNotes() {
        viewModelScope.launch {
            _isRefreshing.value = true
            try {
                // Trigger a fetch which syncs from cloud to local DB
                withContext(Dispatchers.IO) { noteRepository.fetchNotes() }
            } finally {
                _isRefreshing.value = false
            }
        }
    }

    /**
     * Phase 0.4: Delete with undo support.
     * Holds the note for 4 seconds before permanent deletion.
     */
    fun deleteNote(noteId: String) {
        // Find the note in current list to hold for undo
        val noteToDelete = notes.value.find { it.id == noteId }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.deleteNote(noteId, context)
                if (result.isSuccess) {
                    if (noteToDelete != null) {
                        // Set pending delete for undo
                        _pendingDelete.value = noteToDelete
                        // Cancel any previous undo timer
                        undoDeleteJob?.cancel()
                        // Start timer to clear pending state
                        undoDeleteJob = viewModelScope.launch {
                            delay(4000L) // 4 second undo window
                            _pendingDelete.value = null
                        }
                    }
                    if (!networkManager.isConnected()) {
                        _uiEvent.emit(UiEvent.ShowToast(" Note deleted offline. Will sync when online."))
                    }
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast(Constants.ERROR_DELETING_MESSAGE))
            }
        }
    }

    /**
     * Phase 0.4: Undo the last delete.
     * Re-saves the note that was pending deletion.
     */
    fun undoDelete() {
        val note = _pendingDelete.value ?: return
        undoDeleteJob?.cancel()
        _pendingDelete.value = null

        viewModelScope.launch(Dispatchers.IO) {
            try {
                noteRepository.saveNote(
                    title = note.title,
                    description = note.description,
                    noteId = note.id,
                    context = context
                )
            } catch (e: Exception) {
                Log.e(TAG, "Failed to undo delete", e)
                _uiEvent.emit(UiEvent.ShowToast("❌ Failed to restore note"))
            }
        }
    }

    fun syncNotes() {
        if (!networkManager.isConnected()) {
            viewModelScope.launch { _uiEvent.emit(UiEvent.ShowToast("❌ Can't sync while offline")) }
            return
        }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val result = noteRepository.syncOfflineNotes(context)
                if (result.isSuccess) {
                    _uiEvent.emit(UiEvent.ShowToast("✅ Sync completed"))
                }
            } catch (e: Exception) {
                _uiEvent.emit(UiEvent.ShowToast("❌ Sync failed"))
            }
        }
    }

    private fun startAutoSync() {
        autoSyncManager.startAutoSync()
    }

    fun stopAutoSync() {
        autoSyncManager.stopAutoSync()
    }

    private fun attemptOneTimeRemoteImport() {
        if (!networkManager.isConnected()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val accountId = PassphraseManager.getStoredPassphrase(context)
                    ?: DeviceManager.getOrCreateDeviceId(context)
                val res = SyncManager.syncDataFromPassphrase(context, accountId, accountId)
                if (res.isSuccess) {
                    // Flow will auto-update, no manual refresh needed
                    Log.d(TAG, "One-time remote import succeeded")
                } else {
                    Log.d(TAG, "One-time remote import failed: ${res.exceptionOrNull()?.message}")
                }
            } catch (e: Exception) {
                Log.d(TAG, "One-time remote import failed", e)
            }
        }
    }

    override fun onCleared() {
        super.onCleared()
        autoSyncManager.stopAutoSync()
    }
}

package com.amvarpvtltd.swiftNote.components

import androidx.compose.animation.*
import androidx.compose.animation.core.*
import androidx.compose.animation.togetherWith
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.outlined.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.amvarpvtltd.swiftNote.design.NoteTheme
import com.amvarpvtltd.swiftNote.utils.Constants
import kotlinx.coroutines.delay
import com.amvarpvtltd.swiftNote.utils.rememberResponsiveDimensions

@OptIn(ExperimentalAnimationApi::class)
@Composable
fun OfflineEmptyStateCard(
    isOnline: Boolean,
    hasPendingSync: Boolean,
    onCreateNoteClick: () -> Unit,
    onSeedDemoClick: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val dims = rememberResponsiveDimensions()
    var showPulse by remember { mutableStateOf(true) }

    // Animated pulse effect for offline indicator
    val pulseAlpha by animateFloatAsState(
        targetValue = if (showPulse && !isOnline) 0.3f else 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = EaseInOutCubic),
            repeatMode = RepeatMode.Reverse
        ),
        label = "pulse_alpha"
    )

    LaunchedEffect(isOnline) {
        if (!isOnline) {
            while (!isOnline) {
                showPulse = true
                delay(1000)
                showPulse = false
                delay(1000)
            }
        } else {
            showPulse = false
        }
    }

    // Derived responsive sizes — keep card components visually consistent
    // across width buckets (COMPACT / MEDIUM / EXPANDED) AND across phones of
    // different physical heights within the same bucket. All hardcoded dp/sp
    // values below were causing layout overflow on shorter screens (e.g.
    // 384x854 vs 412x912 — both fall in MEDIUM so they used identical dims,
    // but the fixed 120/48/56/32 values left no room for the status row).
    val statusIndicatorSize = dims.iconLarge * 5       // 100 / 120 / 140
    val statusIndicatorIcon = dims.iconLarge * 2       //  40 /  48 /  56
    val primaryButtonHeight = dims.fabSize             //  56 /  64 /  72
    val secondaryButtonHeight = dims.fabSize - 8.dp    //  48 /  56 /  64
    val cardElevation = dims.paddingSmall              //   6 /   8 /  10
    val cardInnerPadding = dims.paddingLarge           //  18 /  24 /  32 (was paddingXL — too generous on compact)
    val sectionSpacing = dims.paddingMedium            //  12 /  15 /  20 (was paddingLarge — gave bottom row no room)

    Box(
        modifier = modifier
            .fillMaxSize()
            .padding(dims.paddingMedium),
        contentAlignment = Alignment.Center
    ) {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(dims.paddingSmall),
            colors = CardDefaults.cardColors(
                containerColor = if (isOnline) NoteTheme.Surface else NoteTheme.Surface.copy(alpha = 0.95f)
            ),
            shape = RoundedCornerShape(dims.cornerXL),
            elevation = CardDefaults.cardElevation(defaultElevation = cardElevation)
        ) {
            Column(
                modifier = Modifier
                    .padding(cardInnerPadding)
                    .fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(sectionSpacing)
            ) {
                // Status indicator with icon
                Box(
                    modifier = Modifier
                        .size(statusIndicatorSize)
                        .background(
                            brush = Brush.radialGradient(
                                colors = if (isOnline) {
                                    listOf(
                                        NoteTheme.Success.copy(alpha = 0.2f),
                                        NoteTheme.Success.copy(alpha = 0.05f)
                                    )
                                } else {
                                    listOf(
                                        NoteTheme.Warning.copy(alpha = pulseAlpha),
                                        NoteTheme.Warning.copy(alpha = 0.05f)
                                    )
                                }
                            ),
                            shape = CircleShape
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = if (isOnline) {
                            if (hasPendingSync) Icons.Outlined.CloudSync else Icons.Outlined.CloudDone
                        } else {
                            Icons.Outlined.CloudOff
                        },
                        contentDescription = null,
                        tint = if (isOnline) {
                            if (hasPendingSync) NoteTheme.Primary else NoteTheme.Success
                        } else {
                            NoteTheme.Warning
                        },
                        modifier = Modifier.size(statusIndicatorIcon)
                    )
                }

                // Title and status message
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                ) {
                    Text(
                        text = if (isOnline) {
                            if (hasPendingSync) "Syncing Notes" else "No Notes Yet"
                        } else {
                            "You're Offline"
                        },
                        style = MaterialTheme.typography.headlineMedium.copy(
                            fontSize = dims.scaledSp(24)
                        ),
                        fontWeight = FontWeight.Bold,
                        color = NoteTheme.OnSurface,
                        textAlign = TextAlign.Center,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis
                    )

                    AnimatedContent(
                        targetState = Pair(isOnline, hasPendingSync),
                        transitionSpec = {
                            (slideInVertically { it } + fadeIn()).togetherWith(slideOutVertically { -it } + fadeOut())
                        },
                        label = "status_message"
                    ) { (online, syncing) ->
                        Text(
                            text = when {
                                !online -> "Your notes are saved locally and will sync automatically when you're back online"
                                syncing -> "Your notes are being synchronized with the cloud"
                                else -> "Create your first note to capture your thoughts and ideas"
                            },
                            style = MaterialTheme.typography.bodyLarge.copy(
                                fontSize = dims.scaledSp(15)
                            ),
                            color = NoteTheme.OnSurfaceVariant,
                            textAlign = TextAlign.Center,
                            lineHeight = dims.scaledSp(22)
                        )
                    }
                }

                // Action buttons
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                ) {
                    // Primary action button
                    Button(
                        onClick = onCreateNoteClick,
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(min = primaryButtonHeight),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = NoteTheme.Primary,
                            contentColor = NoteTheme.OnPrimary
                        ),
                        shape = RoundedCornerShape(dims.cornerLarge),
                        elevation = ButtonDefaults.buttonElevation(defaultElevation = 4.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Add,
                            contentDescription = null,
                            modifier = Modifier.size(dims.iconLarge)
                        )
                        Spacer(modifier = Modifier.width(dims.paddingSmall))
                        Text(
                            text = if (isOnline) "Create First Note" else "Create Note Offline",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.titleMedium.copy(
                                fontSize = dims.scaledSp(16)
                            ),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    // Demo data button – only shown when there are no notes
                    if (onSeedDemoClick != null) {
                        OutlinedButton(
                            onClick = onSeedDemoClick,
                            modifier = Modifier
                                .fillMaxWidth()
                                .heightIn(min = secondaryButtonHeight),
                            colors = ButtonDefaults.outlinedButtonColors(
                                contentColor = NoteTheme.Primary
                            ),
                            border = androidx.compose.foundation.BorderStroke(
                                1.dp,
                                NoteTheme.Primary.copy(alpha = 0.5f)
                            ),
                            shape = RoundedCornerShape(dims.cornerLarge)
                        ) {
                            Icon(
                                imageVector = Icons.Outlined.AutoAwesome,
                                contentDescription = null,
                                modifier = Modifier.size(dims.iconMedium)
                            )
                            Spacer(modifier = Modifier.width(dims.paddingSmall))
                            Text(
                                text = "Load Demo Notes",
                                fontWeight = FontWeight.Medium,
                                style = MaterialTheme.typography.titleSmall
                            )
                        }
                    }

                    // Status information. Always shown on the empty state so
                    // the card layout stays stable across sync states — only
                    // the icon/colour/label vary. Avoids the jarring "shape
                    // shift" between "Syncing Notes" and "No Notes Yet".
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(dims.paddingSmall),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        val statusIcon = when {
                            !isOnline -> Icons.Outlined.WifiOff
                            hasPendingSync -> Icons.Outlined.CloudSync
                            else -> Icons.Outlined.CloudDone
                        }
                        val statusTint = when {
                            !isOnline -> NoteTheme.Warning
                            hasPendingSync -> NoteTheme.Primary
                            else -> NoteTheme.Success
                        }
                        val statusLabel = when {
                            !isOnline -> "Working offline"
                            hasPendingSync -> "Syncing in background"
                            else -> "Auto-sync is active"
                        }
                        Icon(
                            imageVector = statusIcon,
                            contentDescription = null,
                            tint = statusTint,
                            modifier = Modifier.size(dims.iconSmall)
                        )
                        Text(
                            text = statusLabel,
                            style = MaterialTheme.typography.labelMedium,
                            color = statusTint,
                            fontWeight = FontWeight.Medium,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }

                // Offline features info
                if (!isOnline) {
                    Card(
                        colors = CardDefaults.cardColors(
                            containerColor = NoteTheme.SurfaceVariant.copy(alpha = 0.5f)
                        ),
                        shape = RoundedCornerShape(dims.cornerMedium)
                    ) {
                        Column(
                            modifier = Modifier.padding(dims.paddingMedium),
                            verticalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                        ) {
                            Text(
                                text = "Offline Features Available:",
                                style = MaterialTheme.typography.labelLarge,
                                fontWeight = FontWeight.SemiBold,
                                color = NoteTheme.OnSurface
                            )

                            listOf(
                                "Create and edit notes",
                                "Delete existing notes",
                                "Search through notes",
                                "Auto-sync when online"
                            ).forEach { feature ->
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.Check,
                                        contentDescription = null,
                                        tint = NoteTheme.Success,
                                        modifier = Modifier.size(dims.iconSmall)
                                    )
                                    Text(
                                        text = feature,
                                        style = MaterialTheme.typography.bodySmall,
                                        color = NoteTheme.OnSurfaceVariant
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.components

import androidx.compose.animation.*
import androidx.compose.animation.core.*
import androidx.compose.animation.togetherWith
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.outlined.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.amvarpvtltd.swiftNote.design.NoteTheme
import com.amvarpvtltd.swiftNote.utils.Constants
import kotlinx.coroutines.delay
import com.amvarpvtltd.swiftNote.utils.rememberResponsiveDimensions

@OptIn(ExperimentalAnimationApi::class)
@Composable
fun OfflineEmptyStateCard(
    isOnline: Boolean,
    hasPendingSync: Boolean,
    onCreateNoteClick: () -> Unit,
    onSeedDemoClick: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val dims = rememberResponsiveDimensions()
    var showPulse by remember { mutableStateOf(true) }

    // Animated pulse effect for offline indicator
    val pulseAlpha by animateFloatAsState(
        targetValue = if (showPulse && !isOnline) 0.3f else 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = EaseInOutCubic),
            repeatMode = RepeatMode.Reverse
        ),
        label = "pulse_alpha"
    )

    LaunchedEffect(isOnline) {
        if (!isOnline) {
            while (!isOnline) {
                showPulse = true
                delay(1000)
                showPulse = false
                delay(1000)
            }
        } else {
            showPulse = false
        }
    }

    // Derived responsive sizes — keep card components visually consistent
    // across width buckets (COMPACT / MEDIUM / EXPANDED) AND across phones of
    // different physical heights within the same bucket. All hardcoded dp/sp
    // values below were causing layout overflow on shorter screens (e.g.
    // 384x854 vs 412x912 — both fall in MEDIUM so they used identical dims,
    // but the fixed 120/48/56/32 values left no room for the status row).
    val statusIndicatorSize = dims.iconLarge * 5       // 100 / 120 / 140
    val statusIndicatorIcon = dims.iconLarge * 2       //  40 /  48 /  56
    val primaryButtonHeight = dims.fabSize             //  56 /  64 /  72
    val secondaryButtonHeight = dims.fabSize - 8.dp    //  48 /  56 /  64
    val cardElevation = dims.paddingSmall              //   6 /   8 /  10
    val cardInnerPadding = dims.paddingLarge           //  18 /  24 /  32 (was paddingXL — too generous on compact)
    val sectionSpacing = dims.paddingMedium            //  12 /  15 /  20 (was paddingLarge — gave bottom row no room)

    Box(
        modifier = modifier
            .fillMaxSize()
            .padding(dims.paddingMedium),
        contentAlignment = Alignment.Center
    ) {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(dims.paddingSmall),
            colors = CardDefaults.cardColors(
                containerColor = if (isOnline) NoteTheme.Surface else NoteTheme.Surface.copy(alpha = 0.95f)
            ),
            shape = RoundedCornerShape(dims.cornerXL),
            elevation = CardDefaults.cardElevation(defaultElevation = cardElevation)
        ) {
            Column(
                modifier = Modifier
                    .padding(cardInnerPadding)
                    .fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(sectionSpacing)
            ) {
                // Status indicator with icon
                Box(
                    modifier = Modifier
                        .size(statusIndicatorSize)
                        .background(
                            brush = Brush.radialGradient(
                                colors = if (isOnline) {
                                    listOf(
                                        NoteTheme.Success.copy(alpha = 0.2f),
                                        NoteTheme.Success.copy(alpha = 0.05f)
                                    )
                                } else {
                                    listOf(
                                        NoteTheme.Warning.copy(alpha = pulseAlpha),
                                        NoteTheme.Warning.copy(alpha = 0.05f)
                                    )
                                }
                            ),
                            shape = CircleShape
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = if (isOnline) {
                            if (hasPendingSync) Icons.Outlined.CloudSync else Icons.Outlined.CloudDone
                        } else {
                            Icons.Outlined.CloudOff
                        },
                        contentDescription = null,
                        tint = if (isOnline) {
                            if (hasPendingSync) NoteTheme.Primary else NoteTheme.Success
                        } else {
                            NoteTheme.Warning
                        },
                        modifier = Modifier.size(statusIndicatorIcon)
                    )
                }

                // Title and status message
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                ) {
                    Text(
                        text = if (isOnline) {
                            if (hasPendingSync) "Syncing Notes" else "No Notes Yet"
                        } else {
                            "You're Offline"
                        },
                        style = MaterialTheme.typography.headlineMedium.copy(
                            fontSize = dims.scaledSp(24)
                        ),
                        fontWeight = FontWeight.Bold,
                        color = NoteTheme.OnSurface,
                        textAlign = TextAlign.Center,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis
                    )

                    AnimatedContent(
                        targetState = Pair(isOnline, hasPendingSync),
                        transitionSpec = {
                            (slideInVertically { it } + fadeIn()).togetherWith(slideOutVertically { -it } + fadeOut())
                        },
                        label = "status_message"
                    ) { (online, syncing) ->
                        Text(
                            text = when {
                                !online -> "Your notes are saved locally and will sync automatically when you're back online"
                                syncing -> "Your notes are being synchronized with the cloud"
                                else -> "Create your first note to capture your thoughts and ideas"
                            },
                            style = MaterialTheme.typography.bodyLarge.copy(
                                fontSize = dims.scaledSp(15)
                            ),
                            color = NoteTheme.OnSurfaceVariant,
                            textAlign = TextAlign.Center,
                            lineHeight = dims.scaledSp(22)
                        )
                    }
                }

                // Action buttons
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                ) {
                    // Primary action button
                    Button(
                        onClick = onCreateNoteClick,
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(min = primaryButtonHeight),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = NoteTheme.Primary,
                            contentColor = NoteTheme.OnPrimary
                        ),
                        shape = RoundedCornerShape(dims.cornerLarge),
                        elevation = ButtonDefaults.buttonElevation(defaultElevation = 4.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Add,
                            contentDescription = null,
                            modifier = Modifier.size(dims.iconLarge)
                        )
                        Spacer(modifier = Modifier.width(dims.paddingSmall))
                        Text(
                            text = if (isOnline) "Create First Note" else "Create Note Offline",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.titleMedium.copy(
                                fontSize = dims.scaledSp(16)
                            ),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    // Demo data button – only shown when there are no notes
                    if (onSeedDemoClick != null) {
                        OutlinedButton(
                            onClick = onSeedDemoClick,
                            modifier = Modifier
                                .fillMaxWidth()
                                .heightIn(min = secondaryButtonHeight),
                            colors = ButtonDefaults.outlinedButtonColors(
                                contentColor = NoteTheme.Primary
                            ),
                            border = androidx.compose.foundation.BorderStroke(
                                1.dp,
                                NoteTheme.Primary.copy(alpha = 0.5f)
                            ),
                            shape = RoundedCornerShape(dims.cornerLarge)
                        ) {
                            Icon(
                                imageVector = Icons.Outlined.AutoAwesome,
                                contentDescription = null,
                                modifier = Modifier.size(dims.iconMedium)
                            )
                            Spacer(modifier = Modifier.width(dims.paddingSmall))
                            Text(
                                text = "Load Demo Notes",
                                fontWeight = FontWeight.Medium,
                                style = MaterialTheme.typography.titleSmall.copy(
                                    fontSize = dims.scaledSp(14)
                                )
                            )
                        }
                    }

                    // Status information. Always shown on the empty state so
                    // the card layout stays stable across sync states — only
                    // the icon/colour/label vary. Avoids the jarring "shape
                    // shift" between "Syncing Notes" and "No Notes Yet".
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(dims.paddingSmall),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        val statusIcon = when {
                            !isOnline -> Icons.Outlined.WifiOff
                            hasPendingSync -> Icons.Outlined.CloudSync
                            else -> Icons.Outlined.CloudDone
                        }
                        val statusTint = when {
                            !isOnline -> NoteTheme.Warning
                            hasPendingSync -> NoteTheme.Primary
                            else -> NoteTheme.Success
                        }
                        val statusLabel = when {
                            !isOnline -> "Working offline"
                            hasPendingSync -> "Syncing in background"
                            else -> "Auto-sync is active"
                        }
                        Icon(
                            imageVector = statusIcon,
                            contentDescription = null,
                            tint = statusTint,
                            modifier = Modifier.size(dims.iconSmall)
                        )
                        Text(
                            text = statusLabel,
                            style = MaterialTheme.typography.labelMedium,
                            color = statusTint,
                            fontWeight = FontWeight.Medium,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }

                // Offline features info
                if (!isOnline) {
                    Card(
                        colors = CardDefaults.cardColors(
                            containerColor = NoteTheme.SurfaceVariant.copy(alpha = 0.5f)
                        ),
                        shape = RoundedCornerShape(dims.cornerMedium)
                    ) {
                        Column(
                            modifier = Modifier.padding(dims.paddingMedium),
                            verticalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                        ) {
                            Text(
                                text = "Offline Features Available:",
                                style = MaterialTheme.typography.labelLarge,
                                fontWeight = FontWeight.SemiBold,
                                color = NoteTheme.OnSurface
                            )

                            listOf(
                                "Create and edit notes",
                                "Delete existing notes",
                                "Search through notes",
                                "Auto-sync when online"
                            ).forEach { feature ->
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(dims.paddingSmall)
                                ) {
                                    Icon(
                                        imageVector = Icons.Outlined.Check,
                                        contentDescription = null,
                                        tint = NoteTheme.Success,
                                        modifier = Modifier.size(dims.iconSmall)
                                    )
                                    Text(
                                        text = feature,
                                        style = MaterialTheme.typography.bodySmall,
                                        color = NoteTheme.OnSurfaceVariant
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.offline

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.isBlank
import com.amvarpvtltd.swiftNote.isDecryptFailed
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import com.amvarpvtltd.swiftNote.room.PendingDeletionEntity
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class OfflineNoteManager(context: Context) {
    private val TAG = "OfflineNoteManager"
    private val db = AppDatabase.getInstance(context.applicationContext)
    private val noteDao = db.noteDao()
    private val pendingDeletionDao = db.pendingDeletionDao()
    private val reminderDao = db.reminderDao()

    private val _offlineNotes = MutableStateFlow<List<dataclass>>(emptyList())
    val offlineNotes: StateFlow<List<dataclass>> = _offlineNotes.asStateFlow()

    private val _pendingSyncNotes = MutableStateFlow<List<dataclass>>(emptyList())
    val pendingSyncNotes: StateFlow<List<dataclass>> = _pendingSyncNotes.asStateFlow()

    private val _pendingDeletions = MutableStateFlow<List<PendingDeletionEntity>>(emptyList())
    val pendingDeletions: StateFlow<List<PendingDeletionEntity>> = _pendingDeletions.asStateFlow()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in OfflineNoteManager scope", exception)
    }
    // BUG-014 FIX: Named scope with SupervisorJob — can be cancelled via close()
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler)

    init {
        managerScope.launch {
            refreshLocalNotes()
            refreshPendingNotes()
            refreshPendingDeletions()
        }
    }

    /**
     * BUG-014 FIX: Cancel the internal scope to prevent coroutine leaks.
     * Call this when the manager is no longer needed.
     */
    fun close() {
        managerScope.cancel()
    }

    suspend fun saveNoteOffline(note: dataclass, synced: Boolean = false): Result<String> {
        // Last-line defence: refuse to persist blank or failed-decrypt notes. Sync paths
        // already filter these, but this guard ensures no future code path can introduce
        // blank notes into Room (the root cause of "many blank notes appear after sync").
        if (note.isBlank() || note.isDecryptFailed()) {
            Log.w(TAG, "Refusing to save blank/failed note ${note.id} (synced=$synced)")
            return Result.failure(IllegalArgumentException("Cannot save blank or failed-decrypt note"))
        }
        return try {
            withContext(Dispatchers.IO) {
                val entity = NoteEntityMapper.toEntity(note, synced)
                noteDao.insert(entity)
            }
            refreshLocalNotes()
            refreshPendingNotes()
            Log.d(TAG, "Note saved offline: ${note.id} (synced: $synced)")
            Result.success("Note saved offline successfully")
        } catch (e: Exception) {
            Log.e(TAG, "Error saving note offline", e)
            Result.failure(e)
        }
    }

    suspend fun deleteNoteOffline(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                // BUG-039 FIX: Use Room transaction to atomically delete note + record pending deletion
                // Prevents race where note is deleted but pending deletion is not recorded
                db.runInTransaction {
                    val noteEntity = noteDao.getNoteById(noteId)
                    if (noteEntity != null) {
                        // Delete the note from local storage
                        noteDao.delete(noteEntity)

                        // Add to pending deletions for Firebase sync (atomic with delete)
                        val pendingDeletion = PendingDeletionEntity(
                            noteId = noteId,
                            mymobiledeviceid = noteEntity.mymobiledeviceid
                        )
                        pendingDeletionDao.insert(pendingDeletion)

                        Log.d(TAG, "Note deleted offline and marked for Firebase deletion: $noteId")
                    } else {
                        Log.w(TAG, "Note not found for deletion: $noteId")
                    }
                }

                // BUG-013 FIX: Clean up orphan reminders (outside transaction — suspend function)
                try {
                    reminderDao.deleteRemindersForNote(noteId)
                } catch (e: Exception) {
                    Log.w(TAG, "Failed to clean up reminders for note: $noteId", e)
                }
            }
            refreshLocalNotes()
            refreshPendingNotes()
            refreshPendingDeletions()
            Result.success("Note deleted offline successfully")
        } catch (e: Exception) {
            Log.e(TAG, "Error deleting note offline", e)
            Result.failure(e)
        }
    }

    suspend fun getNoteById(noteId: String): dataclass? {
        return try {
            Log.d(TAG, "Attempting to get note by ID: $noteId")

            // Ensure we're running on IO dispatcher for database operations
            val entity = withContext(Dispatchers.IO) {
                noteDao.getNoteById(noteId)
            }

            if (entity != null) {
                Log.d(TAG, "Found note entity in database: $noteId")
                val domainNote = NoteEntityMapper.toDomain(entity)
                Log.d(TAG, "Successfully converted entity to domain object: ${domainNote.title}")
                domainNote
            } else {
                Log.w(TAG, "No note found in database for ID: $noteId")

                // Debug: Check if any notes exist in database
                val allNotes = withContext(Dispatchers.IO) {
                    noteDao.getAllNotes()
                }
                Log.d(TAG, "Total notes in database: ${allNotes.size}")
                allNotes.forEach { note ->
                    Log.d(TAG, "Available note ID: ${note.id}")
                }

                null
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting note by ID: $noteId", e)
            null
        }
    }

    suspend fun getAllNotes(): List<dataclass> {
        return try {
            withContext(Dispatchers.IO) {
                val entities = noteDao.getAllNotes()
                entities.map { NoteEntityMapper.toDomain(it) }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting all notes", e)
            emptyList()
        }
    }

    /**
     * Get ALL notes including archived — used for sync conflict resolution.
     * Without this, archived notes are invisible to the sync map and get overwritten by stale cloud data.
     */
    suspend fun getAllNotesIncludingArchived(): List<dataclass> {
        return try {
            withContext(Dispatchers.IO) {
                val entities = noteDao.getAllNotesIncludingArchived()
                entities.map { NoteEntityMapper.toDomain(it) }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting all notes including archived", e)
            emptyList()
        }
    }

    suspend fun getPendingSyncNotes(): List<dataclass> {
        return try {
            withContext(Dispatchers.IO) {
                val pending = noteDao.getPendingNotes()
                pending.map { NoteEntityMapper.toDomain(it) }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting pending sync notes", e)
            emptyList()
        }
    }

    suspend fun getPendingDeletions(): List<PendingDeletionEntity> {
        return try {
            withContext(Dispatchers.IO) {
                pendingDeletionDao.getAllPendingDeletions()
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting pending deletions", e)
            emptyList()
        }
    }

    suspend fun markNoteAsSynced(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                val entity = noteDao.getNoteById(noteId)
                if (entity != null) {
                    val syncedEntity = entity.copy(synced = true)
                    noteDao.update(syncedEntity)
                    Log.d(TAG, "Note marked as synced: $noteId")
                } else {
                    Log.w(TAG, "Note not found for sync marking: $noteId")
                    return@withContext Result.failure<String>(Exception("Note not found"))
                }
            }
            refreshPendingNotes()
            Result.success("Note marked as synced")
        } catch (e: Exception) {
            Log.e(TAG, "Error marking note as synced: $noteId", e)
            Result.failure(e)
        }
    }

    suspend fun markDeletionAsSynced(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                val removedCount = pendingDeletionDao.removePendingDeletion(noteId)
                if (removedCount > 0) {
                    Log.d(TAG, "Pending deletion removed for synced note: $noteId")
                } else {
                    Log.w(TAG, "No pending deletion found for note: $noteId")
                }
            }
            refreshPendingDeletions()
            Result.success("Deletion marked as synced")
        } catch (e: Exception) {
            Log.e(TAG, "Error marking deletion as synced: $noteId", e)
            Result.failure(e)
        }
    }

    fun hasPendingSync(): Boolean = pendingSyncNotes.value.isNotEmpty() || pendingDeletions.value.isNotEmpty()

    private suspend fun refreshLocalNotes() {
        try {
            withContext(Dispatchers.IO) {
                val entities = noteDao.getAllNotes()
                _offlineNotes.value = entities.map { NoteEntityMapper.toDomain(it) }
                Log.d(TAG, "Refreshed local notes: ${entities.size}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error refreshing local notes", e)
        }
    }

    private suspend fun refreshPendingNotes() {
        try {
            withContext(Dispatchers.IO) {
                val pending = noteDao.getPendingNotes()
                _pendingSyncNotes.value = pending.map { NoteEntityMapper.toDomain(it) }
                Log.d(TAG, "Refreshed pending sync notes: ${pending.size}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error refreshing pending notes", e)
        }
    }

    private suspend fun refreshPendingDeletions() {
        try {
            withContext(Dispatchers.IO) {
                val pendingDeletions = pendingDeletionDao.getAllPendingDeletions()
                _pendingDeletions.value = pendingDeletions
                Log.d(TAG, "Refreshed pending deletions: ${pendingDeletions.size}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error refreshing pending deletions", e)
        }
    }

    fun clearSyncedNotes() {
        managerScope.launch {
            try {
                val pending = noteDao.getPendingNotes()
                pending.forEach { noteDao.update(it.copy(synced = true)) }
                refreshPendingNotes()
                Log.d(TAG, "Cleared synced notes from pending list")
            } catch (e: Exception) {
                Log.e(TAG, "Error clearing synced notes", e)
            }
        }
    }

    // Reassign all local notes to a new deviceId and mark them pending sync
    suspend fun reassignDeviceId(newDeviceId: String) {
        withContext(Dispatchers.IO) {
            val all = noteDao.getAllNotes()
            all.forEach { entity ->
                val updated = entity.copy(mymobiledeviceid = newDeviceId, synced = false)
                noteDao.update(updated)
            }
        }
        refreshLocalNotes()
        refreshPendingNotes()
        Log.d(TAG, "Reassigned ${offlineNotes.value.size} notes to new deviceId")
    }
}

package com.amvarpvtltd.swiftNote.offline

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.isBlank
import com.amvarpvtltd.swiftNote.isDecryptFailed
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import com.amvarpvtltd.swiftNote.room.PendingDeletionEntity
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class OfflineNoteManager(context: Context) {
    private val TAG = "OfflineNoteManager"
    private val db = AppDatabase.getInstance(context.applicationContext)
    private val noteDao = db.noteDao()
    private val pendingDeletionDao = db.pendingDeletionDao()
    private val reminderDao = db.reminderDao()

    private val _offlineNotes = MutableStateFlow<List<dataclass>>(emptyList())
    val offlineNotes: StateFlow<List<dataclass>> = _offlineNotes.asStateFlow()

    private val _pendingSyncNotes = MutableStateFlow<List<dataclass>>(emptyList())
    val pendingSyncNotes: StateFlow<List<dataclass>> = _pendingSyncNotes.asStateFlow()

    private val _pendingDeletions = MutableStateFlow<List<PendingDeletionEntity>>(emptyList())
    val pendingDeletions: StateFlow<List<PendingDeletionEntity>> = _pendingDeletions.asStateFlow()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in OfflineNoteManager scope", exception)
    }
    // BUG-014 FIX: Named scope with SupervisorJob — can be cancelled via close()
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler)

    init {
        managerScope.launch {
            refreshLocalNotes()
            refreshPendingNotes()
            refreshPendingDeletions()
        }
    }

    /**
     * BUG-014 FIX: Cancel the internal scope to prevent coroutine leaks.
     * Call this when the manager is no longer needed.
     */
    fun close() {
        managerScope.cancel()
    }

    suspend fun saveNoteOffline(note: dataclass, synced: Boolean = false): Result<String> {
        // Last-line defence: refuse to persist blank or failed-decrypt notes. Sync paths
        // already filter these, but this guard ensures no future code path can introduce
        // blank notes into Room (the root cause of "many blank notes appear after sync").
        if (note.isBlank() || note.isDecryptFailed()) {
            Log.w(TAG, "Refusing to save blank/failed note ${note.id} (synced=$synced)")
            return Result.failure(IllegalArgumentException("Cannot save blank or failed-decrypt note"))
        }
        return try {
            withContext(Dispatchers.IO) {
                val entity = NoteEntityMapper.toEntity(note, synced)
                noteDao.insert(entity)
            }
            refreshLocalNotes()
            refreshPendingNotes()
            Log.d(TAG, "Note saved offline: ${note.id} (synced: $synced)")
            Result.success("Note saved offline successfully")
        } catch (e: Exception) {
            Log.e(TAG, "Error saving note offline", e)
            Result.failure(e)
        }
    }

    suspend fun deleteNoteOffline(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                // BUG-039 FIX: Use Room transaction to atomically delete note + record pending deletion
                // Prevents race where note is deleted but pending deletion is not recorded
                db.runInTransaction {
                    val noteEntity = noteDao.getNoteById(noteId)
                    if (noteEntity != null) {
                        // Delete the note from local storage
                        noteDao.delete(noteEntity)

                        // Add to pending deletions for Firebase sync (atomic with delete)
                        val pendingDeletion = PendingDeletionEntity(
                            noteId = noteId,
                            mymobiledeviceid = noteEntity.mymobiledeviceid
                        )
                        pendingDeletionDao.insert(pendingDeletion)

                        Log.d(TAG, "Note deleted offline and marked for Firebase deletion: $noteId")
                    } else {
                        Log.w(TAG, "Note not found for deletion: $noteId")
                    }
                }

                // BUG-013 FIX: Clean up orphan reminders (outside transaction — suspend function)
                try {
                    reminderDao.deleteRemindersForNote(noteId)
                } catch (e: Exception) {
                    Log.w(TAG, "Failed to clean up reminders for note: $noteId", e)
                }
            }
            refreshLocalNotes()
            refreshPendingNotes()
            refreshPendingDeletions()
            Result.success("Note deleted offline successfully")
        } catch (e: Exception) {
            Log.e(TAG, "Error deleting note offline", e)
            Result.failure(e)
        }
    }

    /**
     * Delete a note from the local Room database WITHOUT enqueuing a pending Firebase deletion.
     *
     * Use this ONLY for remote-deletion reconciliation — i.e. when the cloud snapshot tells us
     * the note no longer exists in Firebase (was deleted from another device), so we must mirror
     * that deletion locally. We must NOT add a PendingDeletionEntity here, otherwise the next
     * sync would try to re-delete a node that's already gone (no-op but noisy) and, worse, could
     * propagate spurious deletions across devices in edge cases.
     *
     * Also cleans up any orphan reminders for the note.
     */
    suspend fun deleteNoteLocalOnly(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                val noteEntity = noteDao.getNoteById(noteId)
                if (noteEntity != null) {
                    noteDao.delete(noteEntity)
                    Log.d(TAG, "Note deleted locally (remote-reconciled, no Firebase push): $noteId")
                } else {
                    Log.w(TAG, "Note not found for local-only deletion: $noteId")
                }
                try {
                    reminderDao.deleteRemindersForNote(noteId)
                } catch (e: Exception) {
                    Log.w(TAG, "Failed to clean up reminders for reconciled note: $noteId", e)
                }
            }
            refreshLocalNotes()
            refreshPendingNotes()
            Result.success("Note reconciled (deleted locally)")
        } catch (e: Exception) {
            Log.e(TAG, "Error deleting note locally for reconciliation: $noteId", e)
            Result.failure(e)
        }
    }

    suspend fun getNoteById(noteId: String): dataclass? {
        return try {
            Log.d(TAG, "Attempting to get note by ID: $noteId")

            // Ensure we're running on IO dispatcher for database operations
            val entity = withContext(Dispatchers.IO) {
                noteDao.getNoteById(noteId)
            }

            if (entity != null) {
                Log.d(TAG, "Found note entity in database: $noteId")
                val domainNote = NoteEntityMapper.toDomain(entity)
                Log.d(TAG, "Successfully converted entity to domain object: ${domainNote.title}")
                domainNote
            } else {
                Log.w(TAG, "No note found in database for ID: $noteId")

                // Debug: Check if any notes exist in database
                val allNotes = withContext(Dispatchers.IO) {
                    noteDao.getAllNotes()
                }
                Log.d(TAG, "Total notes in database: ${allNotes.size}")
                allNotes.forEach { note ->
                    Log.d(TAG, "Available note ID: ${note.id}")
                }

                null
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting note by ID: $noteId", e)
            null
        }
    }

    suspend fun getAllNotes(): List<dataclass> {
        return try {
            withContext(Dispatchers.IO) {
                val entities = noteDao.getAllNotes()
                entities.map { NoteEntityMapper.toDomain(it) }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting all notes", e)
            emptyList()
        }
    }

    /**
     * Get ALL notes including archived — used for sync conflict resolution.
     * Without this, archived notes are invisible to the sync map and get overwritten by stale cloud data.
     */
    suspend fun getAllNotesIncludingArchived(): List<dataclass> {
        return try {
            withContext(Dispatchers.IO) {
                val entities = noteDao.getAllNotesIncludingArchived()
                entities.map { NoteEntityMapper.toDomain(it) }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting all notes including archived", e)
            emptyList()
        }
    }

    suspend fun getPendingSyncNotes(): List<dataclass> {
        return try {
            withContext(Dispatchers.IO) {
                val pending = noteDao.getPendingNotes()
                pending.map { NoteEntityMapper.toDomain(it) }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting pending sync notes", e)
            emptyList()
        }
    }

    suspend fun getPendingDeletions(): List<PendingDeletionEntity> {
        return try {
            withContext(Dispatchers.IO) {
                pendingDeletionDao.getAllPendingDeletions()
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error getting pending deletions", e)
            emptyList()
        }
    }

    suspend fun markNoteAsSynced(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                val entity = noteDao.getNoteById(noteId)
                if (entity != null) {
                    val syncedEntity = entity.copy(synced = true)
                    noteDao.update(syncedEntity)
                    Log.d(TAG, "Note marked as synced: $noteId")
                } else {
                    Log.w(TAG, "Note not found for sync marking: $noteId")
                    return@withContext Result.failure<String>(Exception("Note not found"))
                }
            }
            refreshPendingNotes()
            Result.success("Note marked as synced")
        } catch (e: Exception) {
            Log.e(TAG, "Error marking note as synced: $noteId", e)
            Result.failure(e)
        }
    }

    suspend fun markDeletionAsSynced(noteId: String): Result<String> {
        return try {
            withContext(Dispatchers.IO) {
                val removedCount = pendingDeletionDao.removePendingDeletion(noteId)
                if (removedCount > 0) {
                    Log.d(TAG, "Pending deletion removed for synced note: $noteId")
                } else {
                    Log.w(TAG, "No pending deletion found for note: $noteId")
                }
            }
            refreshPendingDeletions()
            Result.success("Deletion marked as synced")
        } catch (e: Exception) {
            Log.e(TAG, "Error marking deletion as synced: $noteId", e)
            Result.failure(e)
        }
    }

    fun hasPendingSync(): Boolean = pendingSyncNotes.value.isNotEmpty() || pendingDeletions.value.isNotEmpty()

    private suspend fun refreshLocalNotes() {
        try {
            withContext(Dispatchers.IO) {
                val entities = noteDao.getAllNotes()
                _offlineNotes.value = entities.map { NoteEntityMapper.toDomain(it) }
                Log.d(TAG, "Refreshed local notes: ${entities.size}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error refreshing local notes", e)
        }
    }

    private suspend fun refreshPendingNotes() {
        try {
            withContext(Dispatchers.IO) {
                val pending = noteDao.getPendingNotes()
                _pendingSyncNotes.value = pending.map { NoteEntityMapper.toDomain(it) }
                Log.d(TAG, "Refreshed pending sync notes: ${pending.size}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error refreshing pending notes", e)
        }
    }

    private suspend fun refreshPendingDeletions() {
        try {
            withContext(Dispatchers.IO) {
                val pendingDeletions = pendingDeletionDao.getAllPendingDeletions()
                _pendingDeletions.value = pendingDeletions
                Log.d(TAG, "Refreshed pending deletions: ${pendingDeletions.size}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error refreshing pending deletions", e)
        }
    }

    fun clearSyncedNotes() {
        managerScope.launch {
            try {
                val pending = noteDao.getPendingNotes()
                pending.forEach { noteDao.update(it.copy(synced = true)) }
                refreshPendingNotes()
                Log.d(TAG, "Cleared synced notes from pending list")
            } catch (e: Exception) {
                Log.e(TAG, "Error clearing synced notes", e)
            }
        }
    }

    // Reassign all local notes to a new deviceId and mark them pending sync
    suspend fun reassignDeviceId(newDeviceId: String) {
        withContext(Dispatchers.IO) {
            val all = noteDao.getAllNotes()
            all.forEach { entity ->
                val updated = entity.copy(mymobiledeviceid = newDeviceId, synced = false)
                noteDao.update(updated)
            }
        }
        refreshLocalNotes()
        refreshPendingNotes()
        Log.d(TAG, "Reassigned ${offlineNotes.value.size} notes to new deviceId")
    }
}

package com.amvarpvtltd.swiftNote.offline

import android.content.Context
import androidx.room.Room
import com.amvarpvtltd.swiftNote.Note
import com.amvarpvtltd.swiftNote.myGlobalMobileDeviceId
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntity
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.runTest
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

/**
 * Unit tests for OfflineNoteManager covering:
 * - BUG-014: Init doesn't leak coroutines
 * - BUG-039: Delete + pending deletion is atomic
 * - Basic CRUD operations
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [31], manifest = Config.NONE)
@OptIn(ExperimentalCoroutinesApi::class)
class OfflineNoteManagerTest {

    private lateinit var context: Context
    private lateinit var manager: OfflineNoteManager

    @Before
    fun setUp() {
        context = RuntimeEnvironment.getApplication()
        myGlobalMobileDeviceId = "test-device-offline"
        manager = OfflineNoteManager(context)
    }

    @After
    fun tearDown() {
        manager.close()
    }

    // ============================================================
    // Save Tests
    // ============================================================

    @Test
    fun `saveNoteOffline returns success`() = runTest {
        val note = Note(title = "Test Note", description = "Test Description", mymobiledeviceid = "test-device-offline")
        val result = manager.saveNoteOffline(note)
        assertTrue(result.isSuccess)
    }

    @Test
    fun `saved note can be retrieved by ID`() = runTest {
        val note = Note(title = "Findable", description = "Description", id = "find-me", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note)
        val retrieved = manager.getNoteById("find-me")
        assertNotNull(retrieved)
        assertEquals("find-me", retrieved!!.id)
    }

    @Test
    fun `getAllNotes returns saved notes`() = runTest {
        val note1 = Note(title = "Note 1", description = "Desc 1", id = "id-1", mymobiledeviceid = "test-device-offline")
        val note2 = Note(title = "Note 2", description = "Desc 2", id = "id-2", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note1)
        manager.saveNoteOffline(note2)

        val all = manager.getAllNotes()
        assertTrue(all.size >= 2)
    }

    // ============================================================
    // Delete Tests (BUG-039: Atomic delete + pending)
    // ============================================================

    @Test
    fun `deleteNoteOffline removes note from local storage`() = runTest {
        val note = Note(title = "Delete Me", description = "Desc", id = "del-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note)

        val result = manager.deleteNoteOffline("del-1")
        assertTrue(result.isSuccess)

        val retrieved = manager.getNoteById("del-1")
        assertNull(retrieved)
    }

    @Test
    fun `deleteNoteOffline records pending deletion for sync`() = runTest {
        val note = Note(title = "Delete Me", description = "Desc", id = "del-2", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note)
        manager.deleteNoteOffline("del-2")

        val pendingDeletions = manager.getPendingDeletions()
        assertTrue(pendingDeletions.any { it.noteId == "del-2" })
    }

    @Test
    fun `deleteNoteOffline for non-existent note returns success`() = runTest {
        val result = manager.deleteNoteOffline("non-existent-id")
        assertTrue(result.isSuccess) // Should not crash
    }

    // ============================================================
    // Sync State Tests
    // ============================================================

    @Test
    fun `saveNoteOffline with synced false creates pending sync`() = runTest {
        val note = Note(title = "Pending", description = "Desc", id = "pending-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note, synced = false)

        val pending = manager.getPendingSyncNotes()
        assertTrue(pending.any { it.id == "pending-1" })
    }

    @Test
    fun `saveNoteOffline with synced true does not create pending sync`() = runTest {
        val note = Note(title = "Synced", description = "Desc", id = "synced-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note, synced = true)

        val pending = manager.getPendingSyncNotes()
        assertFalse(pending.any { it.id == "synced-1" })
    }

    @Test
    fun `markNoteAsSynced removes from pending`() = runTest {
        val note = Note(title = "Mark", description = "Desc", id = "mark-1", mymobiledeviceid = "test-device-offline")
        manager.saveNoteOffline(note, synced = false)

        assertTrue(manager.getPendingSyncNotes().any { it.id == "mark-1" })

        manager.markNoteAsSynced("mark-1")

        assertFalse(manager.getPendingSyncNotes().any { it.id == "mark-1" })
    }

    // ============================================================
    // BUG-014: Close/Lifecycle Tests
    // ============================================================

    @Test
    fun `close does not throw`() {
        val mgr = OfflineNoteManager(context)
        mgr.close() // Should not throw
    }

    @Test
    fun `hasPendingSync reflects state correctly`() = runTest {
        // Initially no pending
        val freshManager = OfflineNoteManager(context)
        // Give init time to complete
        kotlinx.coroutines.delay(100)
        // hasPendingSync depends on stateflow — may be empty on fresh DB
        assertNotNull(freshManager.hasPendingSync())
        freshManager.close()
    }
}

package com.amvarpvtltd.swiftNote.offline

import com.amvarpvtltd.swiftNote.Note
import com.amvarpvtltd.swiftNote.myGlobalMobileDeviceId
import com.amvarpvtltd.swiftNote.room.NoteEntity
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/**
 * Unit tests for OfflineNoteManager's non-DB logic:
 * - NoteEntityMapper bidirectional mapping
 * - BUG-039: Transaction-based delete logic is tested via instrumented tests
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [31], manifest = Config.NONE)
class OfflineNoteManagerTest {

    @Before
    fun setUp() {
        myGlobalMobileDeviceId = "test-device-offline"
    }

    // ============================================================
    // NoteEntityMapper Tests
    // ============================================================

    @Test
    fun `toEntity maps Note fields correctly`() {
        val note = Note(
            title = "Test Title",
            description = "Test Description",
            id = "note-123",
            mymobiledeviceid = "device-456",
            timestamp = 1000L
        )
        val entity = NoteEntityMapper.toEntity(note, synced = false)
        assertEquals("note-123", entity.id)
        assertEquals("device-456", entity.mymobiledeviceid)
        assertEquals(1000L, entity.timestamp)
        assertFalse(entity.synced)
        // Title and description should be encrypted (non-empty, different from plain)
        assertTrue(entity.title.isNotEmpty())
        assertTrue(entity.description.isNotEmpty())
    }

    @Test
    fun `toEntity with synced true sets synced flag`() {
        val note = Note(
            title = "Title",
            description = "Desc",
            id = "id-1",
            mymobiledeviceid = "device-1",
            timestamp = 2000L
        )
        val entity = NoteEntityMapper.toEntity(note, synced = true)
        assertTrue(entity.synced)
    }

    @Test
    fun `toDomain maps NoteEntity back to Note`() {
        // Create an entity with encrypted data
        val note = Note(
            title = "Original Title",
            description = "Original Desc",
            id = "id-2",
            mymobiledeviceid = "test-device-offline",
            timestamp = 3000L
        )
        val entity = NoteEntityMapper.toEntity(note, synced = true)

        // Map back to domain
        val restored = NoteEntityMapper.toDomain(entity)
        assertEquals("id-2", restored.id)
        assertEquals("test-device-offline", restored.mymobiledeviceid)
        assertEquals(3000L, restored.timestamp)
        // Title/desc should be decrypted back to original
        assertEquals("Original Title", restored.title)
        assertEquals("Original Desc", restored.description)
    }

    @Test
    fun `roundtrip Note to Entity to Note preserves data`() {
        val original = Note(
            title = "Roundtrip Test",
            description = "This is a roundtrip test with special chars: <b>bold</b>",
            id = "rt-1",
            mymobiledeviceid = "test-device-offline",
            timestamp = 4000L
        )
        val entity = NoteEntityMapper.toEntity(original, synced = false)
        val restored = NoteEntityMapper.toDomain(entity)

        assertEquals(original.title, restored.title)
        assertEquals(original.description, restored.description)
        assertEquals(original.id, restored.id)
        assertEquals(original.mymobiledeviceid, restored.mymobiledeviceid)
        assertEquals(original.timestamp, restored.timestamp)
    }

    @Test
    fun `toDomain handles empty title and description`() {
        val entity = NoteEntity(
            id = "empty-1",
            title = "",
            description = "",
            mymobiledeviceid = "test-device-offline",
            timestamp = 5000L,
            synced = true
        )
        val note = NoteEntityMapper.toDomain(entity)
        assertEquals("", note.title)
        assertEquals("", note.description)
    }
}

