                Text(
                    text = "SMART REMINDERS",
                    style = MaterialTheme.typography.labelSmall.copy(letterSpacing = 1.sp),
                    fontWeight = FontWeight.Bold,
                    color = colors.successColor
                )
            }
            Row(
                modifier = Modifier
