        BasicTextField(
            value = state.description,
            onValueChange = { if (it.length <= 2000) state.description = it },
            textStyle = TextStyle(fontSize = 14.sp, color = colors.onSurface, lineHeight = 22.sp),
            maxLines = 8,
            cursorBrush = SolidColor(colors.primary),
