// ─── Category Selector ─────────────────────────────────────────────────────────

@Composable
private fun CategorySelector(state: QuickCaptureState, colors: CaptureColors) {
    Text(
        text = "CATEGORY",
        style = MaterialTheme.typography.labelSmall.copy(letterSpacing = 1.2.sp),
        fontWeight = FontWeight.SemiBold,
