/**
 * Renders the app launcher icon to a Bitmap for use as a notification large icon.
 * On Android 8+ the launcher icon is an AdaptiveIconDrawable (XML), so BitmapFactory.decodeResource()
 * returns null. This function uses Canvas rendering to correctly rasterize any drawable type.
 */
private fun renderAppIconBitmap(context: Context): Bitmap? {
    return try {
        val size = 192
        val drawable = androidx.core.content
            .ContextCompat.getDrawable(context,
                R.drawable.logo)
            ?: androidx.core.content.ContextCompat.getDrawable(context, R.drawable.logo)
            ?: return null
        val bitmap = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bitmap)
        drawable.setBounds(0, 0, size, size)
        drawable.draw(canvas)
        bitmap
    } catch (e: Exception) {
        Log.w("ReminderManager", "Failed to render app icon bitmap, using fallback", e)
        try { android.graphics.BitmapFactory.decodeResource(context.resources, R.drawable.logo4) }
        catch (e2: Exception) { null }
    }
}

/**
 * Manages reminders with persistent alarms that survive device reboots
 */
class ReminderManager private constructor(private val context: Context) {
    private val TAG = "ReminderManager"

    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
    private val database = AppDatabase.getInstance(context)
    private val reminderDao = database.reminderDao()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in ReminderManager scope", exception)
    }

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: ReminderManager? = null

        private const val NOTIFICATION_CHANNEL_ID = "smart_reminders"
        private const val NOTIFICATION_CHANNEL_NAME = "Smart Reminders"

        const val EXTRA_REMINDER_ID = "reminder_id"
        const val EXTRA_REMINDER_TITLE = "reminder_title"
        const val EXTRA_REMINDER_DESCRIPTION = "reminder_description"
        const val EXTRA_NOTE_ID = "note_id"

        fun getInstance(context: Context): ReminderManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: ReminderManager(context.applicationContext).also {
                    INSTANCE = it
                    it.createNotificationChannel()
                }
            }
        }
    }

    /**
     * Create notification channel for reminders
     */
    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            NOTIFICATION_CHANNEL_ID,
            NOTIFICATION_CHANNEL_NAME,
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            description = "Notifications for smart reminders from your notes"
            enableVibration(true)
            enableLights(true)
            setShowBadge(true)
        }

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.createNotificationChannel(channel)
        Log.d(TAG, " Notification channel created")
    }

    /**
     * Schedule a reminder alarm with Android 12-15 compliance.
     * Strategy:
     *  1. Try setExactAndAllowWhileIdle (requires SCHEDULE_EXACT_ALARM or USE_EXACT_ALARM)
     *  2. Fallback: setAndAllowWhileIdle (inexact but still fires during Doze)
     *  3. Final fallback: WorkManager OneTimeWorkRequest (guaranteed execution)
     */
    suspend fun scheduleReminder(
        reminder: DetectedReminder,
        noteId: String
    ): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            // Save reminder to database first (always persisted regardless of alarm success)
            // Use originalNoteTitle as the noteTitle so the Today screen shows the note's
            // own title instead of the AI-generated label (e.g. " Meeting Reminder").
            val entityTitle = reminder.originalNoteTitle.ifBlank { reminder.title }

            // Propagate recurrence info detected by SmartReminderAI / Gemini
            val recurrenceType = reminder.detectedRecurrence?.type ?: RecurrenceType.NONE
            val recurrenceInterval = reminder.detectedRecurrence?.interval ?: 1
            val recurrenceDaysOfWeek = reminder.detectedRecurrence?.daysOfWeek

            val reminderEntity = ReminderEntity(
                id = reminder.id,
                noteId = noteId,
                noteTitle = entityTitle,
                noteDescription = reminder.description,
                reminderTime = reminder.reminderDateTime,
                isActive = true,
                createdAt = System.currentTimeMillis(),
                recurrenceType = recurrenceType,
                recurrenceInterval = recurrenceInterval,
                recurrenceDaysOfWeek = recurrenceDaysOfWeek,
                parentReminderId = if (recurrenceType != RecurrenceType.NONE) reminder.id else null
            )

            reminderDao.insertReminder(reminderEntity)
            Log.d(TAG, " Reminder saved to database: $entityTitle")

            // Schedule the alarm
            val intent = Intent(context, ReminderReceiver::class.java).apply {
                putExtra(EXTRA_REMINDER_ID, reminder.id)
                putExtra(EXTRA_REMINDER_TITLE, reminder.title)
                putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.description)
                putExtra(EXTRA_NOTE_ID, noteId)
            }

            val pendingIntent = PendingIntent.getBroadcast(
                context,
                reminder.id.hashCode(),
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            scheduleAlarmWithFallback(
                triggerAtMillis = reminder.reminderDateTime,
                pendingIntent = pendingIntent,
                reminderId = reminder.id,
                noteId = noteId,
                title = reminder.title,
                description = reminder.description
            )

            val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
            val dateTime = formatter.format(Date(reminder.reminderDateTime))

            Log.d(TAG, "⏰ Reminder scheduled: ${reminder.title} for $dateTime")
            Result.success("Reminder scheduled for $dateTime")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error scheduling reminder", e)
            Result.failure(e)
        }
    }

    /**
     * Android 12-15 compliant alarm scheduling with redundancy:
     * 1. Try exact alarm (best precision) OR inexact setAndAllowWhileIdle
     * 2. ALWAYS also schedule WorkManager as redundant backup (guaranteed execution)
     * The WorkManager job will check if notification was already shown before duplicating.
     */
    private fun scheduleAlarmWithFallback(
        triggerAtMillis: Long,
        pendingIntent: PendingIntent,
        reminderId: String,
        noteId: String,
        title: String,
        description: String
    ) {
        val delay = triggerAtMillis - System.currentTimeMillis()
        if (delay <= 0) {
            Log.w(TAG, "Reminder time is in the past, firing notification immediately")
            // Fire immediately instead of silently skipping
            showReminderNotification(reminderId, title, description, noteId)
            return
        }

        var alarmScheduled = false

        try {
            if (canScheduleExactAlarms()) {
                // Best case: exact alarm fires at the precise time
                alarmManager.setExactAndAllowWhileIdle(
                    AlarmManager.RTC_WAKEUP,
                    triggerAtMillis,
                    pendingIntent
                )
                Log.d(TAG, "Scheduled exact alarm for $reminderId")
                alarmScheduled = true
            }
        } catch (e: SecurityException) {
            Log.w(TAG, "SecurityException on exact alarm: ${e.message}")
        }

        if (!alarmScheduled) {
            // Fallback 1: setAndAllowWhileIdle (inexact but fires during Doze)
            try {
                alarmManager.setAndAllowWhileIdle(
                    AlarmManager.RTC_WAKEUP,
                    triggerAtMillis,
                    pendingIntent
                )
                Log.d(TAG, "Scheduled inexact (setAndAllowWhileIdle) alarm for $reminderId")
                alarmScheduled = true
            } catch (e: SecurityException) {
                Log.w(TAG, "SecurityException on setAndAllowWhileIdle: ${e.message}")
            }
        }

        if (!alarmScheduled) {
            Log.e(TAG, "All alarm scheduling strategies failed for $reminderId")
        }
    }

    /**
     * Get all active reminders
     */
    suspend fun getAllActiveReminders(): List<ReminderEntity> = withContext(Dispatchers.IO) {
        return@withContext try {
            reminderDao.getAllActiveReminders().first()
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error getting all active reminders", e)
            emptyList()
        }
    }

    /**
     * Reschedule all active reminders (called after device reboot or permission grant)
     */
    suspend fun rescheduleAllReminders(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            val activeReminders = getAllActiveReminders()
            val currentTime = System.currentTimeMillis()
            var rescheduledCount = 0

            activeReminders.forEach { reminder ->
                if (reminder.reminderTime > currentTime) {
                    // Reschedule future reminders
                    val intent = Intent(context, ReminderReceiver::class.java).apply {
                        putExtra(EXTRA_REMINDER_ID, reminder.id)
                        putExtra(EXTRA_REMINDER_TITLE, reminder.noteTitle)
                        putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.noteDescription)
                        putExtra(EXTRA_NOTE_ID, reminder.noteId)
                    }

                    val pendingIntent = PendingIntent.getBroadcast(
                        context,
                        reminder.id.hashCode(),
                        intent,
                        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                    )

                    // Use the same graduated fallback as scheduleReminder
                    scheduleAlarmWithFallback(
                        triggerAtMillis = reminder.reminderTime,
                        pendingIntent = pendingIntent,
                        reminderId = reminder.id,
                        noteId = reminder.noteId,
                        title = reminder.noteTitle,
                        description = reminder.noteDescription
                    )
                    rescheduledCount++
                } else {
                    // Mark expired reminders as inactive
                    reminderDao.deactivateReminder(reminder.id)
                }
            }

            Log.d(TAG, " Rescheduled $rescheduledCount reminders after reboot")
            Result.success("Rescheduled $rescheduledCount reminders")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error rescheduling reminders", e)
            Result.failure(e)
        }
    }

    /**
     * Create a reminder from AI detection
     * This is a convenience method that wraps scheduleReminder with proper error handling.
     *
     * Safety net: refuses to schedule if the same note already has an active reminder
     * firing in the same minute bucket. This is the last line of defense against
     * duplicate detections from ML Kit overlapping annotations, regex overlap,
     * LLM hallucinations, or double-saves.
     */
    suspend fun createReminderFromDetection(
        detectedReminder: DetectedReminder,
        noteId: String
    ): Boolean {
        return try {
            val targetBucket = detectedReminder.reminderDateTime / 60_000L
            val existing = try {
                reminderDao.getRemindersForNote(noteId)
            } catch (_: Exception) {
                emptyList()
            }
            val duplicate = existing.any { it.reminderTime / 60_000L == targetBucket }
            if (duplicate) {
                Log.d(TAG, "⏭️ Skipping duplicate reminder for note $noteId at bucket $targetBucket")
                return true // Treat as success — the user's intent is already satisfied
            }

            val result = scheduleReminder(detectedReminder, noteId)
            result.isSuccess
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error creating reminder from detection", e)
            false
        }
    }

    /**
     * Check if the app can schedule exact alarms
     */
    fun canScheduleExactAlarms(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            alarmManager.canScheduleExactAlarms()
        } else {
            true
        }
    }

    /**
     * Open system settings to allow the user to grant exact alarm permission (Android 12+).
     * Returns true if the intent was launched, false if not needed or not applicable.
     */
    fun requestExactAlarmPermission(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !canScheduleExactAlarms()) {
            try {
                val intent = Intent(
                    android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,
                    android.net.Uri.parse("package:${context.packageName}")
                ).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(intent)
                return true
            } catch (e: Exception) {
                Log.e(TAG, "❌ Error opening exact alarm settings", e)
            }
        }
        return false
    }

    /**
     * Show notification for triggered reminder
     */
    fun showReminderNotification(
        reminderId: String,
        title: String,
        description: String,
        noteId: String
    ) {
        try {
            // Check notification permissions first
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                val notificationManager = NotificationManagerCompat.from(context)
                if (!notificationManager.areNotificationsEnabled()) {
                    Log.w(TAG, "⚠️ Notifications are disabled for this app")
                    return
                }
            }

            // Create intent to open the note
            val notificationIntent = Intent(context, MainActivity::class.java).apply {
                putExtra("noteId", noteId)
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            }

            val pendingIntent = PendingIntent.getActivity(
                context,
                reminderId.hashCode(),
                notificationIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            // Strip HTML tags and entities so the notification body shows clean readable text
            val rawDescription = RichTextBridge.stripHtmlToPlainText(description).trim()

            // Format checklist content for readable notification display
            val displayDescription = if (ChecklistParser.isChecklistContent(description)) {
                val (checked, total) = ChecklistParser.progress(description)
                val items = ChecklistParser.parseItems(description)
                val unchecked = items.filter { !it.isChecked }.take(3)
                if (unchecked.isEmpty()) {
                    "✓ All $total items completed!"
                } else {
                    "Checklist ($checked/$total done): " + unchecked.joinToString(", ") { it.text }
                }
            } else {
                rawDescription.ifEmpty { "Tap to open your note" }
            }

            val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)
                // Monochrome small icon for the status bar
                .setSmallIcon(R.drawable.logo4)
                // App launcher icon as large icon — rendered via Canvas to handle adaptive icons on API 26+
                .setLargeIcon(renderAppIconBitmap(context))
                .setContentTitle(" $title")
                .setContentText(displayDescription)
                // Expand to show full description when notification is expanded
                .setStyle(
                    NotificationCompat.BigTextStyle()
                        .bigText(displayDescription)
                        .setBigContentTitle(" $title")
                        .setSummaryText("SwiftNote · Reminder")
                )
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                // Brand teal accent
                .setColor(ContextCompat.getColor(context, R.color.primary))
                .setCategory(NotificationCompat.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .setContentIntent(pendingIntent)
                .setVibrate(longArrayOf(0, 500, 100, 500))
                .setDefaults(NotificationCompat.DEFAULT_SOUND or NotificationCompat.DEFAULT_LIGHTS)
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                .setOnlyAlertOnce(false)
                .build()

            val notificationManager = NotificationManagerCompat.from(context)
            try {
                notificationManager.notify(reminderId.hashCode(), notification)
                Log.d(TAG, " Reminder notification shown: $title")

                // Mark reminder as completed SYNCHRONOUSLY using runBlocking
                // This ensures it completes before the BroadcastReceiver's goAsync() finishes
                kotlinx.coroutines.runBlocking(Dispatchers.IO) {
                    try {
                        reminderDao.deactivateReminder(reminderId)
                        Log.d(TAG, "✅ Reminder marked as completed: $title")
                    } catch (e: Exception) {
                        Log.e(TAG, "❌ Error marking reminder as completed", e)
                    }
                }
            } catch (e: SecurityException) {
                Log.e(TAG, "❌ Missing notification permission", e)
            }

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error showing reminder notification", e)
        }
    }
}

/**
0 * BroadcastReceiver to handle reminder alarms.
 * Uses goAsync() to prevent the system from killing the process before
 * the notification is fully shown (critical when app is not in foreground).
 */
class ReminderReceiver : BroadcastReceiver() {
    @RequiresPermission(Manifest.permission.POST_NOTIFICATIONS)
    override fun onReceive(context: Context, intent: Intent) {
        val reminderId = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_ID) ?: return
        val title = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_TITLE) ?: "Reminder"
        val description = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_DESCRIPTION) ?: ""
        val noteId = intent.getStringExtra(ReminderManager.EXTRA_NOTE_ID) ?: ""

        Log.d("ReminderReceiver", " Reminder triggered: $title")

        // Use goAsync() to get more execution time (~30s instead of ~10s)
        // This is critical when the app is killed/background — prevents premature process death
        val pendingResult = goAsync()

        val exceptionHandler = CoroutineExceptionHandler { _, exception ->
            Log.e("ReminderReceiver", "Uncaught exception in ReminderReceiver scope", exception)
            pendingResult.finish()
        }

        CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
            try {
                val reminderManager = ReminderManager.getInstance(context)
                reminderManager.showReminderNotification(reminderId, title, description, noteId)

                // Mark this reminder as fired (inactive). For recurring reminders, the
                // next occurrence is inserted below as a new active entity.
                val db = com.amvarpvtltd.swiftNote.room.AppDatabase.getInstance(context)
                try { db.reminderDao().deactivateReminder(reminderId) } catch (_: Exception) {}

                // Phase 2: Schedule next occurrence for recurring reminders
                val reminderEntity = db.reminderDao().getReminderById(reminderId)
                if (reminderEntity != null && reminderEntity.recurrenceType != RecurrenceType.NONE) {
                    val parentId = reminderEntity.parentReminderId ?: reminderEntity.id
                    val nextTime = RecurrenceCalculator.getNextOccurrence(
                        currentReminderTime = reminderEntity.reminderTime,
                        recurrenceType = reminderEntity.recurrenceType,
                        recurrenceInterval = reminderEntity.recurrenceInterval,
                        recurrenceDaysOfWeek = reminderEntity.recurrenceDaysOfWeek,
                        recurrenceEndDate = reminderEntity.recurrenceEndDate
                    )

                    if (nextTime != null) {
                        val nextReminder = ReminderEntity(
                            id = java.util.UUID.randomUUID().toString(),
                            noteId = reminderEntity.noteId,
                            noteTitle = reminderEntity.noteTitle,
                            noteDescription = reminderEntity.noteDescription,
                            reminderTime = nextTime,
                            isActive = true,
                            createdAt = System.currentTimeMillis(),
                            recurrenceType = reminderEntity.recurrenceType,
                            recurrenceInterval = reminderEntity.recurrenceInterval,
                            recurrenceDaysOfWeek = reminderEntity.recurrenceDaysOfWeek,
                            recurrenceEndDate = reminderEntity.recurrenceEndDate,
                            parentReminderId = parentId
                        )

                        db.reminderDao().insertReminder(nextReminder)

                        // Schedule the next alarm
                        val nextIntent = Intent(context, ReminderReceiver::class.java).apply {
                            putExtra(ReminderManager.EXTRA_REMINDER_ID, nextReminder.id)
                            putExtra(ReminderManager.EXTRA_REMINDER_TITLE, nextReminder.noteTitle)
                            putExtra(ReminderManager.EXTRA_REMINDER_DESCRIPTION, nextReminder.noteDescription)
                            putExtra(ReminderManager.EXTRA_NOTE_ID, nextReminder.noteId)
                        }
                        val nextPendingIntent = PendingIntent.getBroadcast(
                            context,
                            nextReminder.id.hashCode(),
                            nextIntent,
                            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                        )

                        val alarmMgr = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
                        try {
                            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && alarmMgr.canScheduleExactAlarms()) {
                                alarmMgr.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, nextTime, nextPendingIntent)
                            } else {
                                alarmMgr.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, nextTime, nextPendingIntent)
                            }
                        } catch (_: SecurityException) {
                            alarmMgr.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, nextTime, nextPendingIntent)
                        }

                        Log.d("ReminderReceiver", " Scheduled next recurring reminder at $nextTime for chain $parentId")
                    } else {
                        Log.d("ReminderReceiver", " Recurring chain ended for $parentId (end date reached)")
                    }
                }
            } catch (e: Exception) {
                Log.e("ReminderReceiver", "❌ Error in ReminderReceiver", e)
            } finally {
                pendingResult.finish()
            }
        }
    }
}

/**
 * BroadcastReceiver to handle device boot and reschedule alarms.
 * Uses goAsync() for safe background execution.
 */
class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (Intent.ACTION_BOOT_COMPLETED == intent.action ||
            Intent.ACTION_MY_PACKAGE_REPLACED == intent.action) {

            Log.d("BootReceiver", " Device booted, rescheduling reminders...")

            val pendingResult = goAsync()

            val exceptionHandler = CoroutineExceptionHandler { _, exception ->
                Log.e("BootReceiver", "Uncaught exception in BootReceiver scope", exception)
                pendingResult.finish()
            }
            CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
                try {
                    val reminderManager = ReminderManager.getInstance(context)
                    reminderManager.rescheduleAllReminders()
                } finally {
                    pendingResult.finish()
                }
            }
        }
    }
}

/**
 * BroadcastReceiver for ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED (Android 12+).
 * When the user grants or revokes exact alarm permission from system settings,
 * reschedule all active reminders to use the best available alarm type.
 */
class ExactAlarmPermissionReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            intent.action == AlarmManager.ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED) {

            Log.d("ExactAlarmPermReceiver", "Exact alarm permission state changed — rescheduling reminders")

            val pendingResult = goAsync()

            val exceptionHandler = CoroutineExceptionHandler { _, exception ->
                Log.e("ExactAlarmPermReceiver", "Error rescheduling after permission change", exception)
                pendingResult.finish()
            }
            CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
                try {
                    val reminderManager = ReminderManager.getInstance(context)
                    reminderManager.rescheduleAllReminders()
                } finally {
                    pendingResult.finish()
                }
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.reminders

import android.Manifest
import android.annotation.SuppressLint
import android.app.AlarmManager
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.Canvas
import android.os.Build
import android.util.Log
import androidx.annotation.RequiresPermission
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.core.content.ContextCompat
import com.amvarpvtltd.swiftNote.MainActivity
import com.amvarpvtltd.swiftNote.R
import com.amvarpvtltd.swiftNote.ai.DetectedReminder
import com.amvarpvtltd.swiftNote.checklist.ChecklistParser
import com.amvarpvtltd.swiftNote.richtext.RichTextBridge
import com.amvarpvtltd.swiftNote.room.AppDatabase
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Renders the app launcher icon to a Bitmap for use as a notification large icon.
 * On Android 8+ the launcher icon is an AdaptiveIconDrawable (XML), so BitmapFactory.decodeResource()
 * returns null. This function uses Canvas rendering to correctly rasterize any drawable type.
 */
private fun renderAppIconBitmap(context: Context): Bitmap? {
    return try {
        val size = 192
        val drawable = androidx.core.content
            .ContextCompat.getDrawable(context,
                R.drawable.logo)
            ?: androidx.core.content.ContextCompat.getDrawable(context, R.drawable.logo)
            ?: return null
        val bitmap = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bitmap)
        drawable.setBounds(0, 0, size, size)
        drawable.draw(canvas)
        bitmap
    } catch (e: Exception) {
        Log.w("ReminderManager", "Failed to render app icon bitmap, using fallback", e)
        try { android.graphics.BitmapFactory.decodeResource(context.resources, R.drawable.logo) }
        catch (e2: Exception) { null }
    }
}

/**
 * Manages reminders with persistent alarms that survive device reboots
 */
class ReminderManager private constructor(private val context: Context) {
    private val TAG = "ReminderManager"

    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
    private val database = AppDatabase.getInstance(context)
    private val reminderDao = database.reminderDao()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in ReminderManager scope", exception)
    }

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: ReminderManager? = null

        private const val NOTIFICATION_CHANNEL_ID = "smart_reminders"
        private const val NOTIFICATION_CHANNEL_NAME = "Smart Reminders"

        const val EXTRA_REMINDER_ID = "reminder_id"
        const val EXTRA_REMINDER_TITLE = "reminder_title"
        const val EXTRA_REMINDER_DESCRIPTION = "reminder_description"
        const val EXTRA_NOTE_ID = "note_id"

        fun getInstance(context: Context): ReminderManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: ReminderManager(context.applicationContext).also {
                    INSTANCE = it
                    it.createNotificationChannel()
                }
            }
        }
    }

    /**
     * Create notification channel for reminders
     */
    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            NOTIFICATION_CHANNEL_ID,
            NOTIFICATION_CHANNEL_NAME,
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            description = "Notifications for smart reminders from your notes"
            enableVibration(true)
            enableLights(true)
            setShowBadge(true)
        }

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.createNotificationChannel(channel)
        Log.d(TAG, " Notification channel created")
    }

    /**
     * Schedule a reminder alarm with Android 12-15 compliance.
     * Strategy:
     *  1. Try setExactAndAllowWhileIdle (requires SCHEDULE_EXACT_ALARM or USE_EXACT_ALARM)
     *  2. Fallback: setAndAllowWhileIdle (inexact but still fires during Doze)
     *  3. Final fallback: WorkManager OneTimeWorkRequest (guaranteed execution)
     */
    suspend fun scheduleReminder(
        reminder: DetectedReminder,
        noteId: String
    ): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            // Save reminder to database first (always persisted regardless of alarm success)
            // Use originalNoteTitle as the noteTitle so the Today screen shows the note's
            // own title instead of the AI-generated label (e.g. " Meeting Reminder").
            val entityTitle = reminder.originalNoteTitle.ifBlank { reminder.title }

            // Propagate recurrence info detected by SmartReminderAI / Gemini
            val recurrenceType = reminder.detectedRecurrence?.type ?: RecurrenceType.NONE
            val recurrenceInterval = reminder.detectedRecurrence?.interval ?: 1
            val recurrenceDaysOfWeek = reminder.detectedRecurrence?.daysOfWeek

            val reminderEntity = ReminderEntity(
                id = reminder.id,
                noteId = noteId,
                noteTitle = entityTitle,
                noteDescription = reminder.description,
                reminderTime = reminder.reminderDateTime,
                isActive = true,
                createdAt = System.currentTimeMillis(),
                recurrenceType = recurrenceType,
                recurrenceInterval = recurrenceInterval,
                recurrenceDaysOfWeek = recurrenceDaysOfWeek,
                parentReminderId = if (recurrenceType != RecurrenceType.NONE) reminder.id else null
            )

            reminderDao.insertReminder(reminderEntity)
            Log.d(TAG, " Reminder saved to database: $entityTitle")

            // Schedule the alarm
            val intent = Intent(context, ReminderReceiver::class.java).apply {
                putExtra(EXTRA_REMINDER_ID, reminder.id)
                putExtra(EXTRA_REMINDER_TITLE, reminder.title)
                putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.description)
                putExtra(EXTRA_NOTE_ID, noteId)
            }

            val pendingIntent = PendingIntent.getBroadcast(
                context,
                reminder.id.hashCode(),
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            scheduleAlarmWithFallback(
                triggerAtMillis = reminder.reminderDateTime,
                pendingIntent = pendingIntent,
                reminderId = reminder.id,
                noteId = noteId,
                title = reminder.title,
                description = reminder.description
            )

            val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
            val dateTime = formatter.format(Date(reminder.reminderDateTime))

            Log.d(TAG, "⏰ Reminder scheduled: ${reminder.title} for $dateTime")
            Result.success("Reminder scheduled for $dateTime")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error scheduling reminder", e)
            Result.failure(e)
        }
    }

    /**
     * Android 12-15 compliant alarm scheduling with redundancy:
     * 1. Try exact alarm (best precision) OR inexact setAndAllowWhileIdle
     * 2. ALWAYS also schedule WorkManager as redundant backup (guaranteed execution)
     * The WorkManager job will check if notification was already shown before duplicating.
     */
    private fun scheduleAlarmWithFallback(
        triggerAtMillis: Long,
        pendingIntent: PendingIntent,
        reminderId: String,
        noteId: String,
        title: String,
        description: String
    ) {
        val delay = triggerAtMillis - System.currentTimeMillis()
        if (delay <= 0) {
            Log.w(TAG, "Reminder time is in the past, firing notification immediately")
            // Fire immediately instead of silently skipping
            showReminderNotification(reminderId, title, description, noteId)
            return
        }

        var alarmScheduled = false

        try {
            if (canScheduleExactAlarms()) {
                // Best case: exact alarm fires at the precise time
                alarmManager.setExactAndAllowWhileIdle(
                    AlarmManager.RTC_WAKEUP,
                    triggerAtMillis,
                    pendingIntent
                )
                Log.d(TAG, "Scheduled exact alarm for $reminderId")
                alarmScheduled = true
            }
        } catch (e: SecurityException) {
            Log.w(TAG, "SecurityException on exact alarm: ${e.message}")
        }

        if (!alarmScheduled) {
            // Fallback 1: setAndAllowWhileIdle (inexact but fires during Doze)
            try {
                alarmManager.setAndAllowWhileIdle(
                    AlarmManager.RTC_WAKEUP,
                    triggerAtMillis,
                    pendingIntent
                )
                Log.d(TAG, "Scheduled inexact (setAndAllowWhileIdle) alarm for $reminderId")
                alarmScheduled = true
            } catch (e: SecurityException) {
                Log.w(TAG, "SecurityException on setAndAllowWhileIdle: ${e.message}")
            }
        }

        if (!alarmScheduled) {
            Log.e(TAG, "All alarm scheduling strategies failed for $reminderId")
        }
    }

    /**
     * Get all active reminders
     */
    suspend fun getAllActiveReminders(): List<ReminderEntity> = withContext(Dispatchers.IO) {
        return@withContext try {
            reminderDao.getAllActiveReminders().first()
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error getting all active reminders", e)
            emptyList()
        }
    }

    /**
     * Reschedule all active reminders (called after device reboot or permission grant)
     */
    suspend fun rescheduleAllReminders(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            val activeReminders = getAllActiveReminders()
            val currentTime = System.currentTimeMillis()
            var rescheduledCount = 0

            activeReminders.forEach { reminder ->
                if (reminder.reminderTime > currentTime) {
                    // Reschedule future reminders
                    val intent = Intent(context, ReminderReceiver::class.java).apply {
                        putExtra(EXTRA_REMINDER_ID, reminder.id)
                        putExtra(EXTRA_REMINDER_TITLE, reminder.noteTitle)
                        putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.noteDescription)
                        putExtra(EXTRA_NOTE_ID, reminder.noteId)
                    }

                    val pendingIntent = PendingIntent.getBroadcast(
                        context,
                        reminder.id.hashCode(),
                        intent,
                        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                    )

                    // Use the same graduated fallback as scheduleReminder
                    scheduleAlarmWithFallback(
                        triggerAtMillis = reminder.reminderTime,
                        pendingIntent = pendingIntent,
                        reminderId = reminder.id,
                        noteId = reminder.noteId,
                        title = reminder.noteTitle,
                        description = reminder.noteDescription
                    )
                    rescheduledCount++
                } else {
                    // Mark expired reminders as inactive
                    reminderDao.deactivateReminder(reminder.id)
                }
            }

            Log.d(TAG, " Rescheduled $rescheduledCount reminders after reboot")
            Result.success("Rescheduled $rescheduledCount reminders")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error rescheduling reminders", e)
            Result.failure(e)
        }
    }

    /**
     * Create a reminder from AI detection
     * This is a convenience method that wraps scheduleReminder with proper error handling.
     *
     * Safety net: refuses to schedule if the same note already has an active reminder
     * firing in the same minute bucket. This is the last line of defense against
     * duplicate detections from ML Kit overlapping annotations, regex overlap,
     * LLM hallucinations, or double-saves.
     */
    suspend fun createReminderFromDetection(
        detectedReminder: DetectedReminder,
        noteId: String
    ): Boolean {
        return try {
            val targetBucket = detectedReminder.reminderDateTime / 60_000L
            val existing = try {
                reminderDao.getRemindersForNote(noteId)
            } catch (_: Exception) {
                emptyList()
            }
            val duplicate = existing.any { it.reminderTime / 60_000L == targetBucket }
            if (duplicate) {
                Log.d(TAG, "⏭️ Skipping duplicate reminder for note $noteId at bucket $targetBucket")
                return true // Treat as success — the user's intent is already satisfied
            }

            val result = scheduleReminder(detectedReminder, noteId)
            result.isSuccess
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error creating reminder from detection", e)
            false
        }
    }

    /**
     * Check if the app can schedule exact alarms
     */
    fun canScheduleExactAlarms(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            alarmManager.canScheduleExactAlarms()
        } else {
            true
        }
    }

    /**
     * Open system settings to allow the user to grant exact alarm permission (Android 12+).
     * Returns true if the intent was launched, false if not needed or not applicable.
     */
    fun requestExactAlarmPermission(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !canScheduleExactAlarms()) {
            try {
                val intent = Intent(
                    android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,
                    android.net.Uri.parse("package:${context.packageName}")
                ).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(intent)
                return true
            } catch (e: Exception) {
                Log.e(TAG, "❌ Error opening exact alarm settings", e)
            }
        }
        return false
    }

    /**
     * Show notification for triggered reminder
     */
    fun showReminderNotification(
        reminderId: String,
        title: String,
        description: String,
        noteId: String
    ) {
        try {
            // Check notification permissions first
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                val notificationManager = NotificationManagerCompat.from(context)
                if (!notificationManager.areNotificationsEnabled()) {
                    Log.w(TAG, "⚠️ Notifications are disabled for this app")
                    return
                }
            }

            // Create intent to open the note
            val notificationIntent = Intent(context, MainActivity::class.java).apply {
                putExtra("noteId", noteId)
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            }

            val pendingIntent = PendingIntent.getActivity(
                context,
                reminderId.hashCode(),
                notificationIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            // Strip HTML tags and entities so the notification body shows clean readable text
            val rawDescription = RichTextBridge.stripHtmlToPlainText(description).trim()

            // Format checklist content for readable notification display
            val displayDescription = if (ChecklistParser.isChecklistContent(description)) {
                val (checked, total) = ChecklistParser.progress(description)
                val items = ChecklistParser.parseItems(description)
                val unchecked = items.filter { !it.isChecked }.take(3)
                if (unchecked.isEmpty()) {
                    "✓ All $total items completed!"
                } else {
                    "Checklist ($checked/$total done): " + unchecked.joinToString(", ") { it.text }
                }
            } else {
                rawDescription.ifEmpty { "Tap to open your note" }
            }

            val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)
                // Monochrome small icon for the status bar
                .setSmallIcon(R.drawable.logo4)
                // App launcher icon as large icon — rendered via Canvas to handle adaptive icons on API 26+
                .setLargeIcon(renderAppIconBitmap(context))
                .setContentTitle(" $title")
                .setContentText(displayDescription)
                // Expand to show full description when notification is expanded
                .setStyle(
                    NotificationCompat.BigTextStyle()
                        .bigText(displayDescription)
                        .setBigContentTitle(" $title")
                        .setSummaryText("SwiftNote · Reminder")
                )
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                // Brand teal accent
                .setColor(ContextCompat.getColor(context, R.color.primary))
                .setCategory(NotificationCompat.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .setContentIntent(pendingIntent)
                .setVibrate(longArrayOf(0, 500, 100, 500))
                .setDefaults(NotificationCompat.DEFAULT_SOUND or NotificationCompat.DEFAULT_LIGHTS)
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                .setOnlyAlertOnce(false)
                .build()

            val notificationManager = NotificationManagerCompat.from(context)
            try {
                notificationManager.notify(reminderId.hashCode(), notification)
                Log.d(TAG, " Reminder notification shown: $title")

                // Mark reminder as completed SYNCHRONOUSLY using runBlocking
                // This ensures it completes before the BroadcastReceiver's goAsync() finishes
                kotlinx.coroutines.runBlocking(Dispatchers.IO) {
                    try {
                        reminderDao.deactivateReminder(reminderId)
                        Log.d(TAG, "✅ Reminder marked as completed: $title")
                    } catch (e: Exception) {
                        Log.e(TAG, "❌ Error marking reminder as completed", e)
                    }
                }
            } catch (e: SecurityException) {
                Log.e(TAG, "❌ Missing notification permission", e)
            }

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error showing reminder notification", e)
        }
    }
}

/**
0 * BroadcastReceiver to handle reminder alarms.
 * Uses goAsync() to prevent the system from killing the process before
 * the notification is fully shown (critical when app is not in foreground).
 */
class ReminderReceiver : BroadcastReceiver() {
    @RequiresPermission(Manifest.permission.POST_NOTIFICATIONS)
    override fun onReceive(context: Context, intent: Intent) {
        val reminderId = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_ID) ?: return
        val title = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_TITLE) ?: "Reminder"
        val description = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_DESCRIPTION) ?: ""
        val noteId = intent.getStringExtra(ReminderManager.EXTRA_NOTE_ID) ?: ""

        Log.d("ReminderReceiver", " Reminder triggered: $title")

        // Use goAsync() to get more execution time (~30s instead of ~10s)
        // This is critical when the app is killed/background — prevents premature process death
        val pendingResult = goAsync()

        val exceptionHandler = CoroutineExceptionHandler { _, exception ->
            Log.e("ReminderReceiver", "Uncaught exception in ReminderReceiver scope", exception)
            pendingResult.finish()
        }

        CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
            try {
                val reminderManager = ReminderManager.getInstance(context)
                reminderManager.showReminderNotification(reminderId, title, description, noteId)

                // Mark this reminder as fired (inactive). For recurring reminders, the
                // next occurrence is inserted below as a new active entity.
                val db = com.amvarpvtltd.swiftNote.room.AppDatabase.getInstance(context)
                try { db.reminderDao().deactivateReminder(reminderId) } catch (_: Exception) {}

                // Phase 2: Schedule next occurrence for recurring reminders
                val reminderEntity = db.reminderDao().getReminderById(reminderId)
                if (reminderEntity != null && reminderEntity.recurrenceType != RecurrenceType.NONE) {
                    val parentId = reminderEntity.parentReminderId ?: reminderEntity.id
                    val nextTime = RecurrenceCalculator.getNextOccurrence(
                        currentReminderTime = reminderEntity.reminderTime,
                        recurrenceType = reminderEntity.recurrenceType,
                        recurrenceInterval = reminderEntity.recurrenceInterval,
                        recurrenceDaysOfWeek = reminderEntity.recurrenceDaysOfWeek,
                        recurrenceEndDate = reminderEntity.recurrenceEndDate
                    )

                    if (nextTime != null) {
                        val nextReminder = ReminderEntity(
                            id = java.util.UUID.randomUUID().toString(),
                            noteId = reminderEntity.noteId,
                            noteTitle = reminderEntity.noteTitle,
                            noteDescription = reminderEntity.noteDescription,
                            reminderTime = nextTime,
                            isActive = true,
                            createdAt = System.currentTimeMillis(),
                            recurrenceType = reminderEntity.recurrenceType,
                            recurrenceInterval = reminderEntity.recurrenceInterval,
                            recurrenceDaysOfWeek = reminderEntity.recurrenceDaysOfWeek,
                            recurrenceEndDate = reminderEntity.recurrenceEndDate,
                            parentReminderId = parentId
                        )

                        db.reminderDao().insertReminder(nextReminder)

                        // Schedule the next alarm
                        val nextIntent = Intent(context, ReminderReceiver::class.java).apply {
                            putExtra(ReminderManager.EXTRA_REMINDER_ID, nextReminder.id)
                            putExtra(ReminderManager.EXTRA_REMINDER_TITLE, nextReminder.noteTitle)
                            putExtra(ReminderManager.EXTRA_REMINDER_DESCRIPTION, nextReminder.noteDescription)
                            putExtra(ReminderManager.EXTRA_NOTE_ID, nextReminder.noteId)
                        }
                        val nextPendingIntent = PendingIntent.getBroadcast(
                            context,
                            nextReminder.id.hashCode(),
                            nextIntent,
                            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                        )

                        val alarmMgr = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
                        try {
                            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && alarmMgr.canScheduleExactAlarms()) {
                                alarmMgr.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, nextTime, nextPendingIntent)
                            } else {
                                alarmMgr.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, nextTime, nextPendingIntent)
                            }
                        } catch (_: SecurityException) {
                            alarmMgr.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, nextTime, nextPendingIntent)
                        }

                        Log.d("ReminderReceiver", " Scheduled next recurring reminder at $nextTime for chain $parentId")
                    } else {
                        Log.d("ReminderReceiver", " Recurring chain ended for $parentId (end date reached)")
                    }
                }
            } catch (e: Exception) {
                Log.e("ReminderReceiver", "❌ Error in ReminderReceiver", e)
            } finally {
                pendingResult.finish()
            }
        }
    }
}

/**
 * BroadcastReceiver to handle device boot and reschedule alarms.
 * Uses goAsync() for safe background execution.
 */
class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (Intent.ACTION_BOOT_COMPLETED == intent.action ||
            Intent.ACTION_MY_PACKAGE_REPLACED == intent.action) {

            Log.d("BootReceiver", " Device booted, rescheduling reminders...")

            val pendingResult = goAsync()

            val exceptionHandler = CoroutineExceptionHandler { _, exception ->
                Log.e("BootReceiver", "Uncaught exception in BootReceiver scope", exception)
                pendingResult.finish()
            }
            CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
                try {
                    val reminderManager = ReminderManager.getInstance(context)
                    reminderManager.rescheduleAllReminders()
                } finally {
                    pendingResult.finish()
                }
            }
        }
    }
}

/**
 * BroadcastReceiver for ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED (Android 12+).
 * When the user grants or revokes exact alarm permission from system settings,
 * reschedule all active reminders to use the best available alarm type.
 */
class ExactAlarmPermissionReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            intent.action == AlarmManager.ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED) {

            Log.d("ExactAlarmPermReceiver", "Exact alarm permission state changed — rescheduling reminders")

            val pendingResult = goAsync()

            val exceptionHandler = CoroutineExceptionHandler { _, exception ->
                Log.e("ExactAlarmPermReceiver", "Error rescheduling after permission change", exception)
                pendingResult.finish()
            }
            CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
                try {
                    val reminderManager = ReminderManager.getInstance(context)
                    reminderManager.rescheduleAllReminders()
                } finally {
                    pendingResult.finish()
                }
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.reminders

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.notifications.ReminderScheduler
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.utils.NetworkManager
import com.google.firebase.database.DatabaseReference
import com.google.firebase.database.FirebaseDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext
import java.util.*

class ReminderRepository(private val context: Context) {

    private val reminderDao = AppDatabase.getInstance(context).reminderDao()
    private val reminderScheduler = ReminderScheduler(context)
    private val database = FirebaseDatabase.getInstance()

    /**
     * Resolve the Firebase path for reminders, mirroring [com.amvarpvtltd.swiftNote.repository.NoteRepository.resolveNotesRef]:
     *   users/{accountId}/reminders/{deviceId}
     * accountId = stored passphrase if synced, otherwise local deviceId.
     */
    private fun resolveRemindersRef(): DatabaseReference {
        val deviceId = DeviceManager.getOrCreateDeviceId(context)
        val accountId = PassphraseManager.getStoredPassphrase(context).takeIf { !it.isNullOrEmpty() } ?: deviceId
        return database.getReference("users").child(accountId).child("reminders").child(deviceId)
    }

    /**
     * Best-effort push of a single reminder to Firebase. Mirrors NoteRepository.syncSingleNote.
     * Silently no-ops when offline so the local DB stays the source of truth.
     */
    private suspend fun syncSingleReminder(reminder: ReminderEntity) {
        if (!NetworkManager.getInstance(context).isConnected()) {
            Log.d("ReminderRepository", "Offline — skipping Firebase push for reminder ${reminder.id}")
            return
        }
        try {
            // Firebase rules require auth != null — make sure anon sign-in resolved first.
            val authResult = PassphraseManager.ensureAuthenticated()
            if (authResult.isFailure) {
                Log.w("ReminderRepository", "Auth not ready, skipping Firebase push for reminder ${reminder.id}: ${authResult.exceptionOrNull()?.message}")
                return
            }
            val deviceId = DeviceManager.getOrCreateDeviceId(context)
            val accountId = PassphraseManager.getStoredPassphrase(context).takeIf { !it.isNullOrEmpty() } ?: deviceId
            val key = accountId // same key candidate the sync layer tries first
            val encrypted = reminder.toEncryptedData(key)
            val ref = database.getReference("users").child(accountId).child("reminders").child(deviceId).child(reminder.id)
            ref.setValue(encrypted).await()
            Log.i("ReminderRepository", "✅ Pushed reminder ${reminder.id} to users/$accountId/reminders/$deviceId/${reminder.id}")
        } catch (e: Exception) {
            // Elevated to warn so silent permission-denied / network issues are visible in Logcat.
            Log.w("ReminderRepository", "❌ Failed to push reminder ${reminder.id} to Firebase: ${e.message}", e)
        }
    }

    /** Best-effort removal of a single reminder from Firebase. */
    private suspend fun deleteRemoteReminder(reminderId: String) {
        if (!NetworkManager.getInstance(context).isConnected()) return
        try {
            resolveRemindersRef().child(reminderId).removeValue().await()
        } catch (e: Exception) {
            Log.w("ReminderRepository", "Failed to remove remote reminder $reminderId: ${e.message}")
        }
    }

    suspend fun createReminder(request: ReminderRequest): Result<String> {
        return try {
            val reminderId = UUID.randomUUID().toString()
            val reminder = ReminderEntity(
                id = reminderId,
                noteId = request.noteId,
                noteTitle = request.noteTitle,
                noteDescription = request.noteDescription,
                reminderTime = request.getReminderTime(),
                // Phase 2: Include recurrence data
                recurrenceType = request.recurrenceType,
                recurrenceInterval = request.recurrenceInterval,
                recurrenceDaysOfWeek = request.recurrenceDaysOfWeek,
                recurrenceEndDate = request.recurrenceEndDate,
                parentReminderId = if (request.isRecurring) reminderId else null
            )

            withContext(Dispatchers.IO) {
                reminderDao.insertReminder(reminder)
                reminderScheduler.scheduleReminder(reminder)
                // Best-effort Firebase push so smart reminders show up under
                // users/{accountId}/reminders/{deviceId}/{reminderId} immediately on creation.
                syncSingleReminder(reminder)
            }

            Log.d("ReminderRepository", "Created reminder for note: ${request.noteTitle}" +
                if (request.isRecurring) " (recurring: ${request.recurrenceType})" else "")
            Result.success(reminder.id)
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error creating reminder", e)
            Result.failure(e)
        }
    }

    suspend fun getRemindersForNote(noteId: String): List<ReminderEntity> {
        return withContext(Dispatchers.IO) {
            reminderDao.getRemindersForNote(noteId)
        }
    }

    fun getAllActiveReminders(): Flow<List<ReminderEntity>> {
        return reminderDao.getAllActiveReminders()
    }

    suspend fun cancelReminder(reminderId: String): Result<Unit> {
        return try {
            withContext(Dispatchers.IO) {
                reminderDao.deactivateReminder(reminderId)
                reminderScheduler.cancelReminder(reminderId)
                deleteRemoteReminder(reminderId)
            }
            Result.success(Unit)
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error cancelling reminder", e)
            Result.failure(e)
        }
    }

    suspend fun deleteRemindersForNote(noteId: String): Result<Unit> {
        return try {
            withContext(Dispatchers.IO) {
                val reminders = reminderDao.getRemindersForNote(noteId)
                reminders.forEach { reminder ->
                    reminderScheduler.cancelReminder(reminder.id)
                    deleteRemoteReminder(reminder.id)
                }
                reminderDao.deleteRemindersForNote(noteId)
            }
            Result.success(Unit)
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error deleting reminders for note", e)
            Result.failure(e)
        }
    }

    // BUG-031 FIX: Proper suspend function instead of launching unscoped coroutine
    suspend fun cleanupOldReminders() {
        withContext(Dispatchers.IO) {
            try {
                val currentTime = System.currentTimeMillis()
                reminderDao.cleanupOldReminders(currentTime)
            } catch (e: Exception) {
                Log.e("ReminderRepository", "Error cleaning up old reminders", e)
            }
        }
    }

    suspend fun rescheduleAllReminders() {
        try {
            withContext(Dispatchers.IO) {
                // Get all active reminders by retrieving the first snapshot of the Flow
                val reminders = getAllActiveReminders().first()
                val currentTime = System.currentTimeMillis()
                val futureReminders = reminders.filter { it.reminderTime > currentTime }
                reminderScheduler.rescheduleAllReminders(futureReminders)
            }
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error rescheduling reminders", e)
        }
    }
}

package com.amvarpvtltd.swiftNote.reminders

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.auth.DeviceManager
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.notifications.ReminderScheduler
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.utils.NetworkManager
import com.google.firebase.database.DatabaseReference
import com.google.firebase.database.FirebaseDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext
import java.util.*

class ReminderRepository(private val context: Context) {

    private val reminderDao = AppDatabase.getInstance(context).reminderDao()
    private val reminderScheduler = ReminderScheduler(context)
    private val database = FirebaseDatabase.getInstance()

    /**
     * Resolve the Firebase path for reminders, mirroring [com.amvarpvtltd.swiftNote.repository.NoteRepository.resolveNotesRef]:
     *   users/{accountId}/reminders/{deviceId}
     * accountId = stored passphrase if synced, otherwise local deviceId.
     */
    private fun resolveRemindersRef(): DatabaseReference {
        val deviceId = DeviceManager.getOrCreateDeviceId(context)
        val accountId = PassphraseManager.getStoredPassphrase(context).takeIf { !it.isNullOrEmpty() } ?: deviceId
        return database.getReference("users").child(accountId).child("reminders").child(deviceId)
    }

    /**
     * Best-effort push of a single reminder to Firebase. Mirrors NoteRepository.syncSingleNote.
     * Silently no-ops when offline so the local DB stays the source of truth.
     *
     * SECURITY: never log accountId / deviceId / passphrase — these are the AES encryption keys
     * for all user content. Log only the reminder UUID and bounded error messages.
     */
    private suspend fun syncSingleReminder(reminder: ReminderEntity) {
        if (!NetworkManager.getInstance(context).isConnected()) {
            Log.d("ReminderRepository", "Offline — skipping Firebase push for reminder ${reminder.id}")
            return
        }
        try {
            // Firebase rules require auth != null — make sure anon sign-in resolved first.
            val authResult = PassphraseManager.ensureAuthenticated()
            if (authResult.isFailure) {
                Log.w("ReminderRepository", "Auth not ready, skipping push for reminder ${reminder.id}")
                return
            }
            val deviceId = DeviceManager.getOrCreateDeviceId(context)
            val accountId = PassphraseManager.getStoredPassphrase(context).takeIf { !it.isNullOrEmpty() } ?: deviceId
            val encrypted = reminder.toEncryptedData(accountId)
            database.getReference("users")
                .child(accountId)
                .child("reminders")
                .child(deviceId)
                .child(reminder.id)
                .setValue(encrypted)
                .await()
            // Log.d only — ProGuard strips this in release. Never logs accountId / deviceId.
            Log.d("ReminderRepository", "Pushed reminder ${reminder.id} to Firebase")
        } catch (e: Exception) {
            // Pass message only — full throwable stack can include path with accountId.
            Log.w("ReminderRepository", "Failed to push reminder ${reminder.id}: ${e.message}")
        }
    }

    /** Best-effort removal of a single reminder from Firebase. */
    private suspend fun deleteRemoteReminder(reminderId: String) {
        if (!NetworkManager.getInstance(context).isConnected()) return
        try {
            resolveRemindersRef().child(reminderId).removeValue().await()
        } catch (e: Exception) {
            Log.w("ReminderRepository", "Failed to remove remote reminder $reminderId: ${e.message}")
        }
    }

    suspend fun createReminder(request: ReminderRequest): Result<String> {
        return try {
            val reminderId = UUID.randomUUID().toString()
            val reminder = ReminderEntity(
                id = reminderId,
                noteId = request.noteId,
                noteTitle = request.noteTitle,
                noteDescription = request.noteDescription,
                reminderTime = request.getReminderTime(),
                // Phase 2: Include recurrence data
                recurrenceType = request.recurrenceType,
                recurrenceInterval = request.recurrenceInterval,
                recurrenceDaysOfWeek = request.recurrenceDaysOfWeek,
                recurrenceEndDate = request.recurrenceEndDate,
                parentReminderId = if (request.isRecurring) reminderId else null
            )

            withContext(Dispatchers.IO) {
                reminderDao.insertReminder(reminder)
                reminderScheduler.scheduleReminder(reminder)
                // Best-effort Firebase push so smart reminders show up under
                // users/{accountId}/reminders/{deviceId}/{reminderId} immediately on creation.
                syncSingleReminder(reminder)
            }

            Log.d("ReminderRepository", "Created reminder for note: ${request.noteTitle}" +
                if (request.isRecurring) " (recurring: ${request.recurrenceType})" else "")
            Result.success(reminder.id)
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error creating reminder", e)
            Result.failure(e)
        }
    }

    suspend fun getRemindersForNote(noteId: String): List<ReminderEntity> {
        return withContext(Dispatchers.IO) {
            reminderDao.getRemindersForNote(noteId)
        }
    }

    fun getAllActiveReminders(): Flow<List<ReminderEntity>> {
        return reminderDao.getAllActiveReminders()
    }

    suspend fun cancelReminder(reminderId: String): Result<Unit> {
        return try {
            withContext(Dispatchers.IO) {
                reminderDao.deactivateReminder(reminderId)
                reminderScheduler.cancelReminder(reminderId)
                deleteRemoteReminder(reminderId)
            }
            Result.success(Unit)
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error cancelling reminder", e)
            Result.failure(e)
        }
    }

    suspend fun deleteRemindersForNote(noteId: String): Result<Unit> {
        return try {
            withContext(Dispatchers.IO) {
                val reminders = reminderDao.getRemindersForNote(noteId)
                reminders.forEach { reminder ->
                    reminderScheduler.cancelReminder(reminder.id)
                    deleteRemoteReminder(reminder.id)
                }
                reminderDao.deleteRemindersForNote(noteId)
            }
            Result.success(Unit)
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error deleting reminders for note", e)
            Result.failure(e)
        }
    }

    // BUG-031 FIX: Proper suspend function instead of launching unscoped coroutine
    suspend fun cleanupOldReminders() {
        withContext(Dispatchers.IO) {
            try {
                val currentTime = System.currentTimeMillis()
                reminderDao.cleanupOldReminders(currentTime)
            } catch (e: Exception) {
                Log.e("ReminderRepository", "Error cleaning up old reminders", e)
            }
        }
    }

    suspend fun rescheduleAllReminders() {
        try {
            withContext(Dispatchers.IO) {
                // Get all active reminders by retrieving the first snapshot of the Flow
                val reminders = getAllActiveReminders().first()
                val currentTime = System.currentTimeMillis()
                val futureReminders = reminders.filter { it.reminderTime > currentTime }
                reminderScheduler.rescheduleAllReminders(futureReminders)
            }
        } catch (e: Exception) {
            Log.e("ReminderRepository", "Error rescheduling reminders", e)
        }
    }
}

package com.amvarpvtltd.swiftNote.richtext

import org.jsoup.Jsoup
import org.jsoup.nodes.Element
import org.jsoup.nodes.Node
import org.jsoup.nodes.TextNode

/**
 * Facade over the MohamedRejeb compose-rich-editor library.
 *
 * All external callers that previously used RichTextRenderer go through here.
 * Keeping library calls in one place makes future swaps a single-file change.
 */
object RichTextBridge {

    /**
     * Strip all HTML tags and return plain text.
     * Used by: SmartEntityDetector, SearchAndSortManager, AutoTitleGenerator.
     *
     * Replaces RichTextRenderer.stripHtmlToPlainText().
     */
    fun stripHtmlToPlainText(html: String): String {
        if (html.isBlank() || '<' !in html) return html
        return try {
            Jsoup.parseBodyFragment(html).text()
        } catch (e: Exception) {
            // Fallback: strip tags with regex if Jsoup fails (should never happen)
            html.replace(Regex("<[^>]+>"), "")
        }
    }

    /**
     * Convert HTML to well-formatted plain text that preserves structural
     * formatting (paragraphs, headings, lists, code blocks, links).
     * Also strips any remaining Markdown-style formatting markers (e.g. *bold*).
     *
     * Used by: ShareUtils for copy-to-clipboard and share operations so the
     * recipient sees a readable, structured note — not a flat wall of text.
     */
    fun htmlToFormattedPlainText(html: String): String {
        if (html.isBlank()) return html

        // If no HTML tags, check if it's markdown — convert to HTML first for proper structure
        val effectiveHtml = if ('<' !in html) {
            if (MarkdownToHtmlConverter.containsMarkdown(html)) {
                // Convert markdown → HTML so we can walk the DOM tree for structure
                MarkdownToHtmlConverter.convert(html) ?: html
            } else {
                // Plain text with no formatting — just return as-is preserving line breaks
                return html
            }
        } else {
            html
        }

        // If still no HTML after markdown conversion attempt, return stripped
        if ('<' !in effectiveHtml) return stripMarkdownFormatting(effectiveHtml)

        return try {
            val doc = Jsoup.parseBodyFragment(effectiveHtml)
            val sb = StringBuilder()
            renderNode(doc.body(), sb, listDepth = 0, orderedIndex = null)
            // Clean up excessive blank lines then strip markdown markers
            val structured = sb.toString()
                .replace(Regex("[ \\t]+\\n"), "\n")       // trailing spaces
                .replace(Regex("\\n{3,}"), "\n\n")          // max 2 consecutive newlines
                .trim()
            stripMarkdownFormatting(structured)
        } catch (e: Exception) {
            stripMarkdownFormatting(stripHtmlToPlainText(effectiveHtml))
        }
    }

    /**
     * Strip Markdown-style formatting markers from plain text:
     * - **bold** or *bold* → bold (remove asterisks)
     * - __bold__ or _italic_ → text (remove underscores)
     * - Lines starting with "- " → "• " (bullet points)
     * - Lines starting with "* " (list item) → "• "
     * - Heading markers like "# ", "## " → removed
     */
    private fun stripMarkdownFormatting(text: String): String {
        if (text.isBlank()) return text

        var result = text

        // Strip bold/italic markers: **text** → text, *text* → text
        // Handle double asterisks first, then single
        result = result.replace(Regex("\\*\\*(.+?)\\*\\*")) { it.groupValues[1] }

        // Single *text* — match asterisks that wrap words/phrases (not math like 2*3)
        // Handles: *bold text*, beginning of line, after space/punctuation
        result = result.replace(Regex("(^|[\\s(\\[])\\*([^*\\n]+?)\\*([\\s),.;:!?\\]\\-]|$)", RegexOption.MULTILINE)) { 
            "${it.groupValues[1]}${it.groupValues[2]}${it.groupValues[3]}" 
        }

        // Strip __text__ and _text_ (underscore bold/italic)
        result = result.replace(Regex("__(.+?)__")) { it.groupValues[1] }
        result = result.replace(Regex("(^|[\\s(\\[])_([^_\\n]+?)_([\\s),.;:!?\\]\\-]|$)", RegexOption.MULTILINE)) {
            "${it.groupValues[1]}${it.groupValues[2]}${it.groupValues[3]}"
        }

        // Convert "- " at line start to "• " (markdown unordered list)
        result = result.replace(Regex("^- ", RegexOption.MULTILINE), "• ")

        // Convert "* " at line start to "• " (markdown unordered list alternative)
        result = result.replace(Regex("^\\* ", RegexOption.MULTILINE), "• ")

        // Strip heading markers "# ", "## ", "### " etc. at line start
        result = result.replace(Regex("^#{1,6}\\s+", RegexOption.MULTILINE), "")

        return result
    }

    private fun renderNode(
        node: Node,
        sb: StringBuilder,
        listDepth: Int,
        orderedIndex: MutableList<Int>?
    ) {
        when (node) {
            is TextNode -> {
                val text = node.wholeText
                // Skip pure-whitespace nodes between block elements
                if (text.isNotBlank()) {
                    sb.append(text)
                }
            }

            is Element -> {
                val tag = node.tagName().lowercase()
                when (tag) {
                    "br" -> sb.append("\n")

                    "p", "div" -> {
                        ensureNewline(sb)
                        renderChildren(node, sb, listDepth, orderedIndex)
                        sb.append("\n")
                    }

                    "h1", "h2", "h3", "h4", "h5", "h6" -> {
                        ensureNewline(sb)
                        renderChildren(node, sb, listDepth, orderedIndex)
                        sb.append("\n")
                    }

                    "ul" -> {
                        ensureNewline(sb)
                        for (child in node.childNodes()) {
                            renderNode(child, sb, listDepth + 1, null)
                        }
                    }

                    "ol" -> {
                        ensureNewline(sb)
                        val idx = mutableListOf(0)
                        for (child in node.childNodes()) {
                            renderNode(child, sb, listDepth + 1, idx)
                        }
                    }

                    "li" -> {
                        val indent = "  ".repeat((listDepth - 1).coerceAtLeast(0))
                        if (orderedIndex != null) {
                            orderedIndex[0]++
                            sb.append("$indent${orderedIndex[0]}. ")
                        } else {
                            sb.append("$indent• ")
                        }
                        renderChildren(node, sb, listDepth, orderedIndex)
                        sb.append("\n")
                    }

                    "pre", "code" -> {
                        val isBlock = tag == "pre" || node.parent()?.tagName()?.lowercase() != "pre"
                                && node.children().isNotEmpty()
                        if (isBlock && tag == "pre") {
                            ensureNewline(sb)
                        }
                        renderChildren(node, sb, listDepth, orderedIndex)
                        if (isBlock && tag == "pre") {
                            sb.append("\n")
                        }
                    }

                    "a" -> {
                        val linkText = node.text()
                        val href = node.attr("href")
                        if (href.isNotBlank() && linkText != href) {
                            sb.append("$linkText ($href)")
                        } else {
                            sb.append(linkText)
                        }
                    }

                    "input" -> {
                        // Checklist items
                        val isChecked = node.hasAttr("checked")
                        sb.append(if (isChecked) "☑ " else "☐ ")
                    }

                    // Inline formatting tags — just render children (no markdown wrappers needed for plain text)
                    "b", "strong", "i", "em", "u" -> {
                        renderChildren(node, sb, listDepth, orderedIndex)
                    }

                    // body or unknown — just recurse
                    else -> {
                        renderChildren(node, sb, listDepth, orderedIndex)
                    }
                }
            }

            else -> {
                // Other node types (comments, etc.) — ignore
            }
        }
    }

    private fun renderChildren(
        element: Element,
        sb: StringBuilder,
        listDepth: Int,
        orderedIndex: MutableList<Int>?
    ) {
        for (child in element.childNodes()) {
            renderNode(child, sb, listDepth, orderedIndex)
        }
    }

    /** Ensure we're on a fresh line without adding excessive blank lines. */
    private fun ensureNewline(sb: StringBuilder) {
        if (sb.isNotEmpty() && sb.last() != '\n') {
            sb.append("\n")
        }
    }

    /**
     * Pre-process HTML (or plain text) so that leading whitespace (spaces/tabs
     * used for indentation) is preserved when rendered by an HTML engine.
     *
     * HTML renderers collapse consecutive whitespace to a single space by
     * default, so "    word" inside a <p> loses its indentation.  This
     * function converts those leading spaces/tabs to non-breaking-space
     * entities (&nbsp;) so the visual indentation survives rendering.
     *
     * - Plain text (no '<'): converts to HTML, turning '\n' into <br> and
     *   leading spaces/tabs on each line into &nbsp; sequences.
     * - HTML content: replaces space/tab runs that appear immediately after
     *   a '>' boundary (i.e. at the start of a text node) with &nbsp;.
     */
    fun preserveLeadingWhitespace(html: String): String {
        if (html.isBlank()) return html

        if ('<' !in html) {
            // Pure plain text — convert to displayable HTML preserving indentation
            return html
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .split("\n")
                .joinToString("<br>") { line ->
                    val leading = line.length - line.trimStart(' ', '\t').length
                    if (leading > 0) {
                        line.substring(0, leading)
                            .replace(" ", "&nbsp;")
                            .replace("\t", "&nbsp;&nbsp;&nbsp;&nbsp;") +
                                line.substring(leading)
                    } else {
                        line
                    }
                }
        }

        // HTML content — replace space/tab runs that directly follow a '>'
        // (i.e. at the start of a text node inside a block element).
        return html
            .replace(Regex("(?<=>)([ ]+)")) { match ->
                "&nbsp;".repeat(match.value.length)
            }
            .replace(Regex("(?<=>)(\\t+)")) { match ->
                "&nbsp;&nbsp;&nbsp;&nbsp;".repeat(match.value.length)
            }
    }

    /**
     * Returns true if the string contains any HTML we recognise.
     * Used in save/load paths to decide rendering mode.
     *
     * Replaces RichTextRenderer.containsHtml().
     */
    fun containsHtml(text: String): Boolean {
        if (text.isBlank() || '<' !in text) return false
        return Regex(
            "<(/?)(b|strong|i|em|u|h[1-6]|p|br|ul|ol|li|a|code|pre|input|div|span|s)\\b[^>]*>",
            RegexOption.IGNORE_CASE
        ).containsMatchIn(text)
    }
}

package com.amvarpvtltd.swiftNote.richtext

import org.jsoup.Jsoup
import org.jsoup.nodes.Element
import org.jsoup.nodes.Node
import org.jsoup.nodes.TextNode

/**
 * Facade over the MohamedRejeb compose-rich-editor library.
 *
 * All external callers that previously used RichTextRenderer go through here.
 * Keeping library calls in one place makes future swaps a single-file change.
 */
object RichTextBridge {

    /**
     * Strip all HTML tags and return plain text.
     * Used by: SmartEntityDetector, SearchAndSortManager, AutoTitleGenerator.
     *
     * Replaces RichTextRenderer.stripHtmlToPlainText().
     */
    fun stripHtmlToPlainText(html: String): String {
        if (html.isBlank() || '<' !in html) return html
        return try {
            Jsoup.parseBodyFragment(html).text()
        } catch (e: Exception) {
            // Fallback: strip tags with regex if Jsoup fails (should never happen)
            html.replace(Regex("<[^>]+>"), "")
        }
    }

    /**
     * Convert HTML to well-formatted plain text that preserves structural
     * formatting (paragraphs, headings, lists, code blocks, links).
     * Also strips any remaining Markdown-style formatting markers (e.g. *bold*).
     *
     * Used by: ShareUtils for copy-to-clipboard and share operations so the
     * recipient sees a readable, structured note — not a flat wall of text.
     */
    fun htmlToFormattedPlainText(html: String): String {
        if (html.isBlank()) return html

        // If no HTML tags, check if it's markdown — convert to HTML first for proper structure
        val effectiveHtml = if ('<' !in html) {
            if (MarkdownToHtmlConverter.containsMarkdown(html)) {
                // Convert markdown → HTML so we can walk the DOM tree for structure
                MarkdownToHtmlConverter.convert(html) ?: html
            } else {
                // Plain text with no formatting — just return as-is preserving line breaks
                return html
            }
        } else {
            html
        }

        // If still no HTML after markdown conversion attempt, return stripped
        if ('<' !in effectiveHtml) return stripMarkdownFormatting(effectiveHtml)

        return try {
            val doc = Jsoup.parseBodyFragment(effectiveHtml)
            val sb = StringBuilder()
            renderNode(doc.body(), sb, listDepth = 0, orderedIndex = null)
            // Clean up excessive blank lines then strip markdown markers
            val structured = sb.toString()
                .replace(Regex("[ \\t]+\\n"), "\n")       // trailing spaces
                .replace(Regex("\\n{3,}"), "\n\n")          // max 2 consecutive newlines
                .trim()
            stripMarkdownFormatting(structured)
        } catch (e: Exception) {
            stripMarkdownFormatting(stripHtmlToPlainText(effectiveHtml))
        }
    }

    /**
     * Strip Markdown-style formatting markers from plain text:
     * - **bold** or *bold* → bold (remove asterisks)
     * - __bold__ or _italic_ → text (remove underscores)
     * - Lines starting with "- " → "• " (bullet points)
     * - Lines starting with "* " (list item) → "• "
     * - Heading markers like "# ", "## " → removed
     */
    private fun stripMarkdownFormatting(text: String): String {
        if (text.isBlank()) return text

        var result = text

        // Strip bold/italic markers: **text** → text, *text* → text
        // Handle double asterisks first, then single
        result = result.replace(Regex("\\*\\*(.+?)\\*\\*")) { it.groupValues[1] }

        // Single *text* — match asterisks that wrap words/phrases (not math like 2*3)
        // Handles: *bold text*, beginning of line, after space/punctuation
        result = result.replace(Regex("(^|[\\s(\\[])\\*([^*\\n]+?)\\*([\\s),.;:!?\\]\\-]|$)", RegexOption.MULTILINE)) { 
            "${it.groupValues[1]}${it.groupValues[2]}${it.groupValues[3]}" 
        }

        // Strip __text__ and _text_ (underscore bold/italic)
        result = result.replace(Regex("__(.+?)__")) { it.groupValues[1] }
        result = result.replace(Regex("(^|[\\s(\\[])_([^_\\n]+?)_([\\s),.;:!?\\]\\-]|$)", RegexOption.MULTILINE)) {
            "${it.groupValues[1]}${it.groupValues[2]}${it.groupValues[3]}"
        }

        // Convert "- " at line start to "• " (markdown unordered list)
        result = result.replace(Regex("^- ", RegexOption.MULTILINE), "• ")

        // Convert "* " at line start to "• " (markdown unordered list alternative)
        result = result.replace(Regex("^\\* ", RegexOption.MULTILINE), "• ")

        // Strip heading markers "# ", "## ", "### " etc. at line start
        result = result.replace(Regex("^#{1,6}\\s+", RegexOption.MULTILINE), "")

        return result
    }

    private fun renderNode(
        node: Node,
        sb: StringBuilder,
        listDepth: Int,
        orderedIndex: MutableList<Int>?
    ) {
        when (node) {
            is TextNode -> {
                val text = node.wholeText
                // Skip pure-whitespace nodes between block elements
                if (text.isNotBlank()) {
                    sb.append(text)
                }
            }

            is Element -> {
                val tag = node.tagName().lowercase()
                when (tag) {
                    "br" -> sb.append("\n")

                    "p", "div" -> {
                        ensureNewline(sb)
                        renderChildren(node, sb, listDepth, orderedIndex)
                        sb.append("\n")
                    }

                    "h1", "h2", "h3", "h4", "h5", "h6" -> {
                        ensureNewline(sb)
                        renderChildren(node, sb, listDepth, orderedIndex)
                        sb.append("\n")
                    }

                    "ul" -> {
                        ensureNewline(sb)
                        for (child in node.childNodes()) {
                            renderNode(child, sb, listDepth + 1, null)
                        }
                    }

                    "ol" -> {
                        ensureNewline(sb)
                        val idx = mutableListOf(0)
                        for (child in node.childNodes()) {
                            renderNode(child, sb, listDepth + 1, idx)
                        }
                    }

                    "li" -> {
                        val indent = "  ".repeat((listDepth - 1).coerceAtLeast(0))
                        if (orderedIndex != null) {
                            orderedIndex[0]++
                            sb.append("$indent${orderedIndex[0]}. ")
                        } else {
                            sb.append("$indent• ")
                        }
                        renderChildren(node, sb, listDepth, orderedIndex)
                        sb.append("\n")
                    }

                    "pre", "code" -> {
                        val isBlock = tag == "pre" || node.parent()?.tagName()?.lowercase() != "pre"
                                && node.children().isNotEmpty()
                        if (isBlock && tag == "pre") {
                            ensureNewline(sb)
                        }
                        renderChildren(node, sb, listDepth, orderedIndex)
                        if (isBlock && tag == "pre") {
                            sb.append("\n")
                        }
                    }

                    "a" -> {
                        val linkText = node.text()
                        val href = node.attr("href")
                        if (href.isNotBlank() && linkText != href) {
                            sb.append("$linkText ($href)")
                        } else {
                            sb.append(linkText)
                        }
                    }

                    "input" -> {
                        // Checklist items
                        val isChecked = node.hasAttr("checked")
                        sb.append(if (isChecked) "☑ " else "☐ ")
                    }

                    // Inline formatting tags — just render children (no markdown wrappers needed for plain text)
                    "b", "strong", "i", "em", "u" -> {
                        renderChildren(node, sb, listDepth, orderedIndex)
                    }

                    // body or unknown — just recurse
                    else -> {
                        renderChildren(node, sb, listDepth, orderedIndex)
                    }
                }
            }

            else -> {
                // Other node types (comments, etc.) — ignore
            }
        }
    }

    private fun renderChildren(
        element: Element,
        sb: StringBuilder,
        listDepth: Int,
        orderedIndex: MutableList<Int>?
    ) {
        for (child in element.childNodes()) {
            renderNode(child, sb, listDepth, orderedIndex)
        }
    }

    /** Ensure we're on a fresh line without adding excessive blank lines. */
    private fun ensureNewline(sb: StringBuilder) {
        if (sb.isNotEmpty() && sb.last() != '\n') {
            sb.append("\n")
        }
    }

    /**
     * Pre-process HTML (or plain text) so that leading whitespace (spaces/tabs
     * used for indentation) is preserved when rendered by an HTML engine.
     *
     * HTML renderers collapse consecutive whitespace to a single space by
     * default, so "    word" inside a <p> loses its indentation.  This
     * function converts those leading spaces/tabs to non-breaking-space
     * entities (&nbsp;) so the visual indentation survives rendering.
     *
     * - Plain text (no '<'): converts to HTML, turning '\n' into <br> and
     *   leading spaces/tabs on each line into &nbsp; sequences.
     * - HTML content: replaces space/tab runs that appear immediately after
     *   a '>' boundary (i.e. at the start of a text node) with &nbsp;.
     */
    fun preserveLeadingWhitespace(html: String): String {
        if (html.isBlank()) return html

        if ('<' !in html) {
            // Pure plain text — convert to displayable HTML preserving indentation
            return html
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .split("\n")
                .joinToString("<br>") { line ->
                    val leading = line.length - line.trimStart(' ', '\t').length
                    if (leading > 0) {
                        line.substring(0, leading)
                            .replace(" ", "&nbsp;")
                            .replace("\t", "&nbsp;&nbsp;&nbsp;&nbsp;") +
                                line.substring(leading)
                    } else {
                        line
                    }
                }
        }

        // HTML content — replace space/tab runs that directly follow a '>'
        // ONLY when the spaces lead into actual text content (not into another tag).
        // Replacing spaces between tags (e.g. <ol>\n  <li>) breaks list/heading structure
        // in compose-rich-editor because &nbsp; inside <li>/<ul>/<ol> prevents the
        // library from recognising the list hierarchy and it collapses items to a single line.
        return html
            .replace(Regex("(?<=>)([ ]+)(?!<)")) { match ->
                "&nbsp;".repeat(match.value.length)
            }
            .replace(Regex("(?<=>)(\\t+)(?!<)")) { match ->
                "&nbsp;&nbsp;&nbsp;&nbsp;".repeat(match.value.length)
            }
    }

    /**
     * Returns true if the string contains any HTML we recognise.
     * Used in save/load paths to decide rendering mode.
     *
     * Replaces RichTextRenderer.containsHtml().
     */
    fun containsHtml(text: String): Boolean {
        if (text.isBlank() || '<' !in text) return false
        return Regex(
            "<(/?)(b|strong|i|em|u|h[1-6]|p|br|ul|ol|li|a|code|pre|input|div|span|s)\\b[^>]*>",
            RegexOption.IGNORE_CASE
        ).containsMatchIn(text)
    }
}

package com.amvarpvtltd.swiftNote.richtext

import androidx.compose.ui.text.TextRange
import androidx.compose.ui.text.input.TextFieldValue

/**
 * Pure, stateless helper functions for HTML-based rich text editing.
 *
 * All functions take a [TextFieldValue] (text + cursor/selection) and return a new
 * [TextFieldValue] with the formatting applied.  They never touch Compose state or the
 * UI layer — they are trivially unit-testable.
 *
 * Phase 2 implementation.
 */
object RichTextEditorHelpers {

    // ─── Inline tags ──────────────────────────────────────────────────────────

    /**
     * Toggle an inline HTML tag around the current selection.
     *
     * Behaviour:
     * - **No selection (collapsed cursor) & already inside tag:** removes the surrounding tags (toggle off).
     * - **No selection (collapsed cursor) & not inside tag:** inserts `<tag></tag>` and places cursor between.
     * - **Selection already wrapped:** unwraps — removes the surrounding tags.
     * - **New selection:** wraps the selected text with `<tag>…</tag>`.
     */
    fun toggleInlineTag(value: TextFieldValue, tag: String): TextFieldValue {
        val openTag  = "<$tag>"
        val closeTag = "</$tag>"
        val sel  = value.selection
        val text = value.text

        if (sel.collapsed) {
            // Check if cursor is currently inside an existing <tag>...</tag> pair
            val before = text.substring(0, sel.start)
            val after  = text.substring(sel.start)

            // Use regex for exact tag matching (avoids <li> matching <i>)
            val openRegex = Regex("<$tag(\\s[^>]*)?>", RegexOption.IGNORE_CASE)
            val closeRegex = Regex("</$tag>", RegexOption.IGNORE_CASE)

            val openMatches = openRegex.findAll(before).toList()
            if (openMatches.isNotEmpty()) {
                val lastOpen = openMatches.last()
                val afterOpenTag = lastOpen.range.last + 1
                // Check there's no close tag between open tag and cursor
                val closeInBetween = closeRegex.find(before, startIndex = afterOpenTag)
                if (closeInBetween == null) {
                    // We ARE inside the tag — find the close tag after cursor and remove both
                    val closeAfterCursor = closeRegex.find(after)
                    if (closeAfterCursor != null) {
                        // Remove the close tag after cursor
                        val afterWithoutClose = after.removeRange(
                            closeAfterCursor.range.first,
                            closeAfterCursor.range.last + 1
                        )
                        // Remove the open tag before cursor
                        val beforeWithoutOpen = before.removeRange(
                            lastOpen.range.first,
                            lastOpen.range.last + 1
                        )
                        val newText = beforeWithoutOpen + afterWithoutClose
                        val newCursor = beforeWithoutOpen.length
                        return value.copy(text = newText, selection = TextRange(newCursor))
                    }
                }
            }

            // Not inside existing tag — insert empty tag pair
            val newText = text.substring(0, sel.start) + openTag + closeTag + text.substring(sel.start)
            return value.copy(
                text      = newText,
                selection = TextRange(sel.start + openTag.length)
            )
        }

        val before = text.substring(0, sel.start)
        val after  = text.substring(sel.end)

        // Already wrapped → unwrap
        if (before.endsWith(openTag) && after.startsWith(closeTag)) {
            val newText = before.dropLast(openTag.length) +
                          text.substring(sel.start, sel.end) +
                          after.drop(closeTag.length)
            return value.copy(
                text      = newText,
                selection = TextRange(sel.start - openTag.length, sel.end - openTag.length)
            )
        }

        // Check if selection is fully inside existing tags — unwrap those tags
        val openRegex = Regex("<$tag(\\s[^>]*)?>", RegexOption.IGNORE_CASE)
        val closeRegex = Regex("</$tag>", RegexOption.IGNORE_CASE)
        val openMatches = openRegex.findAll(before).toList()
        if (openMatches.isNotEmpty()) {
            val lastOpen = openMatches.last()
            val afterOpenTag = lastOpen.range.last + 1
            val closeInBetween = closeRegex.find(before, startIndex = afterOpenTag)
            if (closeInBetween == null) {
                val closeAfterSelection = closeRegex.find(after)
                if (closeAfterSelection != null) {
                    // Remove surrounding tags
                    val afterWithoutClose = after.removeRange(
                        closeAfterSelection.range.first,
                        closeAfterSelection.range.last + 1
                    )
                    val beforeWithoutOpen = before.removeRange(
                        lastOpen.range.first,
                        lastOpen.range.last + 1
                    )
                    val selected = text.substring(sel.start, sel.end)
                    val newText = beforeWithoutOpen + selected + afterWithoutClose
                    val openLen = lastOpen.range.last - lastOpen.range.first + 1
                    return value.copy(
                        text = newText,
                        selection = TextRange(sel.start - openLen, sel.end - openLen)
                    )
                }
            }
        }

        // Wrap selection
        val selected = text.substring(sel.start, sel.end)
        val newText  = before + openTag + selected + closeTag + after
        return value.copy(
            text      = newText,
            selection = TextRange(sel.start + openTag.length, sel.end + openTag.length)
        )
    }

    /** Bold — toggles `<b>…</b>` around selection. */
    fun toggleBold(value: TextFieldValue)      = toggleInlineTag(value, "b")

    /** Italic — toggles `<i>…</i>` around selection. */
    fun toggleItalic(value: TextFieldValue)    = toggleInlineTag(value, "i")

    /** Underline — toggles `<u>…</u>` around selection. */
    fun toggleUnderline(value: TextFieldValue) = toggleInlineTag(value, "u")

    /** Inline code — toggles `<code>…</code>` around selection. */
    fun toggleCode(value: TextFieldValue)      = toggleInlineTag(value, "code")

    // ─── Headings ─────────────────────────────────────────────────────────────

    /**
     * Apply (or remove) a heading to the line containing the cursor.
     *
     * - [level] 1 → `<h1>`, 2 → `<h2>`, 0 → removes any existing heading.
     * - If the line already has the requested heading, it is removed (toggle off).
     */
    fun applyHeading(value: TextFieldValue, level: Int): TextFieldValue {
        val text     = value.text
        val cursor   = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1   // 0 if no newline found
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val existingHeadingRegex = Regex("^<h([12])>(.*)</h([12])>$", RegexOption.DOT_MATCHES_ALL)
        val match = existingHeadingRegex.matchEntire(line.trim())

        val newLine: String = when {
            // Toggle off: same level already applied
            match != null && match.groupValues[1] == level.toString() -> match.groupValues[2]
            // Apply heading (replacing any existing heading)
            level in 1..2 -> {
                val plainContent = if (match != null) match.groupValues[2] else line
                "<h$level>$plainContent</h$level>"
            }
            // level == 0 → strip heading
            match != null -> match.groupValues[2]
            else          -> line
        }

        val newText = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        // Keep cursor inside the new content
        val newCursor = (lineStart + newLine.length).coerceAtMost(newText.length)
        return value.copy(text = newText, selection = TextRange(newCursor))
    }

    // ─── Lists ────────────────────────────────────────────────────────────────

    /**
     * Toggle unordered list formatting for the current line.
     *
     * - If the line already has a `<li>` wrapper (inside `<ul>`), strip it.
     * - Otherwise wrap the line content in `<ul><li>...</li></ul>`.
     */
    fun toggleBulletList(value: TextFieldValue): TextFieldValue {
        val text   = value.text
        val cursor = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val ulRegex = Regex("""^<ul><li>(.*)</li></ul>$""")
        val bulletPrefix = Regex("""^•\s?""")
        val newLine = when {
            ulRegex.matches(line) -> ulRegex.find(line)!!.groupValues[1]
            bulletPrefix.containsMatchIn(line) -> line.replace(bulletPrefix, "")
            else -> "<ul><li>$line</li></ul>"
        }
        val newText = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        val newCursor = (lineStart + newLine.length).coerceAtMost(newText.length)
        return value.copy(text = newText, selection = TextRange(newCursor))
    }

    /**
     * Toggle ordered (numbered) list formatting for the current line.
     *
     * - If the line already has a `<li>` wrapper (inside `<ol>`), strip it.
     * - Otherwise wrap the line content in `<ol><li>...</li></ol>`.
     */
    fun toggleNumberedList(value: TextFieldValue): TextFieldValue {
        val text   = value.text
        val cursor = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val olRegex = Regex("""^<ol><li>(.*)</li></ol>$""")
        val numPrefix = Regex("""^\d+\.\s?""")
        val newLine = when {
            olRegex.matches(line) -> olRegex.find(line)!!.groupValues[1]
            numPrefix.containsMatchIn(line) -> line.replace(numPrefix, "")
            else -> "<ol><li>$line</li></ol>"
        }
        val newText = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        val newCursor = (lineStart + newLine.length).coerceAtMost(newText.length)
        return value.copy(text = newText, selection = TextRange(newCursor))
    }

    /** Insert an unchecked checkbox (`<input type="checkbox">`) at the cursor. */
    fun insertCheckbox(value: TextFieldValue, checked: Boolean = false): TextFieldValue {
        val marker  = if (checked) "<input type=\"checkbox\" checked>" else "<input type=\"checkbox\">"
        val newText = value.text.substring(0, value.selection.start) +
                      marker + " " +
                      value.text.substring(value.selection.start)
        return value.copy(
            text      = newText,
            selection = TextRange(value.selection.start + marker.length + 1)
        )
    }

    // ─── Links ────────────────────────────────────────────────────────────────

    /**
     * Insert a hyperlink at the cursor.
     *
     * - If [displayText] is provided (or text was selected), uses it as link label.
     * - Otherwise uses the URL itself as label.
     * - Ensures the URL starts with `"https://"` if it has no scheme.
     */
    fun insertLink(
        value: TextFieldValue,
        url: String,
        displayText: String?
    ): TextFieldValue {
        val safeUrl  = if (url.startsWith("http://") || url.startsWith("https://")) url else "https://$url"
        val label    = displayText?.takeIf { it.isNotBlank() } ?: safeUrl
        val linkHtml = "<a href=\"$safeUrl\">$label</a>"

        val sel     = value.selection
        val before  = value.text.substring(0, sel.start)
        val after   = value.text.substring(sel.end)   // replaces any selected text
        val newText = before + linkHtml + after
        return value.copy(
            text      = newText,
            selection = TextRange(before.length + linkHtml.length)
        )
    }

    // ─── Code block ───────────────────────────────────────────────────────────

    /** Insert a `<pre><code>` block wrapping the selection (or at cursor). */
    fun insertCodeBlock(value: TextFieldValue): TextFieldValue {
        val sel      = value.selection
        val selected = value.text.substring(sel.start, sel.end)
        val block    = "\n<pre><code>$selected</code></pre>\n"
        val before   = value.text.substring(0, sel.start)
        val after    = value.text.substring(sel.end)
        val newText  = before + block + after
        return value.copy(
            text      = newText,
            selection = TextRange(before.length + block.length)
        )
    }

    // ─── Internal helpers ─────────────────────────────────────────────────────

    /**
     * Toggle a text prefix on/off for the line containing the cursor.
     * Used by [toggleBulletList] and [toggleNumberedList].
     */
    private fun toggleLinePrefix(value: TextFieldValue, prefix: String): TextFieldValue {
        val text      = value.text
        val cursor    = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val (newLine, cursorDelta) = if (line.startsWith(prefix)) {
            Pair(line.removePrefix(prefix), -prefix.length)
        } else {
            Pair(prefix + line, prefix.length)
        }

        val newText      = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        val newCursorPos = (cursor + cursorDelta).coerceIn(0, newText.length)
        return value.copy(text = newText, selection = TextRange(newCursorPos))
    }
}

package com.amvarpvtltd.swiftNote.richtext

import androidx.compose.ui.text.TextRange
import androidx.compose.ui.text.input.TextFieldValue

/**
 * Pure, stateless helper functions for HTML-based rich text editing.
 *
 * All functions take a [TextFieldValue] (text + cursor/selection) and return a new
 * [TextFieldValue] with the formatting applied.  They never touch Compose state or the
 * UI layer — they are trivially unit-testable.
 *
 * Phase 2 implementation.
 */
object RichTextEditorHelpers {

    // ─── Inline tags ──────────────────────────────────────────────────────────

    /**
     * Toggle an inline HTML tag around the current selection.
     *
     * Behaviour:
     * - **No selection (collapsed cursor) & already inside tag:** splits the tag at cursor
     *   so text before cursor stays formatted, text after cursor loses formatting.
     * - **No selection (collapsed cursor) & not inside tag:** inserts `<tag></tag>` and places cursor between.
     * - **Selection already wrapped:** unwraps — removes the surrounding tags.
     * - **New selection:** wraps the selected text with `<tag>…</tag>`.
     */
    fun toggleInlineTag(value: TextFieldValue, tag: String): TextFieldValue {
        val openTag  = "<$tag>"
        val closeTag = "</$tag>"
        val sel  = value.selection
        val text = value.text

        if (sel.collapsed) {
            // Check if cursor is currently inside an existing <tag>...</tag> pair
            val before = text.substring(0, sel.start)
            val after  = text.substring(sel.start)

            // Use regex for exact tag matching (avoids <li> matching <i>)
            val openRegex = Regex("<$tag(\\s[^>]*)?>", RegexOption.IGNORE_CASE)
            val closeRegex = Regex("</$tag>", RegexOption.IGNORE_CASE)

            val openMatches = openRegex.findAll(before).toList()
            if (openMatches.isNotEmpty()) {
                val lastOpen = openMatches.last()
                val afterOpenTag = lastOpen.range.last + 1
                // Check there's no close tag between open tag and cursor
                val closeInBetween = closeRegex.find(before, startIndex = afterOpenTag)
                if (closeInBetween == null) {
                    // We ARE inside the tag — find the close tag after cursor
                    val closeAfterCursor = closeRegex.find(after)
                    if (closeAfterCursor != null) {
                        // FIX BUG 1: Instead of removing the whole tag pair, SPLIT at cursor.
                        // Text before cursor keeps formatting, text after cursor loses it.
                        val contentBefore = before.substring(afterOpenTag)
                        val contentAfter = after.substring(0, closeAfterCursor.range.first)
                        val remainingAfter = after.substring(closeAfterCursor.range.last + 1)

                        if (contentBefore.isEmpty() && contentAfter.isEmpty()) {
                            // Empty tags — just remove both tags entirely
                            val beforeWithoutOpen = before.substring(0, lastOpen.range.first)
                            val newText = beforeWithoutOpen + remainingAfter
                            return value.copy(text = newText, selection = TextRange(beforeWithoutOpen.length))
                        } else if (contentBefore.isEmpty()) {
                            // Cursor is right after open tag — remove open tag, keep content unformatted
                            val beforeWithoutOpen = before.substring(0, lastOpen.range.first)
                            val newText = beforeWithoutOpen + contentAfter + remainingAfter
                            return value.copy(text = newText, selection = TextRange(beforeWithoutOpen.length))
                        } else if (contentAfter.isEmpty()) {
                            // Cursor is right before close tag — close tag here, done
                            val beforeOpen = before.substring(0, lastOpen.range.first)
                            val newText = beforeOpen + openTag + contentBefore + closeTag + remainingAfter
                            return value.copy(text = newText, selection = TextRange(beforeOpen.length + openTag.length + contentBefore.length + closeTag.length))
                        } else {
                            // Split: close tag before cursor, leave after-content unformatted
                            val beforeOpen = before.substring(0, lastOpen.range.first)
                            val newText = beforeOpen + openTag + contentBefore + closeTag + contentAfter + remainingAfter
                            val newCursor = beforeOpen.length + openTag.length + contentBefore.length + closeTag.length
                            return value.copy(text = newText, selection = TextRange(newCursor))
                        }
                    }
                }
            }

            // Not inside existing tag — insert empty tag pair
            val newText = text.substring(0, sel.start) + openTag + closeTag + text.substring(sel.start)
            return value.copy(
                text      = newText,
                selection = TextRange(sel.start + openTag.length)
            )
        }

        val before = text.substring(0, sel.start)
        val after  = text.substring(sel.end)

        // Already wrapped → unwrap
        if (before.endsWith(openTag) && after.startsWith(closeTag)) {
            val newText = before.dropLast(openTag.length) +
                          text.substring(sel.start, sel.end) +
                          after.drop(closeTag.length)
            return value.copy(
                text      = newText,
                selection = TextRange(sel.start - openTag.length, sel.end - openTag.length)
            )
        }

        // Check if selection is fully inside existing tags — unwrap those tags
        val openRegex = Regex("<$tag(\\s[^>]*)?>", RegexOption.IGNORE_CASE)
        val closeRegex = Regex("</$tag>", RegexOption.IGNORE_CASE)
        val openMatches = openRegex.findAll(before).toList()
        if (openMatches.isNotEmpty()) {
            val lastOpen = openMatches.last()
            val afterOpenTag = lastOpen.range.last + 1
            val closeInBetween = closeRegex.find(before, startIndex = afterOpenTag)
            if (closeInBetween == null) {
                val closeAfterSelection = closeRegex.find(after)
                if (closeAfterSelection != null) {
                    // Remove surrounding tags
                    val afterWithoutClose = after.removeRange(
                        closeAfterSelection.range.first,
                        closeAfterSelection.range.last + 1
                    )
                    val beforeWithoutOpen = before.removeRange(
                        lastOpen.range.first,
                        lastOpen.range.last + 1
                    )
                    val selected = text.substring(sel.start, sel.end)
                    val newText = beforeWithoutOpen + selected + afterWithoutClose
                    val openLen = lastOpen.range.last - lastOpen.range.first + 1
                    return value.copy(
                        text = newText,
                        selection = TextRange(sel.start - openLen, sel.end - openLen)
                    )
                }
            }
        }

        // Wrap selection
        val selected = text.substring(sel.start, sel.end)
        val newText  = before + openTag + selected + closeTag + after
        return value.copy(
            text      = newText,
            selection = TextRange(sel.start + openTag.length, sel.end + openTag.length)
        )
    }

    /** Bold — toggles `<b>…</b>` around selection. */
    fun toggleBold(value: TextFieldValue)      = toggleInlineTag(value, "b")

    /** Italic — toggles `<i>…</i>` around selection. */
    fun toggleItalic(value: TextFieldValue)    = toggleInlineTag(value, "i")

    /** Underline — toggles `<u>…</u>` around selection. */
    fun toggleUnderline(value: TextFieldValue) = toggleInlineTag(value, "u")

    /** Inline code — toggles `<code>…</code>` around selection. */
    fun toggleCode(value: TextFieldValue)      = toggleInlineTag(value, "code")

    // ─── Headings ─────────────────────────────────────────────────────────────

    /**
     * Apply (or remove) a heading to the line containing the cursor.
     *
     * - [level] 1 → `<h1>`, 2 → `<h2>`, 0 → removes any existing heading.
     * - If the line already has the requested heading, it is removed (toggle off).
     */
    fun applyHeading(value: TextFieldValue, level: Int): TextFieldValue {
        val text     = value.text
        val cursor   = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1   // 0 if no newline found
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val existingHeadingRegex = Regex("^<h([12])>(.*)</h([12])>$", RegexOption.DOT_MATCHES_ALL)
        val match = existingHeadingRegex.matchEntire(line.trim())

        val newLine: String = when {
            // Toggle off: same level already applied
            match != null && match.groupValues[1] == level.toString() -> match.groupValues[2]
            // Apply heading (replacing any existing heading)
            level in 1..2 -> {
                val plainContent = if (match != null) match.groupValues[2] else line
                "<h$level>$plainContent</h$level>"
            }
            // level == 0 → strip heading
            match != null -> match.groupValues[2]
            else          -> line
        }

        val newText = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        // Keep cursor inside the new content
        val newCursor = (lineStart + newLine.length).coerceAtMost(newText.length)
        return value.copy(text = newText, selection = TextRange(newCursor))
    }

    // ─── Lists ────────────────────────────────────────────────────────────────

    /**
     * Toggle unordered list formatting for the current line.
     *
     * - If the line already has a `<li>` wrapper (inside `<ul>`), strip it.
     * - Otherwise wrap the line content in `<ul><li>...</li></ul>`.
     */
    fun toggleBulletList(value: TextFieldValue): TextFieldValue {
        val text   = value.text
        val cursor = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val ulRegex = Regex("""^<ul><li>(.*)</li></ul>$""")
        val bulletPrefix = Regex("""^•\s?""")
        val newLine = when {
            ulRegex.matches(line) -> ulRegex.find(line)!!.groupValues[1]
            bulletPrefix.containsMatchIn(line) -> line.replace(bulletPrefix, "")
            else -> "<ul><li>$line</li></ul>"
        }
        val newText = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        val newCursor = (lineStart + newLine.length).coerceAtMost(newText.length)
        return value.copy(text = newText, selection = TextRange(newCursor))
    }

    /**
     * Toggle ordered (numbered) list formatting for the current line.
     *
     * - If the line already has a `<li>` wrapper (inside `<ol>`), strip it.
     * - Otherwise wrap the line content in `<ol><li>...</li></ol>`.
     */
    fun toggleNumberedList(value: TextFieldValue): TextFieldValue {
        val text   = value.text
        val cursor = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val olRegex = Regex("""^<ol><li>(.*)</li></ol>$""")
        val numPrefix = Regex("""^\d+\.\s?""")
        val newLine = when {
            olRegex.matches(line) -> olRegex.find(line)!!.groupValues[1]
            numPrefix.containsMatchIn(line) -> line.replace(numPrefix, "")
            else -> "<ol><li>$line</li></ol>"
        }
        val newText = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        val newCursor = (lineStart + newLine.length).coerceAtMost(newText.length)
        return value.copy(text = newText, selection = TextRange(newCursor))
    }

    /** Insert an unchecked checkbox (`<input type="checkbox">`) at the cursor. */
    fun insertCheckbox(value: TextFieldValue, checked: Boolean = false): TextFieldValue {
        val marker  = if (checked) "<input type=\"checkbox\" checked>" else "<input type=\"checkbox\">"
        val newText = value.text.substring(0, value.selection.start) +
                      marker + " " +
                      value.text.substring(value.selection.start)
        return value.copy(
            text      = newText,
            selection = TextRange(value.selection.start + marker.length + 1)
        )
    }

    // ─── Auto-continue on Enter (Bug Fix #2) ──────────────────────────────────

    /**
     * Handles newline auto-continuation for lists and checkboxes.
     *
     * Call this from onValueChange: if the user just typed Enter on a list/checkbox line,
     * automatically insert the appropriate prefix on the new line.
     *
     * - Bullet list → inserts new `<ul><li></li></ul>` on next line.
     * - Numbered list → inserts new `<ol><li></li></ol>` on next line.
     * - Checkbox → inserts new unchecked checkbox on next line.
     * - If previous item was empty, removes it (breaks out of the list).
     */
    fun handleNewLine(oldValue: TextFieldValue, newValue: TextFieldValue): TextFieldValue {
        // Only process if exactly one character was added
        if (newValue.text.length != oldValue.text.length + 1) return newValue
        val insertPos = newValue.selection.start - 1
        if (insertPos < 0 || newValue.text[insertPos] != '\n') return newValue

        // Find the previous line (the line before the newline we just inserted)
        val prevLineEnd = insertPos
        val prevLineStart = newValue.text.lastIndexOf('\n', prevLineEnd - 1) + 1
        val prevLine = newValue.text.substring(prevLineStart, prevLineEnd)

        val ulRegex = Regex("""^<ul><li>(.*)</li></ul>$""")
        val olRegex = Regex("""^<ol><li>(.*)</li></ol>$""")
        val checkboxRegex = Regex("""^<input type="checkbox"[^>]*>\s?(.*)$""")

        val ulMatch = ulRegex.find(prevLine)
        val olMatch = olRegex.find(prevLine)
        val cbMatch = checkboxRegex.find(prevLine)

        when {
            ulMatch != null -> {
                val content = ulMatch.groupValues[1]
                if (content.isBlank()) {
                    // Empty bullet item — remove it and break out of list
                    val newText = newValue.text.substring(0, prevLineStart) +
                            newValue.text.substring(insertPos + 1)
                    return newValue.copy(
                        text = newText,
                        selection = TextRange(prevLineStart)
                    )
                }
                // Continue with new bullet item
                val continuation = "<ul><li></li></ul>"
                val cursorInside = "<ul><li>".length
                val before = newValue.text.substring(0, insertPos + 1)
                val after = newValue.text.substring(insertPos + 1)
                val newText = before + continuation + after
                return newValue.copy(
                    text = newText,
                    selection = TextRange(insertPos + 1 + cursorInside)
                )
            }
            olMatch != null -> {
                val content = olMatch.groupValues[1]
                if (content.isBlank()) {
                    // Empty numbered item — remove it and break out of list
                    val newText = newValue.text.substring(0, prevLineStart) +
                            newValue.text.substring(insertPos + 1)
                    return newValue.copy(
                        text = newText,
                        selection = TextRange(prevLineStart)
                    )
                }
                // Continue with new numbered item
                val continuation = "<ol><li></li></ol>"
                val cursorInside = "<ol><li>".length
                val before = newValue.text.substring(0, insertPos + 1)
                val after = newValue.text.substring(insertPos + 1)
                val newText = before + continuation + after
                return newValue.copy(
                    text = newText,
                    selection = TextRange(insertPos + 1 + cursorInside)
                )
            }
            cbMatch != null -> {
                val content = cbMatch.groupValues[1]
                if (content.isBlank()) {
                    // Empty checkbox item — remove it and break out
                    val newText = newValue.text.substring(0, prevLineStart) +
                            newValue.text.substring(insertPos + 1)
                    return newValue.copy(
                        text = newText,
                        selection = TextRange(prevLineStart)
                    )
                }
                // Continue with new unchecked checkbox
                val continuation = "<input type=\"checkbox\"> "
                val before = newValue.text.substring(0, insertPos + 1)
                val after = newValue.text.substring(insertPos + 1)
                val newText = before + continuation + after
                return newValue.copy(
                    text = newText,
                    selection = TextRange(insertPos + 1 + continuation.length)
                )
            }
            else -> return newValue
        }
    }

    // ─── Links ────────────────────────────────────────────────────────────────

    /**
     * Insert a hyperlink at the cursor.
     *
     * - If [displayText] is provided (or text was selected), uses it as link label.
     * - Otherwise uses the URL itself as label.
     * - Ensures the URL starts with `"https://"` if it has no scheme.
     */
    fun insertLink(
        value: TextFieldValue,
        url: String,
        displayText: String?
    ): TextFieldValue {
        val safeUrl  = if (url.startsWith("http://") || url.startsWith("https://")) url else "https://$url"
        val label    = displayText?.takeIf { it.isNotBlank() } ?: safeUrl
        val linkHtml = "<a href=\"$safeUrl\">$label</a>"

        val sel     = value.selection
        val before  = value.text.substring(0, sel.start)
        val after   = value.text.substring(sel.end)   // replaces any selected text
        val newText = before + linkHtml + after
        return value.copy(
            text      = newText,
            selection = TextRange(before.length + linkHtml.length)
        )
    }

    // ─── Code block ───────────────────────────────────────────────────────────

    /** Insert a `<pre><code>` block wrapping the selection (or at cursor). */
    fun insertCodeBlock(value: TextFieldValue): TextFieldValue {
        val sel      = value.selection
        val selected = value.text.substring(sel.start, sel.end)
        val block    = "\n<pre><code>$selected</code></pre>\n"
        val before   = value.text.substring(0, sel.start)
        val after    = value.text.substring(sel.end)
        val newText  = before + block + after
        return value.copy(
            text      = newText,
            selection = TextRange(before.length + block.length)
        )
    }

    // ─── Internal helpers ─────────────────────────────────────────────────────

    /**
     * Toggle a text prefix on/off for the line containing the cursor.
     */
    private fun toggleLinePrefix(value: TextFieldValue, prefix: String): TextFieldValue {
        val text      = value.text
        val cursor    = value.selection.start.coerceIn(0, text.length)
        val lineStart = text.lastIndexOf('\n', cursor - 1) + 1
        val lineEnd   = text.indexOf('\n', cursor).let { if (it == -1) text.length else it }
        val line      = text.substring(lineStart, lineEnd)

        val (newLine, cursorDelta) = if (line.startsWith(prefix)) {
            Pair(line.removePrefix(prefix), -prefix.length)
        } else {
            Pair(prefix + line, prefix.length)
        }

        val newText      = text.substring(0, lineStart) + newLine + text.substring(lineEnd)
        val newCursorPos = (cursor + cursorDelta).coerceIn(0, newText.length)
        return value.copy(text = newText, selection = TextRange(newCursorPos))
    }
}

package com.amvarpvtltd.swiftNote.richtext

import androidx.compose.ui.text.TextRange
import androidx.compose.ui.text.input.TextFieldValue
import org.junit.Assert.*
import org.junit.Test

/**
 * Unit tests for RichTextEditorHelpers — covers all three bug fixes:
 * 1. Toggle-off splits tags at cursor instead of removing content
 * 2. Auto-continue lists/checkboxes on Enter
 * 3. Italic and other toolbar functions work correctly
 */
class RichTextEditorHelpersTest {

    // ═══════════════════════════════════════════════════════════════════════════
    // BUG FIX #1: Toggle-off should split, not remove
    // ═══════════════════════════════════════════════════════════════════════════

    @Test
    fun `toggleBold - collapsed cursor inside bold - splits tag at cursor`() {
        // Simulates: <b>hello world</b> with cursor after "hello"
        val text = "<b>hello world</b>"
        val cursorPos = "<b>hello".length  // cursor after "hello" inside <b>
        val value = TextFieldValue(text, TextRange(cursorPos))

        val result = RichTextEditorHelpers.toggleBold(value)

        // Expected: <b>hello</b> world — text before cursor stays bold, after loses it
        assertEquals("<b>hello</b> world", result.text)
        // Cursor should be right after </b>
        assertEquals("<b>hello</b>".length, result.selection.start)
    }

    @Test
    fun `toggleBold - collapsed cursor at start of content - removes formatting from all`() {
        // Cursor right after <b> — nothing before cursor inside tag
        val text = "<b>hello</b>"
        val cursorPos = "<b>".length
        val value = TextFieldValue(text, TextRange(cursorPos))

        val result = RichTextEditorHelpers.toggleBold(value)

        // Cursor at start means no content before cursor inside tag → unformat everything after
        assertEquals("hello", result.text)
        assertEquals(0, result.selection.start)
    }

    @Test
    fun `toggleBold - collapsed cursor at end of content - keeps all formatted`() {
        // Cursor right before </b> — all content before cursor
        val text = "<b>hello</b>"
        val cursorPos = "<b>hello".length
        val value = TextFieldValue(text, TextRange(cursorPos))

        val result = RichTextEditorHelpers.toggleBold(value)

        // All content is before cursor → keeps formatted, just closes there
        assertEquals("<b>hello</b>", result.text)
    }

    @Test
    fun `toggleBold - empty tags - removes them`() {
        val text = "<b></b>"
        val cursorPos = "<b>".length
        val value = TextFieldValue(text, TextRange(cursorPos))

        val result = RichTextEditorHelpers.toggleBold(value)

        assertEquals("", result.text)
        assertEquals(0, result.selection.start)
    }

    @Test
    fun `toggleItalic - not inside tag - inserts empty tags`() {
        val text = "hello world"
        val cursorPos = 5
