    }

    @Test
    fun `toggleBulletList - wraps normal line`() {
        val text = "buy groceries"
        val value = TextFieldValue(text, TextRange(5))

        val result = RichTextEditorHelpers.toggleBulletList(value)

        assertEquals("<ul><li>buy groceries</li></ul>", result.text)
    }

    @Test
    fun `toggleBulletList - unwraps existing bullet`() {
        val text = "<ul><li>buy groceries</li></ul>"
        val value = TextFieldValue(text, TextRange(10))

        val result = RichTextEditorHelpers.toggleBulletList(value)

        assertEquals("buy groceries", result.text)
    }

    @Test
    fun `toggleNumberedList - wraps normal line`() {
        val text = "step one"
        val value = TextFieldValue(text, TextRange(4))

        val result = RichTextEditorHelpers.toggleNumberedList(value)

        assertEquals("<ol><li>step one</li></ol>", result.text)
    }

    @Test
    fun `toggleNumberedList - unwraps existing`() {
        val text = "<ol><li>step one</li></ol>"
        val value = TextFieldValue(text, TextRange(10))

        val result = RichTextEditorHelpers.toggleNumberedList(value)

        assertEquals("step one", result.text)
    }

    @Test
    fun `insertCheckbox - inserts at cursor`() {
        val text = "todo item"
        val value = TextFieldValue(text, TextRange(0))

        val result = RichTextEditorHelpers.insertCheckbox(value)

        assertTrue(result.text.startsWith("<input type=\"checkbox\"> "))
        assertEquals("<input type=\"checkbox\"> todo item", result.text)
    }

    @Test
    fun `insertLink - inserts with display text`() {
        val text = "click here for info"
        val value = TextFieldValue(text, TextRange(text.length))

        val result = RichTextEditorHelpers.insertLink(value, "example.com", "Example")

        assertTrue(result.text.contains("<a href=\"https://example.com\">Example</a>"))
    }

    @Test
    fun `insertLink - preserves https scheme`() {
        val text = ""
        val value = TextFieldValue(text, TextRange(0))

        val result = RichTextEditorHelpers.insertLink(value, "https://google.com", null)

        assertEquals("<a href=\"https://google.com\">https://google.com</a>", result.text)
    }

    @Test
    fun `insertCodeBlock - wraps selection`() {
        val text = "some code here"
        val value = TextFieldValue(text, TextRange(5, 9))  // selects "code"

        val result = RichTextEditorHelpers.insertCodeBlock(value)

        assertTrue(result.text.contains("<pre><code>code</code></pre>"))
    }

    @Test
    fun `toggleBold - split preserves other content`() {
        // Real-world scenario: "before <b>some bold text</b> after"
        // cursor inside "bold" → should split into "before <b>some bold</b> text after"
        val text = "before <b>some bold text</b> after"
        val cursorPos = "before <b>some bold".length
        val value = TextFieldValue(text, TextRange(cursorPos))

        val result = RichTextEditorHelpers.toggleBold(value)

        assertEquals("before <b>some bold</b> text after", result.text)
        assertEquals("before <b>some bold</b>".length, result.selection.start)
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Multi-line Enter continuation
    // ═══════════════════════════════════════════════════════════════════════════

    @Test
    fun `handleNewLine - works with multiline content before bullet`() {
        val oldText = "Title\n<ul><li>item</li></ul>"
        val oldValue = TextFieldValue(oldText, TextRange(oldText.length))

        val newText = "$oldText\n"
        val newValue = TextFieldValue(newText, TextRange(newText.length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        assertTrue(result.text.endsWith("\n<ul><li></li></ul>"))
    }

    @Test
    fun `handleNewLine - Enter pressed INSIDE bullet list tags (Scenario B)`() {
        // When VisualTransformation maps cursor to inside <ul><li>item|</li></ul>
        // and Enter inserts newline there, we get split tags
        val oldText = "<ul><li>item</li></ul>"
        val oldValue = TextFieldValue(oldText, TextRange("<ul><li>item".length))

        // After Enter: "<ul><li>item\n</li></ul>"
        val newText = "<ul><li>item\n</li></ul>"
        val newValue = TextFieldValue(newText, TextRange("<ul><li>item\n".length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        // Should rebuild into two proper list items
        assertTrue(result.text.contains("<ul><li>item</li></ul>"))
        assertTrue(result.text.contains("<ul><li></li></ul>"))
    }

    @Test
    fun `handleNewLine - Enter pressed INSIDE numbered list tags (Scenario B)`() {
        val oldText = "<ol><li>step one</li></ol>"
        val oldValue = TextFieldValue(oldText, TextRange("<ol><li>step one".length))

        val newText = "<ol><li>step one\n</li></ol>"
        val newValue = TextFieldValue(newText, TextRange("<ol><li>step one\n".length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        assertTrue(result.text.contains("<ol><li>step one</li></ol>"))
        assertTrue(result.text.contains("<ol><li></li></ol>"))
    }

    @Test
    fun `handleNewLine - checked checkbox also continues`() {
        val oldText = "<input type=\"checkbox\" checked> done item"
        val oldValue = TextFieldValue(oldText, TextRange(oldText.length))

        val newText = "$oldText\n"
        val newValue = TextFieldValue(newText, TextRange(newText.length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        // Should continue with unchecked checkbox
        assertTrue(result.text.contains("\n<input type=\"checkbox\"> "))
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // BUG FIX: Smart deletion — removes whole tag on backspace
    // ═══════════════════════════════════════════════════════════════════════════

    @Test
    fun `handleTextChange - deleting char inside bold tag removes both tags`() {
        // Old text has <b>hello</b>, user deletes the '>' of <b>
        val oldText = "<b>hello</b>"
        val oldValue = TextFieldValue(oldText, TextRange(3))  // cursor after <b>

        // Simulated: system deleted the '>' at position 2, producing "<bhello</b>"
        val newText = "<bhello</b>"
        val newValue = TextFieldValue(newText, TextRange(2))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // Should remove both tags cleanly, keeping just "hello"
        assertEquals("hello", result.text)
    }

    @Test
    fun `handleTextChange - deleting char inside closing tag removes formatting`() {
        // Old text has <i>world</i>, user deletes '<' of </i>
        val oldText = "<i>world</i>"
        val oldValue = TextFieldValue(oldText, TextRange(10))  // cursor after 'd' before </i>

        // Simulated: deleted '<' at position 8 → "<i>world/i>"
        val newText = "<i>world/i>"
        val newValue = TextFieldValue(newText, TextRange(8))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // Should recognize broken tag and clean up — removing formatting
        assertEquals("world", result.text)
    }

    @Test
    fun `handleTextChange - deleting char inside checkbox removes entire checkbox`() {
        val oldText = "<input type=\"checkbox\"> task"
        val oldValue = TextFieldValue(oldText, TextRange(5))  // inside the tag

        // Simulated: deleted 'p' at position 4 → "<inut type=\"checkbox\"> task"
        val newText = "<inut type=\"checkbox\"> task"
        val newValue = TextFieldValue(newText, TextRange(4))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // Should recognize broken tag and fix it
        // The exact behavior depends on the broken tag detection — tag is still complete (<...>)
        // But it's now an invalid tag name, so fixBrokenTagsAroundCursor should handle it
        assertFalse(result.text.contains("<inut"))
    }

    @Test
    fun `handleTextChange - deleting normal text char does nothing special`() {
        val oldText = "hello world"
        val oldValue = TextFieldValue(oldText, TextRange(5))

        val newText = "hell world"
        val newValue = TextFieldValue(newText, TextRange(4))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // No tags involved — should just pass through
        assertEquals("hell world", result.text)
        assertEquals(4, result.selection.start)
    }

    @Test
    fun `handleTextChange - deleting inside ul-li tag removes list wrapper`() {
        val oldText = "<ul><li>item</li></ul>"
        val oldValue = TextFieldValue(oldText, TextRange(4))  // inside <ul> tag

        // Simulated: deleted '>' of <ul> → "<ulitem</li></ul>"...
        // Actually let's do it correctly - deleted 'l' at pos 2: "<u><li>item</li></ul>"
        val newText = "<u><li>item</li></ul>"
        val newValue = TextFieldValue(newText, TextRange(2))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // Should detect broken tag state. Since <u> is a valid tag on its own,
        // the behavior is just to pass through; but this tests the code doesn't crash
        assertNotNull(result)
    }

    @Test
    fun `handleTextChange - paste (multi-char add) passes through`() {
        val oldText = "hello"
        val oldValue = TextFieldValue(oldText, TextRange(5))

        val newText = "hello world"
        val newValue = TextFieldValue(newText, TextRange(11))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // Multi-char additions are not processed by handleTextChange
        assertEquals(newValue, result)
    }

    @Test
    fun `handleTextChange - multi-char deletion passes through`() {
        val oldText = "<b>hello</b> world"
        val oldValue = TextFieldValue(oldText, TextRange(3, 8))  // "hello" selected

        // User deleted selected "hello" + more → only single-char deletes are handled
        val newText = "<b></b> world"
        val newValue = TextFieldValue(newText, TextRange(3))

        val result = RichTextEditorHelpers.handleTextChange(oldValue, newValue)

        // Multi-char deletion, just passes through
        assertEquals(newValue.text, result.text)
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Heading edge cases
    // ═══════════════════════════════════════════════════════════════════════════

    @Test
    fun `applyHeading - cursor at end of h1 line toggles off`() {
        val text = "<h1>My Title</h1>"
        // Cursor at the very end (after </h1>)
        val value = TextFieldValue(text, TextRange(text.length))

        val result = RichTextEditorHelpers.applyHeading(value, 1)

        assertEquals("My Title", result.text)
    }

    @Test
    fun `applyHeading - cursor at start of h1 line toggles off`() {
        val text = "<h1>My Title</h1>"
        val value = TextFieldValue(text, TextRange(0))

        val result = RichTextEditorHelpers.applyHeading(value, 1)

        assertEquals("My Title", result.text)
    }

    @Test
    fun `applyHeading - Normal (level 0) strips h1`() {
        val text = "<h1>My Title</h1>"
        val value = TextFieldValue(text, TextRange(8))

        val result = RichTextEditorHelpers.applyHeading(value, 0)

        assertEquals("My Title", result.text)
    }

    @Test
    fun `applyHeading - Normal (level 0) strips h2`() {
        val text = "<h2>Subtitle</h2>"
        val value = TextFieldValue(text, TextRange(5))

        val result = RichTextEditorHelpers.applyHeading(value, 0)

        assertEquals("Subtitle", result.text)
    }

    @Test
    fun `applyHeading - h1 on multiline text only affects current line`() {
        val text = "Line one\nLine two\nLine three"
        // Cursor on "Line two" (position 10)
        val value = TextFieldValue(text, TextRange(12))

        val result = RichTextEditorHelpers.applyHeading(value, 1)

        assertEquals("Line one\n<h1>Line two</h1>\nLine three", result.text)
    }

    @Test
    fun `applyHeading - switch h2 to h1`() {
        val text = "<h2>Title</h2>"
        val value = TextFieldValue(text, TextRange(6))

        val result = RichTextEditorHelpers.applyHeading(value, 1)

        assertEquals("<h1>Title</h1>", result.text)
    }

    @Test
    fun `handleNewLine - Enter inside heading splits and exits heading`() {
        // User presses Enter inside <h1>content</h1>
        val oldText = "<h1>My Title</h1>"
        val oldValue = TextFieldValue(oldText, TextRange("<h1>My Title".length))

        // After Enter: "<h1>My Title\n</h1>"
        val newText = "<h1>My Title\n</h1>"
        val newValue = TextFieldValue(newText, TextRange("<h1>My Title\n".length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        // Should close heading on first line and start new plain line
        assertTrue(result.text.startsWith("<h1>My Title</h1>"))
        assertTrue(result.text.contains("\n"))
        assertFalse(result.text.endsWith("</h1>"))
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Bullet/Numbered continuation edge cases
    // ═══════════════════════════════════════════════════════════════════════════

    @Test
    fun `handleNewLine - bullet continuation works after second item`() {
        // Simulate: two bullet items, cursor at end of second, press Enter
        val oldText = "<ul><li>first</li></ul>\n<ul><li>second</li></ul>"
        val oldValue = TextFieldValue(oldText, TextRange(oldText.length))

        val newText = "$oldText\n"
        val newValue = TextFieldValue(newText, TextRange(newText.length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        assertTrue(result.text.endsWith("\n<ul><li></li></ul>"))
    }

    @Test
    fun `handleNewLine - numbered continuation works after second item`() {
        val oldText = "<ol><li>first</li></ol>\n<ol><li>second</li></ol>"
        val oldValue = TextFieldValue(oldText, TextRange(oldText.length))

        val newText = "$oldText\n"
        val newValue = TextFieldValue(newText, TextRange(newText.length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        assertTrue(result.text.endsWith("\n<ol><li></li></ol>"))
    }

    @Test
    fun `handleNewLine - Scenario B bullet with more text after`() {
        // Content after the list on same construct
        val oldText = "intro\n<ul><li>item</li></ul>\nmore"
        val oldValue = TextFieldValue(oldText, TextRange("intro\n<ul><li>item".length))

        // Enter splits inside: "intro\n<ul><li>item\n</li></ul>\nmore"
        val newText = "intro\n<ul><li>item\n</li></ul>\nmore"
        val newValue = TextFieldValue(newText, TextRange("intro\n<ul><li>item\n".length))

        val result = RichTextEditorHelpers.handleNewLine(oldValue, newValue)

        assertTrue(result.text.contains("<ul><li>item</li></ul>"))
        assertTrue(result.text.contains("<ul><li></li></ul>"))
        assertTrue(result.text.contains("more"))
    }
}

package com.amvarpvtltd.swiftNote.richtext

import android.text.Editable
import android.text.Html
import android.text.Spannable
import android.text.Spanned
import android.text.style.TypefaceSpan
import android.util.Log
import androidx.compose.foundation.text.appendInlineContent
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.AnnotatedString
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontStyle
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextDecoration
import androidx.compose.ui.unit.sp
import org.xml.sax.XMLReader

/**
 * Central HTML ↔ AnnotatedString conversion utilities.
 *
 * Phase 0: extracted from add_Note.kt's spannedToAnnotatedString.
 * Phase 1: extended with full HTML support —
 *   headings (h1/h2), bullet/ordered lists, hyperlinks, code/pre blocks,
 *   and inline checkboxes (<input type="checkbox">).
 */
object RichTextRenderer {

    // ─── Regex & private constants ────────────────────────────────────────────

    private val HTML_TAG_REGEX = Regex(
        "<(/?)(b|strong|i|em|u|s|h1|h2|p|br|ul|ol|li|a|code|pre|input)\\b[^>]*>",
        RegexOption.IGNORE_CASE
    )

    /**
     * Private-Use-Area Unicode chars that act as in-band markers for checkboxes
     * during the HTML pre-processing step.  They survive [Html.fromHtml] unchanged.
     */
    internal const val CHECKBOX_UNCHECKED = "\uE001"
    internal const val CHECKBOX_CHECKED   = "\uE002"
    private  const val CHECKBOX_UNCHECKED_CHAR = '\uE001'
    private  const val CHECKBOX_CHECKED_CHAR   = '\uE002'

    /** Default link colour — matches NoteTheme.Primary; callers may override. */
    val DEFAULT_LINK_COLOR = Color(0xFF6366F1)

    // ─── Public data classes ──────────────────────────────────────────────────

    /**
     * Metadata for a single inline checkbox detected in the HTML.
     *
     * @param id       Unique key used in the [androidx.compose.foundation.text.InlineTextContent] map.
     * @param checked  Whether the checkbox is checked.
     * @param index    Zero-based index within this note's checkbox list — used to locate
     *                 the checkbox in the original HTML for toggling.
     */
    data class CheckboxInfo(
        val id: String,
        val checked: Boolean,
        val index: Int
    )

    /**
     * Full result of converting an HTML string.
     *
     * @param annotated  Compose [AnnotatedString] ready for [androidx.compose.material3.Text].
     * @param checkboxes Ordered list of checkboxes found; each carries an [InlineTextContent] key.
     */
    data class RenderedContent(
        val annotated: AnnotatedString,
        val checkboxes: List<CheckboxInfo>
    )

    // ─── Public API ───────────────────────────────────────────────────────────

    /** Returns true if the string appears to contain HTML markup. */
    fun containsHtml(text: String): Boolean = HTML_TAG_REGEX.containsMatchIn(text)

    /**
     * Strip HTML tags and return plain text — suitable for search or entity detection.
     */
    fun stripHtmlToPlainText(html: String): String {
        if (!containsHtml(html)) return html
        return try {
            Html.fromHtml(html, Html.FROM_HTML_MODE_COMPACT).toString()
        } catch (e: Exception) {
            Log.d("RichTextRenderer", "stripHtmlToPlainText: ${e.message}")
            html
        }
    }

    /**
     * Convenience overload — converts HTML to [AnnotatedString] only.
     * For notes that may contain checkboxes, prefer [htmlToAnnotatedFull].
     */
    fun htmlToAnnotated(html: String): AnnotatedString = htmlToAnnotatedFull(html).annotated

    /**
     * Full conversion: HTML → [RenderedContent] (annotated text + checkbox list).
     *
     * Supported features:
     * - **Bold / italic / underline / strikethrough** (b/i/u/s and their semantic aliases)
     * - **H1 / H2 headings** — rendered larger and bold (handled by Android's Html.fromHtml)
     * - **Unordered & ordered lists** — converted to "• " / "N. " bullet text in pre-processing
     * - **Hyperlinks** — coloured, underlined, tap-to-open via [RichTextDisplay]
     * - **`<code>` / `<pre>`** — monospace font family
     * - **`<input type="checkbox">`** — replaced with [appendInlineContent] placeholders
     *
     * @param html      Raw HTML string from Room / clipboard.
     * @param linkColor Colour applied to hyperlink text; defaults to [DEFAULT_LINK_COLOR].
     */
    fun htmlToAnnotatedFull(
        html: String,
        linkColor: Color = DEFAULT_LINK_COLOR
    ): RenderedContent {
        if (!containsHtml(html)) {
            return RenderedContent(AnnotatedString(html), emptyList())
        }
        return try {
            val preprocessed = preprocessHtml(html)
            val spanned: Spanned = Html.fromHtml(
                preprocessed,
                Html.FROM_HTML_MODE_COMPACT,
                null,
                CodeTagHandler()
            )

            val checkboxes = mutableListOf<CheckboxInfo>()
            val spannedText = spanned.toString()
            var checkboxIndex = 0

            val annotated = buildAnnotatedString {
                // ── Step 1: walk char-by-char, replace private checkbox markers ──────
                for (i in spannedText.indices) {
                    when (spannedText[i]) {
                        CHECKBOX_UNCHECKED_CHAR -> {
                            val id  = "checkbox_$checkboxIndex"
                            val pos = length
                            appendInlineContent(id, "☐")          // 1 char added
                            addStringAnnotation("CHECKBOX", checkboxIndex.toString(), pos, pos + 1)
                            checkboxes.add(CheckboxInfo(id, false, checkboxIndex++))
                        }
                        CHECKBOX_CHECKED_CHAR -> {
                            val id  = "checkbox_$checkboxIndex"
                            val pos = length
                            appendInlineContent(id, "☑")           // 1 char added
                            addStringAnnotation("CHECKBOX", checkboxIndex.toString(), pos, pos + 1)
                            checkboxes.add(CheckboxInfo(id, true, checkboxIndex++))
                        }
                        else -> append(spannedText[i])
                    }
                }

                // ── Step 2: apply all Android spans (positions 1-to-1 with spannedText) ─
                val allSpans = spanned.getSpans(0, spannedText.length, Any::class.java)
                for (span in allSpans) {
                    val start = spanned.getSpanStart(span).coerceIn(0, spannedText.length)
                    val end   = spanned.getSpanEnd(span).coerceIn(0, spannedText.length)
                    if (start >= end) continue

                    when (span) {
                        is android.text.style.StyleSpan -> {
                            val s = when (span.style) {
                                android.graphics.Typeface.BOLD ->
                                    SpanStyle(fontWeight = FontWeight.Bold)
                                android.graphics.Typeface.ITALIC ->
                                    SpanStyle(fontStyle = FontStyle.Italic)
                                android.graphics.Typeface.BOLD_ITALIC ->
                                    SpanStyle(fontWeight = FontWeight.Bold, fontStyle = FontStyle.Italic)
                                else -> null
                            }
                            s?.let { addStyle(it, start, end) }
                        }
                        is android.text.style.UnderlineSpan ->
                            addStyle(SpanStyle(textDecoration = TextDecoration.Underline), start, end)
                        is android.text.style.StrikethroughSpan ->
                            addStyle(SpanStyle(textDecoration = TextDecoration.LineThrough), start, end)
                        is android.text.style.ForegroundColorSpan ->
                            addStyle(SpanStyle(color = Color(span.foregroundColor)), start, end)
                        is android.text.style.RelativeSizeSpan ->
                            // Use 16sp as base (bodyLarge) so h1 ≈ 24sp, h2 ≈ 22sp
                            addStyle(SpanStyle(fontSize = (16f * span.sizeChange).sp), start, end)
                        is android.text.style.URLSpan -> {
                            // Colour + underline + annotation for tap detection
                            addStyle(
                                SpanStyle(color = linkColor, textDecoration = TextDecoration.Underline),
                                start, end
                            )
                            addStringAnnotation("URL", span.url ?: "", start, end)
                        }
                        is TypefaceSpan -> {
                            if (span.family == "monospace") {
                                addStyle(SpanStyle(fontFamily = FontFamily.Monospace), start, end)
                            }
                        }
                        // BulletSpan / LeadingMarginSpan are dropped; lists are already
                        // pre-processed to "• " text before Html.fromHtml runs.
                    }
                }
            }

            RenderedContent(annotated, checkboxes)
        } catch (e: Exception) {
            Log.d("RichTextRenderer", "htmlToAnnotatedFull error: ${e.message}")
            RenderedContent(AnnotatedString(stripHtmlToPlainText(html)), emptyList())
        }
    }

    /**
     * Convert an Android [Spanned] (from [Html.fromHtml]) to a Compose [AnnotatedString].
     *
     * Kept for backward-compatibility with add_Note.kt's clipboard paste flow.
     * New code should use [htmlToAnnotated] or [htmlToAnnotatedFull].
     */
    fun spannedToAnnotatedString(spanned: Spanned): AnnotatedString {
        val plain = spanned.toString()
        return buildAnnotatedString {
            append(plain)
            try {
                val spans = spanned.getSpans(0, spanned.length, Any::class.java)
                for (span in spans) {
                    val start = spanned.getSpanStart(span).coerceIn(0, plain.length)
                    val end   = spanned.getSpanEnd(span).coerceIn(0, plain.length)
                    val style: SpanStyle? = when (span) {
                        is android.text.style.StyleSpan -> when (span.style) {
                            android.graphics.Typeface.BOLD ->
                                SpanStyle(fontWeight = FontWeight.Bold)
                            android.graphics.Typeface.ITALIC ->
                                SpanStyle(fontStyle = FontStyle.Italic)
                            android.graphics.Typeface.BOLD_ITALIC ->
                                SpanStyle(fontWeight = FontWeight.Bold, fontStyle = FontStyle.Italic)
                            else -> SpanStyle()
                        }
                        is android.text.style.UnderlineSpan ->
                            SpanStyle(textDecoration = TextDecoration.Underline)
                        is android.text.style.StrikethroughSpan ->
                            SpanStyle(textDecoration = TextDecoration.LineThrough)
                        is android.text.style.ForegroundColorSpan ->
                            SpanStyle(color = Color(span.foregroundColor))
                        is android.text.style.RelativeSizeSpan ->
                            SpanStyle(fontSize = (14 * span.sizeChange).sp)
                        else -> null
                    }
                    if (style != null && start < end) addStyle(style, start, end)
                }
            } catch (e: Exception) {
                Log.d("RichTextRenderer", "spannedToAnnotatedString: ${e.message}")
            }
        }
    }

    // ─── Internal helpers ─────────────────────────────────────────────────────

    /**
     * Pre-process HTML before passing to [Html.fromHtml].
     *
     * 1. Replace `<input type="checkbox" [checked]>` with [CHECKBOX_CHECKED] / [CHECKBOX_UNCHECKED]
     *    private-use characters that survive [Html.fromHtml] unchanged.
     * 2. Strip `<ul>` / `<ol>` wrapper tags.
     * 3. Replace `<li>…</li>` with `"• …<br>"` so list items render as bullet paragraphs
     *    without needing BulletSpan / LeadingMarginSpan support in Compose.
     */
    private fun preprocessHtml(html: String): String {
        var result = html

        // ── Checkboxes ────────────────────────────────────────────────────────
        // Process "checked" variants first to avoid partial matches
        result = result.replace(
            Regex("""<input\b[^>]*\bchecked\b[^>]*>""", RegexOption.IGNORE_CASE),
            CHECKBOX_CHECKED
        )
        result = result.replace(
            Regex("""<input\b[^>]*type=["']checkbox["'][^>]*>""", RegexOption.IGNORE_CASE),
            CHECKBOX_UNCHECKED
        )

        // ── Lists ─────────────────────────────────────────────────────────────
        // Render <ol> items with sequential numbers; <ul> items with bullets.
        // First handle ordered lists — number each <li> sequentially.
        result = result.replace(Regex("</?ol[^>]*>", RegexOption.IGNORE_CASE), "")
        var olIndex = 0
        result = result.replace(Regex("<li[^>]*>(?=(?:(?!</?ul).)*$)", RegexOption.IGNORE_CASE)) {
            // This branch only runs for <li> NOT inside a <ul> context — i.e. from stripped <ol>
            olIndex++
            "$olIndex. "
        }
        // Now handle unordered lists.
        result = result.replace(Regex("</?ul[^>]*>", RegexOption.IGNORE_CASE), "")
        result = result.replace(Regex("<li[^>]*>", RegexOption.IGNORE_CASE), "• ")
        result = result.replace(Regex("</li>", RegexOption.IGNORE_CASE), "<br>")

        return result
    }

    // ─── Inner classes ────────────────────────────────────────────────────────

    /**
     * [Html.TagHandler] that adds `<code>` and `<pre>` monospace support.
     *
     * Android's [Html.fromHtml] ignores these tags by default; we intercept them,
     * record the start position with a [CodeMarker] span, and then on the closing
     * tag apply a [TypefaceSpan] over the enclosed range.
     */
    private class CodeTagHandler : Html.TagHandler {
        override fun handleTag(
            opening: Boolean,
            tag: String,
            output: Editable,
            xmlReader: XMLReader
        ) {
            when (tag.lowercase()) {
                "code", "pre" -> {
                    if (opening) {
                        // Mark start position
                        output.setSpan(
                            CodeMarker(),
                            output.length,
                            output.length,
                            Spannable.SPAN_MARK_MARK
                        )
                    } else {
                        // Find the matching start marker and apply monospace
                        val markers = output.getSpans(0, output.length, CodeMarker::class.java)
                        val marker  = markers.lastOrNull() ?: return
                        val start   = output.getSpanStart(marker)
                        output.removeSpan(marker)
                        if (start < output.length) {
                            output.setSpan(
                                TypefaceSpan("monospace"),
                                start,
                                output.length,
                                Spannable.SPAN_EXCLUSIVE_EXCLUSIVE
                            )
                        }
                        // Ensure a trailing newline after <pre> blocks
                        if (tag.lowercase() == "pre" &&
                            output.isNotEmpty() &&
                            output.last() != '\n'
                        ) {
                            output.append('\n')
                        }
                    }
                }
            }
        }

        /** Zero-length marker span used to record the start of a code/pre block. */
        private class CodeMarker
    }
}

package com.amvarpvtltd.swiftNote.richtext

import android.text.Editable
import android.text.Html
import android.text.Spannable
import android.text.Spanned
import android.text.style.TypefaceSpan
import android.util.Log
import androidx.compose.foundation.text.appendInlineContent
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.AnnotatedString
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontStyle
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextDecoration
import androidx.compose.ui.unit.sp
import org.xml.sax.XMLReader

/**
 * Central HTML ↔ AnnotatedString conversion utilities.
 *
 * Phase 0: extracted from add_Note.kt's spannedToAnnotatedString.
 * Phase 1: extended with full HTML support —
 *   headings (h1/h2), bullet/ordered lists, hyperlinks, code/pre blocks,
 *   and inline checkboxes (<input type="checkbox">).
 */
object RichTextRenderer {

    // ─── Regex & private constants ────────────────────────────────────────────

    private val HTML_TAG_REGEX = Regex(
        "<(/?)(b|strong|i|em|u|s|h1|h2|p|br|ul|ol|li|a|code|pre|input)\\b[^>]*>",
        RegexOption.IGNORE_CASE
    )

    /**
     * Private-Use-Area Unicode chars that act as in-band markers for checkboxes
     * during the HTML pre-processing step.  They survive [Html.fromHtml] unchanged.
     */
    internal const val CHECKBOX_UNCHECKED = "\uE001"
    internal const val CHECKBOX_CHECKED   = "\uE002"
    private  const val CHECKBOX_UNCHECKED_CHAR = '\uE001'
    private  const val CHECKBOX_CHECKED_CHAR   = '\uE002'

    /** Default link colour — matches NoteTheme.Primary; callers may override. */
    val DEFAULT_LINK_COLOR = Color(0xFF6366F1)

    // ─── Public data classes ──────────────────────────────────────────────────

    /**
     * Metadata for a single inline checkbox detected in the HTML.
     *
     * @param id       Unique key used in the [androidx.compose.foundation.text.InlineTextContent] map.
     * @param checked  Whether the checkbox is checked.
     * @param index    Zero-based index within this note's checkbox list — used to locate
     *                 the checkbox in the original HTML for toggling.
     */
    data class CheckboxInfo(
        val id: String,
        val checked: Boolean,
        val index: Int
    )

    /**
     * Full result of converting an HTML string.
     *
     * @param annotated  Compose [AnnotatedString] ready for [androidx.compose.material3.Text].
     * @param checkboxes Ordered list of checkboxes found; each carries an [InlineTextContent] key.
     */
    data class RenderedContent(
        val annotated: AnnotatedString,
        val checkboxes: List<CheckboxInfo>
    )

    // ─── Public API ───────────────────────────────────────────────────────────

    /** Returns true if the string appears to contain HTML markup. */
    fun containsHtml(text: String): Boolean = HTML_TAG_REGEX.containsMatchIn(text)

    /**
     * Strip HTML tags and return plain text — suitable for search or entity detection.
     */
    fun stripHtmlToPlainText(html: String): String {
        if (!containsHtml(html)) return html
        return try {
            Html.fromHtml(html, Html.FROM_HTML_MODE_COMPACT).toString()
        } catch (e: Exception) {
            Log.d("RichTextRenderer", "stripHtmlToPlainText: ${e.message}")
            html
        }
    }

    /**
     * Convenience overload — converts HTML to [AnnotatedString] only.
     * For notes that may contain checkboxes, prefer [htmlToAnnotatedFull].
     */
    fun htmlToAnnotated(html: String): AnnotatedString = htmlToAnnotatedFull(html).annotated

    /**
     * Full conversion: HTML → [RenderedContent] (annotated text + checkbox list).
     *
     * Supported features:
     * - **Bold / italic / underline / strikethrough** (b/i/u/s and their semantic aliases)
     * - **H1 / H2 headings** — rendered larger and bold (handled by Android's Html.fromHtml)
     * - **Unordered & ordered lists** — converted to "• " / "N. " bullet text in pre-processing
     * - **Hyperlinks** — coloured, underlined, tap-to-open via [RichTextDisplay]
     * - **`<code>` / `<pre>`** — monospace font family
     * - **`<input type="checkbox">`** — replaced with [appendInlineContent] placeholders
     *
     * @param html      Raw HTML string from Room / clipboard.
     * @param linkColor Colour applied to hyperlink text; defaults to [DEFAULT_LINK_COLOR].
     */
    fun htmlToAnnotatedFull(
        html: String,
        linkColor: Color = DEFAULT_LINK_COLOR
    ): RenderedContent {
        if (!containsHtml(html)) {
            return RenderedContent(AnnotatedString(html), emptyList())
        }
        return try {
            val preprocessed = preprocessHtml(html)
            val spanned: Spanned = Html.fromHtml(
                preprocessed,
                Html.FROM_HTML_MODE_COMPACT,
                null,
                CodeTagHandler()
            )

            val checkboxes = mutableListOf<CheckboxInfo>()
            val spannedText = spanned.toString()
            var checkboxIndex = 0

            val annotated = buildAnnotatedString {
                // ── Step 1: walk char-by-char, replace private checkbox markers ──────
                for (i in spannedText.indices) {
                    when (spannedText[i]) {
                        CHECKBOX_UNCHECKED_CHAR -> {
                            val id  = "checkbox_$checkboxIndex"
                            val pos = length
                            appendInlineContent(id, "☐")          // 1 char added
                            addStringAnnotation("CHECKBOX", checkboxIndex.toString(), pos, pos + 1)
                            checkboxes.add(CheckboxInfo(id, false, checkboxIndex++))
                        }
                        CHECKBOX_CHECKED_CHAR -> {
                            val id  = "checkbox_$checkboxIndex"
                            val pos = length
                            appendInlineContent(id, "☑")           // 1 char added
                            addStringAnnotation("CHECKBOX", checkboxIndex.toString(), pos, pos + 1)
                            checkboxes.add(CheckboxInfo(id, true, checkboxIndex++))
                        }
                        else -> append(spannedText[i])
                    }
                }

                // ── Step 2: apply all Android spans (positions 1-to-1 with spannedText) ─
                val allSpans = spanned.getSpans(0, spannedText.length, Any::class.java)
                for (span in allSpans) {
                    val start = spanned.getSpanStart(span).coerceIn(0, spannedText.length)
                    val end   = spanned.getSpanEnd(span).coerceIn(0, spannedText.length)
                    if (start >= end) continue

                    when (span) {
                        is android.text.style.StyleSpan -> {
                            val s = when (span.style) {
                                android.graphics.Typeface.BOLD ->
                                    SpanStyle(fontWeight = FontWeight.Bold)
                                android.graphics.Typeface.ITALIC ->
                                    SpanStyle(fontStyle = FontStyle.Italic)
                                android.graphics.Typeface.BOLD_ITALIC ->
                                    SpanStyle(fontWeight = FontWeight.Bold, fontStyle = FontStyle.Italic)
                                else -> null
                            }
                            s?.let { addStyle(it, start, end) }
                        }
                        is android.text.style.UnderlineSpan ->
                            addStyle(SpanStyle(textDecoration = TextDecoration.Underline), start, end)
                        is android.text.style.StrikethroughSpan ->
                            addStyle(SpanStyle(textDecoration = TextDecoration.LineThrough), start, end)
                        is android.text.style.ForegroundColorSpan ->
                            addStyle(SpanStyle(color = Color(span.foregroundColor)), start, end)
                        is android.text.style.RelativeSizeSpan ->
                            // Use 16sp as base (bodyLarge) so h1 ≈ 24sp, h2 ≈ 22sp
                            addStyle(SpanStyle(fontSize = (16f * span.sizeChange).sp), start, end)
                        is android.text.style.URLSpan -> {
                            // Colour + underline + annotation for tap detection
                            addStyle(
                                SpanStyle(color = linkColor, textDecoration = TextDecoration.Underline),
                                start, end
                            )
                            addStringAnnotation("URL", span.url ?: "", start, end)
                        }
                        is TypefaceSpan -> {
                            if (span.family == "monospace") {
                                addStyle(SpanStyle(fontFamily = FontFamily.Monospace), start, end)
                            }
                        }
                        // BulletSpan / LeadingMarginSpan are dropped; lists are already
                        // pre-processed to "• " text before Html.fromHtml runs.
                    }
                }
            }

            RenderedContent(annotated, checkboxes)
        } catch (e: Exception) {
            Log.d("RichTextRenderer", "htmlToAnnotatedFull error: ${e.message}")
            RenderedContent(AnnotatedString(stripHtmlToPlainText(html)), emptyList())
        }
    }

    /**
     * Convert an Android [Spanned] (from [Html.fromHtml]) to a Compose [AnnotatedString].
     *
     * Kept for backward-compatibility with add_Note.kt's clipboard paste flow.
     * New code should use [htmlToAnnotated] or [htmlToAnnotatedFull].
     */
    fun spannedToAnnotatedString(spanned: Spanned): AnnotatedString {
        val plain = spanned.toString()
        return buildAnnotatedString {
            append(plain)
            try {
                val spans = spanned.getSpans(0, spanned.length, Any::class.java)
                for (span in spans) {
                    val start = spanned.getSpanStart(span).coerceIn(0, plain.length)
                    val end   = spanned.getSpanEnd(span).coerceIn(0, plain.length)
                    val style: SpanStyle? = when (span) {
                        is android.text.style.StyleSpan -> when (span.style) {
                            android.graphics.Typeface.BOLD ->
                                SpanStyle(fontWeight = FontWeight.Bold)
                            android.graphics.Typeface.ITALIC ->
                                SpanStyle(fontStyle = FontStyle.Italic)
                            android.graphics.Typeface.BOLD_ITALIC ->
                                SpanStyle(fontWeight = FontWeight.Bold, fontStyle = FontStyle.Italic)
                            else -> SpanStyle()
                        }
                        is android.text.style.UnderlineSpan ->
                            SpanStyle(textDecoration = TextDecoration.Underline)
                        is android.text.style.StrikethroughSpan ->
                            SpanStyle(textDecoration = TextDecoration.LineThrough)
                        is android.text.style.ForegroundColorSpan ->
                            SpanStyle(color = Color(span.foregroundColor))
                        is android.text.style.RelativeSizeSpan ->
                            SpanStyle(fontSize = (14 * span.sizeChange).sp)
                        else -> null
                    }
                    if (style != null && start < end) addStyle(style, start, end)
                }
            } catch (e: Exception) {
                Log.d("RichTextRenderer", "spannedToAnnotatedString: ${e.message}")
            }
        }
    }

    // ─── Internal helpers ─────────────────────────────────────────────────────

    /**
     * Pre-process HTML before passing to [Html.fromHtml].
     *
     * 1. Replace `<input type="checkbox" [checked]>` with [CHECKBOX_CHECKED] / [CHECKBOX_UNCHECKED]
     *    private-use characters that survive [Html.fromHtml] unchanged.
     * 2. Strip `<ul>` / `<ol>` wrapper tags.
     * 3. Replace `<li>…</li>` with `"• …<br>"` so list items render as bullet paragraphs
     *    without needing BulletSpan / LeadingMarginSpan support in Compose.
     */
    private fun preprocessHtml(html: String): String {
        var result = html

        // ── Checkboxes ────────────────────────────────────────────────────────
        // Process "checked" variants first to avoid partial matches
        result = result.replace(
            Regex("""<input\b[^>]*\bchecked\b[^>]*>""", RegexOption.IGNORE_CASE),
            CHECKBOX_CHECKED
        )
        result = result.replace(
            Regex("""<input\b[^>]*type=["']checkbox["'][^>]*>""", RegexOption.IGNORE_CASE),
            CHECKBOX_UNCHECKED
        )

        // ── Lists ─────────────────────────────────────────────────────────────
        // Render <ol> items with sequential numbers; <ul> items with bullets.
        // Process <ol>...</ol> blocks first, numbering each <li>.
        result = result.replace(Regex("<ol[^>]*>(.*?)</ol>", setOf(RegexOption.IGNORE_CASE, RegexOption.DOT_MATCHES_ALL))) { match ->
            var idx = 0
            match.groupValues[1]
                .replace(Regex("<li[^>]*>", RegexOption.IGNORE_CASE)) { idx++; "$idx. " }
                .replace(Regex("</li>", RegexOption.IGNORE_CASE), "<br>")
        }
        // Process <ul>...</ul> blocks with bullet prefix.
        result = result.replace(Regex("<ul[^>]*>(.*?)</ul>", setOf(RegexOption.IGNORE_CASE, RegexOption.DOT_MATCHES_ALL))) { match ->
            match.groupValues[1]
                .replace(Regex("<li[^>]*>", RegexOption.IGNORE_CASE), "• ")
                .replace(Regex("</li>", RegexOption.IGNORE_CASE), "<br>")
        }
        // Fallback: any remaining bare <li> (shouldn't happen, but just in case)
        result = result.replace(Regex("<li[^>]*>", RegexOption.IGNORE_CASE), "• ")
        result = result.replace(Regex("</li>", RegexOption.IGNORE_CASE), "<br>")

        return result
    }

    // ─── Inner classes ────────────────────────────────────────────────────────

    /**
     * [Html.TagHandler] that adds `<code>` and `<pre>` monospace support.
     *
     * Android's [Html.fromHtml] ignores these tags by default; we intercept them,
     * record the start position with a [CodeMarker] span, and then on the closing
     * tag apply a [TypefaceSpan] over the enclosed range.
     */
    private class CodeTagHandler : Html.TagHandler {
        override fun handleTag(
            opening: Boolean,
            tag: String,
            output: Editable,
            xmlReader: XMLReader
        ) {
            when (tag.lowercase()) {
                "code", "pre" -> {
                    if (opening) {
                        // Mark start position
                        output.setSpan(
                            CodeMarker(),
                            output.length,
                            output.length,
                            Spannable.SPAN_MARK_MARK
                        )
                    } else {
                        // Find the matching start marker and apply monospace
                        val markers = output.getSpans(0, output.length, CodeMarker::class.java)
                        val marker  = markers.lastOrNull() ?: return
                        val start   = output.getSpanStart(marker)
                        output.removeSpan(marker)
                        if (start < output.length) {
                            output.setSpan(
                                TypefaceSpan("monospace"),
                                start,
                                output.length,
                                Spannable.SPAN_EXCLUSIVE_EXCLUSIVE
                            )
                        }
                        // Ensure a trailing newline after <pre> blocks
                        if (tag.lowercase() == "pre" &&
                            output.isNotEmpty() &&
                            output.last() != '\n'
                        ) {
                            output.append('\n')
                        }
                    }
                }
            }
        }

        /** Zero-length marker span used to record the start of a code/pre block. */
        private class CodeMarker
    }
}

package com.amvarpvtltd.swiftNote.components

import androidx.compose.animation.animateColorAsState
import androidx.compose.animation.core.tween
import androidx.compose.foundation.background
