@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SearchBar(
    searchQuery: String,
    onSearchQueryChange: (String) -> Unit,
    isSearchActive: Boolean,
    onSearchActiveChange: (Boolean) -> Unit,
    onClearSearch: () -> Unit,
    modifier: Modifier = Modifier,
    placeholder: String = "Search notes..."
) {
    val focusRequester = remember { FocusRequester() }
    val keyboardController = LocalSoftwareKeyboardController.current
    val hapticFeedback = LocalHapticFeedback.current

    // Local state for immediate text updates to ensure typing works
    var localSearchQuery by remember { mutableStateOf(searchQuery) }

    // Sync local state with external prop changes
    LaunchedEffect(searchQuery) {
        if (localSearchQuery != searchQuery) {
            localSearchQuery = searchQuery
        }
    }

    LaunchedEffect(isSearchActive) {
        if (isSearchActive) {
            focusRequester.requestFocus()
        }
    }

    Card(
        modifier = modifier
            .fillMaxWidth()
            .height(48.dp)
            .animateContentSize(),
        colors = CardDefaults.cardColors(containerColor = NoteTheme.Surface),
        shape = RoundedCornerShape(NoteTheme.Radius.full.dp),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
        border = androidx.compose.foundation.BorderStroke(
            width = 1.dp,
            color = NoteTheme.Outline
        )
    ) {
        Row(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 12.dp, ),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                imageVector = Icons.Outlined.Search,
                contentDescription = "Search",
                tint = if (isSearchActive || localSearchQuery.isNotEmpty()) NoteTheme.Primary else NoteTheme.OnSurfaceVariant,
                modifier = Modifier.size(20.dp)
            )

            Spacer(modifier = Modifier.width(8.dp))

            TextField(
                value = localSearchQuery,
                onValueChange = { newValue ->
                    localSearchQuery = newValue
                    onSearchQueryChange(newValue)
                    // Update search active state immediately
                    if (newValue.isNotEmpty() && !isSearchActive) {
                        onSearchActiveChange(true)
                    } else if (newValue.isEmpty() && isSearchActive) {
                        onSearchActiveChange(false)
                    }
                },
                modifier = Modifier
                    .weight(1f)
                    .focusRequester(focusRequester),
                placeholder = {
                    Text(
                        text = placeholder,
                        color = NoteTheme.OnSurfaceVariant,
                        style = MaterialTheme.typography.bodyMedium
                    )
                },
                singleLine = true,
                keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
                keyboardActions = KeyboardActions(
                    onSearch = {
                        keyboardController?.hide()
                        if (localSearchQuery.isNotEmpty()) {
                            onSearchActiveChange(true)
                        }
                    }
                ),
                colors = TextFieldDefaults.colors(
                    focusedIndicatorColor = Color.Transparent,
                    unfocusedIndicatorColor = Color.Transparent,
                    disabledIndicatorColor = Color.Transparent,
                    errorIndicatorColor = Color.Transparent,
                    focusedContainerColor = Color.Transparent,
                    unfocusedContainerColor = Color.Transparent,
                    disabledContainerColor = Color.Transparent,
                    cursorColor = NoteTheme.Primary,
                    focusedTextColor = NoteTheme.OnSurface,
                    unfocusedTextColor = NoteTheme.OnSurface
                ),
                textStyle = MaterialTheme.typography.bodyMedium
            )

            AnimatedVisibility(
                visible = localSearchQuery.isNotEmpty(),
                enter = scaleIn() + fadeIn(),
                exit = scaleOut() + fadeOut()
            ) {
                IconButton(
                    onClick = {
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.LongPress)
                        localSearchQuery = ""
                        onClearSearch()
                        onSearchActiveChange(false)
                        keyboardController?.hide()
                    },
                    modifier = Modifier.size(30.dp) // Increased clear button size slightly for 50dp height
                ) {
                    Icon(
                        imageVector = Icons.Default.Clear,
                        contentDescription = "Clear search",
                        tint = NoteTheme.OnSurfaceVariant,
                        modifier = Modifier.size(16.dp)
                    )
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SortOptionsSheet(
    currentSort: SortOption,
    onSortChange: (SortOption) -> Unit,
    onDismiss: () -> Unit,
    modifier: Modifier = Modifier
) {
    val hapticFeedback = LocalHapticFeedback.current

    ModalBottomSheet(
        onDismissRequest = onDismiss,
        containerColor = NoteTheme.Surface,
        modifier = modifier
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(Constants.PADDING_MEDIUM.dp)
        ) {
            // Header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Sort Notes",
                    style = MaterialTheme.typography.headlineSmall,
                    fontWeight = FontWeight.Bold,
                    color = NoteTheme.OnSurface
                )

                IconButton(onClick = onDismiss) {
                    Icon(
                        Icons.Default.Close,
                        contentDescription = "Close",
                        tint = NoteTheme.OnSurfaceVariant
                    )
                }
            }

            Spacer(modifier = Modifier.height(Constants.PADDING_MEDIUM.dp))

            // Sort options
            SortOption.values().forEach { option ->
                SortOptionItem(
                    sortOption = option,
                    isSelected = currentSort == option,
                    onClick = {
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.LongPress)
                        onSortChange(option)
                        onDismiss()
                    }
                )
            }

            Spacer(modifier = Modifier.height(Constants.PADDING_LARGE.dp))
        }
    }
}

@Composable
private fun SortOptionItem(
    sortOption: SortOption,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(vertical = 4.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (isSelected)
                NoteTheme.Primary.copy(alpha = 0.1f)
            else
                Color.Transparent
        ),
        shape = RoundedCornerShape(Constants.CORNER_RADIUS_SMALL.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(Constants.PADDING_MEDIUM.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                imageVector = SearchAndSortManager.getSortIcon(sortOption),
                contentDescription = null,
                tint = if (isSelected) NoteTheme.Primary else NoteTheme.OnSurfaceVariant,
                modifier = Modifier.size(Constants.ICON_SIZE_LARGE.dp)
            )

            Spacer(modifier = Modifier.width(Constants.PADDING_MEDIUM.dp))

            Text(
                text = SearchAndSortManager.getSortOptionLabel(sortOption),
                style = MaterialTheme.typography.bodyLarge,
                color = if (isSelected) NoteTheme.Primary else NoteTheme.OnSurface,
                fontWeight = if (isSelected) FontWeight.SemiBold else FontWeight.Normal,
                modifier = Modifier.weight(1f)
            )

            if (isSelected) {
                Icon(
                    imageVector = Icons.Default.Check,
                    contentDescription = "Selected",
                    tint = NoteTheme.Primary,
                    modifier = Modifier.size(Constants.ICON_SIZE_MEDIUM.dp)
                )
            }
        }
    }
}

@Composable
fun ThemeToggleButton(
    currentTheme: com.amvarpvtltd.swiftNote.theme.ThemeMode,
    onThemeChange: (com.amvarpvtltd.swiftNote.theme.ThemeMode) -> Unit,
    modifier: Modifier = Modifier
) {
    val hapticFeedback = LocalHapticFeedback.current
    val context = LocalContext.current

    // Use adaptive colors for consistency with other buttons
    val (containerColor, contentColor) = adaptiveIconColors(NoteTheme.Background, NoteTheme.Secondary)

    Card(
        modifier = modifier
            .clickable {
                hapticFeedback.performHapticFeedback(HapticFeedbackType.LongPress)
                val nextTheme = when (currentTheme) {
                    com.amvarpvtltd.swiftNote.theme.ThemeMode.LIGHT -> com.amvarpvtltd.swiftNote.theme.ThemeMode.DARK
                    com.amvarpvtltd.swiftNote.theme.ThemeMode.DARK -> com.amvarpvtltd.swiftNote.theme.ThemeMode.SYSTEM
                    com.amvarpvtltd.swiftNote.theme.ThemeMode.SYSTEM -> com.amvarpvtltd.swiftNote.theme.ThemeMode.LIGHT
                }

                // Show toast notification based on the theme being changed to
                val toastMessage = when (nextTheme) {
                    com.amvarpvtltd.swiftNote.theme.ThemeMode.LIGHT -> " Light mode activated"
                    com.amvarpvtltd.swiftNote.theme.ThemeMode.DARK -> " Dark mode activated"
                    com.amvarpvtltd.swiftNote.theme.ThemeMode.SYSTEM -> " System theme activated"
                }

                Toast.makeText(context, toastMessage, Toast.LENGTH_SHORT).show()
                onThemeChange(nextTheme)
            },
        shape = CircleShape,
        colors = CardDefaults.cardColors(
            containerColor = containerColor
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Box(
            modifier = Modifier.padding(Constants.PADDING_SMALL.dp),
            contentAlignment = Alignment.Center
        ) {
            val (icon, contentDescription) = when (currentTheme) {
                com.amvarpvtltd.swiftNote.theme.ThemeMode.LIGHT -> Icons.Outlined.LightMode to "Switch to dark mode"
                com.amvarpvtltd.swiftNote.theme.ThemeMode.DARK -> Icons.Outlined.DarkMode to "Switch to system theme"
                com.amvarpvtltd.swiftNote.theme.ThemeMode.SYSTEM -> Icons.Outlined.SettingsBrightness to "Switch to light mode"
            }

            Icon(
                imageVector = icon,
                contentDescription = contentDescription,
                tint = contentColor,
                modifier = Modifier.size(Constants.ICON_SIZE_LARGE.dp)
            )
        }
    }
}

@Composable
fun SyncStatusIndicator(
    isOnline: Boolean,
    hasPendingSync: Boolean,
    isSyncing: Boolean = false,
    onSyncClick: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val hapticFeedback = LocalHapticFeedback.current

    // Only show the indicator when there's actually syncing happening or pending sync with offline status
    AnimatedVisibility(
        visible = isSyncing || (hasPendingSync && !isOnline),
        enter = scaleIn() + fadeIn(),
        exit = scaleOut() + fadeOut(),
        modifier = modifier
    ) {
        // Determine adaptive colors using background luminance so icon remains visible
        val (containerColor, contentColor) = when {
            isSyncing -> Pair(NoteTheme.Primary.copy(alpha = 0.1f), NoteTheme.Primary)
            !isOnline -> adaptiveIconColors(NoteTheme.Background, NoteTheme.Error)
            else -> adaptiveIconColors(NoteTheme.Background, NoteTheme.Warning)
        }

        Card(
            modifier = Modifier
                .clickable(enabled = !isSyncing && hasPendingSync) {
                    hapticFeedback.performHapticFeedback(HapticFeedbackType.LongPress)
                    onSyncClick()
                },
            colors = CardDefaults.cardColors(
                containerColor = containerColor
            ),
            shape = RoundedCornerShape(Constants.CORNER_RADIUS_SMALL.dp)
        ) {
            Row(
                modifier = Modifier.padding(Constants.PADDING_SMALL.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                if (isSyncing) {
                    // Show spinning animation when syncing
                    CircularProgressIndicator(
                        modifier = Modifier.size(Constants.ICON_SIZE_SMALL.dp),
                        strokeWidth = 2.dp,
                        color = contentColor
                    )
                } else {
                    Icon(
                        imageVector = if (isOnline) Icons.Outlined.CloudSync else Icons.Outlined.CloudOff,
                        contentDescription = if (isOnline) "Sync pending" else "Offline",
                        tint = contentColor,
                        modifier = Modifier.size(Constants.ICON_SIZE_SMALL.dp)
                    )
                }

                Spacer(modifier = Modifier.width(4.dp))

                Text(
                    text = when {
                        isSyncing -> "Syncing..."
                        !isOnline -> "Offline"
                        else -> "Sync"
                    },
                    style = MaterialTheme.typography.labelSmall,
                    color = contentColor,
                    fontWeight = FontWeight.Medium
                )
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.ai

import android.annotation.SuppressLint
import android.content.Context
import android.util.Log
import com.google.mlkit.nl.entityextraction.DateTimeEntity
import com.google.mlkit.nl.entityextraction.EntityAnnotation
import com.google.mlkit.nl.entityextraction.EntityExtraction
import com.google.mlkit.nl.entityextraction.EntityExtractor
import com.google.mlkit.nl.entityextraction.EntityExtractorOptions
import com.amvarpvtltd.swiftNote.richtext.RichTextBridge
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Date
import java.util.Locale
import java.util.UUID
import kotlin.coroutines.resume

class SmartReminderAI(private val context: Context) {
    private val TAG = "SmartReminderAI"

    private lateinit var entityExtractor: EntityExtractor
    private var isInitialized = false

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: SmartReminderAI? = null

        fun getInstance(context: Context): SmartReminderAI {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: SmartReminderAI(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    /**
     * Initialize ML Kit Entity Extractor
     */
    suspend fun initialize(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            suspendCancellableCoroutine<Result<String>> { continuation ->
                val options = EntityExtractorOptions.Builder(EntityExtractorOptions.ENGLISH)
                    .build()

                entityExtractor = EntityExtraction.getClient(options)

                entityExtractor.downloadModelIfNeeded()
                    .addOnSuccessListener {
                        Log.d(TAG, "✅ ML Kit Entity Extractor initialized successfully")
                        isInitialized = true
                        continuation.resume(Result.success("AI initialized successfully"))
                    }
                    .addOnFailureListener { exception ->
                        Log.e(TAG, "❌ Failed to initialize ML Kit Entity Extractor", exception)
                        continuation.resume(Result.failure(exception))
                    }

                continuation.invokeOnCancellation {
                    Log.d(TAG, " Entity Extractor initialization cancelled")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error initializing Entity Extractor", e)
            Result.failure(e)
        }
    }

    /**
     * Analyze text for date/time entities and return detected reminders.
     *
     * Pipeline (smartest → fastest):
     *   1. AI (cloud, ~1-2s) — tried first if available (user has API key, Gemini or Groq)
     *   2. ML Kit Entity Extraction (on-device, instant) — fallback if AI fails/unavailable
     *   3. Regex fallback (on-device, instant, handles Hinglish) — last resort
     */
    suspend fun analyzeTextForReminders(
        text: String,
        noteTitle: String = "Untitled"
    ): Result<List<DetectedReminder>> = withContext(Dispatchers.IO) {
        // ───────────────────────────────────────────────────────────────
        // LLM-first path (multilingual).
        // When the user has configured an API key, bypass the English/Hinglish-only
        // ReminderIntentAnalyzer keyword gate and send the raw text directly to the
        // LLM. The LLM can natively understand any language it supports (Spanish,
        // French, German, Japanese, Arabic, Chinese, Portuguese, Russian, Bengali,
        // Tamil, Marathi, Gujarati, Punjabi, etc.) and will respond with
        // hasReminder=false when no intent is present, so this is safe.
        // ───────────────────────────────────────────────────────────────
        val geminiAvailable = try {
            GeminiReminderParser.getInstance(context).isAvailable()
        } catch (_: Exception) { false }

        if (geminiAvailable) {
            // Defensive HTML strip in case caller passed rich-text content.
            val plain = try { RichTextBridge.stripHtmlToPlainText(text) } catch (_: Exception) { text }
            val llmInput = plain.trim().ifBlank { text.trim() }

            if (llmInput.isNotBlank()) {
                Log.d(TAG, " AI available — routing text directly to LLM (multilingual mode)")
                val geminiResults = tryGeminiParsing(llmInput, noteTitle)
                if (geminiResults.isNotEmpty()) {
                    Log.d(TAG, "AI returned ${geminiResults.size} reminder(s) - using AI response")
                    return@withContext Result.success(geminiResults)
                }
                Log.d(TAG, "AI returned no results - falling back to on-device methods")
            }
        }

        // ───────────────────────────────────────────────────────────────
        // On-device fallback (ML Kit + regex) — keyword-gated, English/Hinglish only.
        // ───────────────────────────────────────────────────────────────
        val analysisText = ReminderIntentAnalyzer.buildAnalysisText(
            noteBody = text,
            noteTitle = noteTitle
        )

        if (analysisText.isNullOrBlank()) {
            Log.d(TAG, "No sentence-level reminder intent found, skipping analysis")
            return@withContext Result.success(emptyList())
        }

        Log.d(TAG, "Analyzing reminder-focused text: ${analysisText.take(100)}...")


        if (!isInitialized) {
            Log.w(TAG, "Entity Extractor not initialized, attempting to initialize...")
            val initResult = initialize()
            if (initResult.isFailure) {
                Log.w(TAG, "ML Kit init failed, using regex fallback: ${initResult.exceptionOrNull()?.message}")
                val regexResults = try {
                    regexFallbackForReminders(analysisText, noteTitle)
                } catch (_: Exception) {
                    emptyList()
                }
                return@withContext Result.success(regexResults)
            }
        }

        return@withContext try {
            suspendCancellableCoroutine<Result<List<DetectedReminder>>> { continuation ->
                entityExtractor.annotate(analysisText)
                    .addOnSuccessListener { entityAnnotations ->
                        val detectedReminders = processEntityAnnotations(
                            entityAnnotations,
                            analysisText,
                            noteTitle
                        )

                        val finalResults = detectedReminders.ifEmpty {
                            val fallback = regexFallbackForReminders(analysisText, noteTitle)
                            if (fallback.isNotEmpty()) {
                                Log.d(TAG, "Regex fallback detected ${fallback.size} reminder(s)")
                            }
                            fallback
                        }

                        Log.d(TAG, "Found ${finalResults.size} potential reminders (on-device)")
                        continuation.resume(Result.success(finalResults))
                    }
                    .addOnFailureListener { exception ->
                        Log.e(TAG, "ML Kit annotation failed, using regex fallback", exception)

                        val fallback = regexFallbackForReminders(analysisText, noteTitle)
                        if (fallback.isNotEmpty()) {
                            Log.d(TAG, "Regex fallback detected ${fallback.size} reminder(s) after ML Kit failure")
                        }
                        continuation.resume(Result.success(fallback))
                    }

                continuation.invokeOnCancellation {
                    Log.d(TAG, "Text analysis cancelled")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error in analyzeTextForReminders - falling back to regex", e)
            val regexResults = try {
                regexFallbackForReminders(analysisText, noteTitle)
            } catch (_: Exception) {
                emptyList()
            }
            return@withContext Result.success(regexResults)
        }
    }

    /**
     * Try parsing with AI (Gemini or Groq). Returns empty list on failure (never throws).
     * This is the intelligent fallback for when on-device methods can't parse the text.
     */
    private suspend fun tryGeminiParsing(text: String, noteTitle: String): List<DetectedReminder> {
        return try {
            val gemini = GeminiReminderParser.getInstance(context)
            val parsed = gemini.parseReminderIntent(text, noteTitle)
            if (parsed != null) {
                val results = gemini.toDetectedReminders(parsed, noteTitle)
                Log.d(TAG, " AI detected ${results.size} reminder(s)")
                results
            } else {
                Log.d(TAG, " AI found no reminder intent")
                emptyList()
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ AI parsing failed silently: ${e.message}")
            emptyList()
        }
    }

    /**
     * Explicitly analyze text using AI (bypasses ML Kit + regex).
     * Use this when:
     * - User taps "Analyze with AI" button
     * - On-device methods returned no results but user insists there's a reminder
     * - Text is in a language that regex/ML Kit can't handle well
     *
     * @return Result with list of detected reminders, or failure if AI is unavailable
     */
    suspend fun analyzeWithGemini(
        text: String,
        noteTitle: String = "Untitled"
    ): Result<List<DetectedReminder>> = withContext(Dispatchers.IO) {
        return@withContext try {
            val gemini = GeminiReminderParser.getInstance(context)
            val parsed = gemini.parseReminderIntent(text, noteTitle)
            if (parsed != null) {
                val results = gemini.toDetectedReminders(parsed, noteTitle)
                Log.d(TAG, " AI explicit analysis: ${results.size} reminder(s)")
                Result.success(results)
            } else {
                Result.success(emptyList())
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Gemini explicit analysis failed: ${e.message}", e)
            Result.failure(e)
        }
    }

    /**
     * Process ML Kit entity annotations to extract date/time information
     */
    private fun processEntityAnnotations(
        annotations: List<EntityAnnotation>,
        originalText: String,
        noteTitle: String
    ): List<DetectedReminder> {
        val reminders = mutableListOf<DetectedReminder>()
        val currentTime = System.currentTimeMillis()

        annotations.forEach { annotation ->
            annotation.entities.forEach { entity ->
                when (entity) {
                    is DateTimeEntity -> {
                        val reminderDateTime = processDateTimeEntity(entity)

                        if (reminderDateTime != null && reminderDateTime > currentTime) {
                            val extractedText = originalText.substring(
                                annotation.start,
                                annotation.end.coerceAtMost(originalText.length)
                            )

                            val reminder = DetectedReminder(
                                id = UUID.randomUUID().toString(),
                                title = generateReminderTitle(extractedText, noteTitle),
                                description = generateReminderDescription(extractedText, originalText),
                                extractedText = extractedText,
                                reminderDateTime = reminderDateTime,
                                confidence = calculateConfidence(entity, extractedText),
                                entityType = "DateTime",
                                originalNoteTitle = noteTitle
                            )

                            reminders.add(reminder)
                            Log.d(TAG, " Detected reminder: ${reminder.title} at ${formatDateTime(reminderDateTime)}")
                        }
                    }
                }
            }
        }

        return reminders.distinctBy { it.reminderDateTime }.sortedBy { it.reminderDateTime }
    }
    private fun processDateTimeEntity(entity: DateTimeEntity): Long? {
        return try {
            val calendar = Calendar.getInstance()

            when (entity.dateTimeGranularity) {
                DateTimeEntity.GRANULARITY_DAY -> {
                    val timestamp = entity.timestampMillis
                    calendar.timeInMillis = timestamp
                    // Set to 9 AM if only date is specified
                    calendar.set(Calendar.HOUR_OF_DAY, 9)
                    calendar.set(Calendar.MINUTE, 0)
                    calendar.set(Calendar.SECOND, 0)
                    calendar.timeInMillis
                }
                DateTimeEntity.GRANULARITY_HOUR -> entity.timestampMillis
                DateTimeEntity.GRANULARITY_MINUTE -> entity.timestampMillis
                else -> entity.timestampMillis
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error processing DateTimeEntity", e)
            null
        }
    }

    /**
     * Generate a meaningful reminder title
     */
    private fun generateReminderTitle(extractedText: String, noteTitle: String): String {
        return when {
            extractedText.contains("appointment", ignoreCase = true) -> " Appointment Reminder"
            extractedText.contains("meeting", ignoreCase = true) -> " Meeting Reminder"
            extractedText.contains("call", ignoreCase = true) -> " Call Reminder"
            extractedText.contains("deadline", ignoreCase = true) -> "⏰ Deadline Reminder"
            extractedText.contains("reminder", ignoreCase = true) -> " Personal Reminder"
            noteTitle.isNotBlank() && noteTitle != "Untitled" -> " $noteTitle"
            else -> " Smart Reminder"
        }
    }

    /**
     * Generate reminder description from context
     */
    private fun generateReminderDescription(extractedText: String, fullText: String): String {
        // Find the sentence containing the extracted text
        val sentences = fullText.split(Regex("[.!?]+"))
        val relevantSentence = sentences.find { it.contains(extractedText, ignoreCase = true) }

        return relevantSentence?.trim()?.takeIf { it.isNotBlank() }
            ?: extractedText.trim().takeIf { it.isNotBlank() }
            ?: "Reminder from your note"
    }

    /**
     * Format date/time for display
     */
    private fun formatDateTime(timestamp: Long): String {
        val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
        return formatter.format(Date(timestamp))
    }

    /**
     * Check if text contains potential reminder keywords
     */
    fun hasReminderKeywords(text: String): Boolean {
        return ReminderIntentAnalyzer.hasReminderIntent(noteBody = text)
    }

    /**
     * Calculate confidence for the detected reminder based on entity characteristics
     */
    private fun calculateConfidence(entity: DateTimeEntity, extractedText: String): Float {

        var confidence = 0.7f // Base confidence

        // Higher confidence for more specific time granularity
        when (entity.dateTimeGranularity) {
            DateTimeEntity.GRANULARITY_MINUTE -> confidence += 0.2f
            DateTimeEntity.GRANULARITY_HOUR -> confidence += 0.15f
            DateTimeEntity.GRANULARITY_DAY -> confidence += 0.1f
            else -> confidence += 0.05f
        }

        // Higher confidence for explicit reminder keywords
        val reminderKeywords = listOf("remind", "appointment", "meeting", "deadline", "alarm")
        if (reminderKeywords.any { extractedText.contains(it, ignoreCase = true) }) {
            confidence += 0.1f
        }

        // Ensure confidence is between 0.0 and 1.0
        return confidence.coerceIn(0.0f, 1.0f)
    }

    private fun regexFallbackForReminders(text: String, noteTitle: String): List<DetectedReminder> {
        val reminders = mutableListOf<DetectedReminder>()
        try {
             // Phase 2: Detect recurrence from the full text (applied to all reminders found)
             val recurrence = detectRecurrence(text)

             // Helper to build DetectedReminder from a timestamp and matched snippet
             fun buildReminder(timestamp: Long, snippet: String): DetectedReminder {
                 return DetectedReminder(
                     id = UUID.randomUUID().toString(),
                     title = generateReminderTitle(snippet, noteTitle),
                     description = generateReminderDescription(snippet, text),
                     extractedText = snippet,
                     reminderDateTime = timestamp,
                     confidence = if (recurrence != null) 0.85f else 0.7f,
                     entityType = "RegexFallback",
                     originalNoteTitle = noteTitle,
                     detectedRecurrence = recurrence
                 )
             }

            // Pattern: numeric minutes in English/Hinglish (e.g., "5 min", "5 mins", "5 minm", "5 min mein", "5 min mai")
            val minuteVariants = Regex("\\b(\\d{1,3})\\s*(?:min|mins|minm|minute|minutes)\\s*(?:mai|mein)?\\b", RegexOption.IGNORE_CASE)
            minuteVariants.findAll(text).forEach { m ->
                val n = m.groupValues[1].toIntOrNull() ?: return@forEach
                val cal = Calendar.getInstance()
                cal.add(Calendar.MINUTE, n)
                cal.set(Calendar.SECOND, 0)
                // Only add future times
                if (cal.timeInMillis > System.currentTimeMillis()) reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }

             // Pattern: (today|tomorrow|tonight)( at)? TIME?
             val relativePattern = Regex("\\b(today|tomorrow|tonight)\\b(?:\\s+at)?\\s*(\\d{1,2}(:\\d{2})?\\s?(?:am|pm)?)?",
                 RegexOption.IGNORE_CASE)
            // Check once whether the full text already has a relative-duration expression
            // ("in X min/hours" or "N min"). If so, bare day words are context only — skip them.
            val textHasRelativeDuration = Regex(
                "\\bin\\s+\\d+\\s*(?:min|mins|minute|minutes|hour|hours)\\b|\\b\\d+\\s*(?:min|mins|minm|minute|minutes)\\s*(?:mai|mein)?\\b",
                RegexOption.IGNORE_CASE
            ).containsMatchIn(text)
            relativePattern.findAll(text).forEach { m ->
                val whenWord = m.groupValues[1].lowercase()
                val timePart = m.groupValues.getOrNull(2)
                // If no explicit time was captured and the text already has a "in X min/hours"
                // duration expression, this day word is only providing event context — skip it.
                if (timePart.isNullOrBlank() && textHasRelativeDuration) return@forEach
                val cal = Calendar.getInstance()
                when (whenWord) {
                    "today", "tonight" -> { /* keep today */ }
                    "tomorrow" -> cal.add(Calendar.DATE, 1)
                }

                // default time for 'tonight' = 20:00, for others if missing = 09:00
                var hour = 9; var minute = 0
                if (whenWord == "tonight") { hour = 20 }

                if (!timePart.isNullOrBlank()) {
                    val t = parseTimeStringToHourMinute(timePart)
                    if (t != null) { hour = t.first; minute = t.second }
                }

                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, minute)
                cal.set(Calendar.SECOND, 0)
                val ts = cal.timeInMillis
                if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
            }

            // Pattern: Hinglish relative day (kal/aaj/parso) + optional time
            // Handles: "kal 5 baje", "aaj subah", "kal morning", "kal 8 bje subah"
            val hinglishDayPattern = Regex(
                "\\b(kal|aaj|parso)\\b(?:\\s+(?:ko|ke))?(?:\\s+(\\d{1,2})\\s*(?:baje|bje|bjey|bajke))?(?:\\s*(?:subah|subh|morning|shaam|evening|raat|night|dopahar|afternoon))?",
                RegexOption.IGNORE_CASE
            )
            hinglishDayPattern.findAll(text).forEach { m ->
                val whenWord = m.groupValues[1].lowercase()
                val hourStr = m.groupValues.getOrNull(2)
                val cal = Calendar.getInstance()
                when (whenWord) {
                    "kal" -> cal.add(Calendar.DATE, 1)
                    "parso" -> cal.add(Calendar.DATE, 2)
                    "aaj" -> { /* today */ }
                }

                // Try extracting hour from "N baje/bje" pattern
                var hour = 9
                val minute = 0
                if (!hourStr.isNullOrBlank()) {
                    val h = hourStr.toIntOrNull()
                    if (h != null && h in 1..12) {
                        // Determine AM/PM from context: subah/morning = AM, shaam/evening/raat/night = PM
                        val fullMatch = m.value.lowercase()
                        hour = if (fullMatch.contains("subah") || fullMatch.contains("subh") || fullMatch.contains("morning")) {
                            if (h == 12) 0 else h
                        } else if (fullMatch.contains("shaam") || fullMatch.contains("evening") || fullMatch.contains("raat") || fullMatch.contains("night")) {
                            if (h == 12) 12 else h + 12
                        } else {
                            // Ambiguous — if <= 6, assume PM; if > 6, assume AM (common Indian usage for daily tasks)
                            if (h in 1..6) h + 12 else h
                        }
                    }
                } else {
                    // No explicit time — check for time-of-day words in wider context
                    val fullMatch = m.value.lowercase()
                    hour = when {
                        fullMatch.contains("subah") || fullMatch.contains("subh") || fullMatch.contains("morning") -> 7
                        fullMatch.contains("dopahar") || fullMatch.contains("afternoon") -> 14
                        fullMatch.contains("shaam") || fullMatch.contains("evening") -> 18
                        fullMatch.contains("raat") || fullMatch.contains("night") -> 21
                        else -> 9 // default
                    }
                }

                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, minute)
                cal.set(Calendar.SECOND, 0)
                val ts = cal.timeInMillis
                if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
            }

            // Pattern: N baje/bje/bjey (standalone Hinglish o'clock without day context)
            // Handles: "5 baje", "5 bje subah", "8 baje shaam"
            val bajePattern = Regex(
                "\\b(\\d{1,2})\\s*(?:baje|bje|bjey|bajke)\\s*((?:subah|subh|morning|shaam|evening|raat|night|dopahar|afternoon))?",
                RegexOption.IGNORE_CASE
            )
            bajePattern.findAll(text).forEach { m ->
                val hourNum = m.groupValues[1].toIntOrNull() ?: return@forEach
                val timeOfDay = m.groupValues.getOrNull(2)?.lowercase()?.takeIf { it.isNotBlank() }
                if (hourNum !in 1..12) return@forEach

                val hour = when {
                    timeOfDay != null && (timeOfDay.startsWith("sub") || timeOfDay == "morning") -> {
                        if (hourNum == 12) 0 else hourNum
                    }
                    timeOfDay != null && (timeOfDay.startsWith("sha") || timeOfDay == "evening" || timeOfDay.startsWith("raa") || timeOfDay == "night") -> {
                        if (hourNum == 12) 12 else hourNum + 12
                    }
                    else -> {
                        // Check nearby context for subah/shaam
                        val contextLower = text.lowercase()
                        if (contextLower.contains("subah") || contextLower.contains("subh") || contextLower.contains("morning")) {
                            if (hourNum == 12) 0 else hourNum
                        } else if (contextLower.contains("shaam") || contextLower.contains("evening") || contextLower.contains("raat") || contextLower.contains("night")) {
                            if (hourNum == 12) 12 else hourNum + 12
                        } else {
                            if (hourNum in 1..6) hourNum + 12 else hourNum
                        }
                    }
                }

                val cal = Calendar.getInstance()
                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, 0)
                cal.set(Calendar.SECOND, 0)
                // If time already passed today, schedule for tomorrow
                if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.DATE, 1)
                reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }

            // Pattern: Weekday (next)? (at)? TIME?
            val weekdays = listOf("monday","tuesday","wednesday","thursday","friday","saturday","sunday")
            val weekdayPattern = Regex("\\b(?:next\\s+)?(${weekdays.joinToString("|")})\\b(?:\\s+at)?\\s*(\\d{1,2}(:\\d{2})?\\s?(?:am|pm)?)?",
                RegexOption.IGNORE_CASE)
            weekdayPattern.findAll(text).forEach { m ->
                val dayName = m.groupValues[1].lowercase()
                val timePart = m.groupValues.getOrNull(2)
                val targetDow = weekdays.indexOf(dayName) + 1 // Calendar.SUNDAY=1
                val cal = Calendar.getInstance()
                val todayDow = cal.get(Calendar.DAY_OF_WEEK)
                var daysAhead = (targetDow - todayDow + 7) % 7
                if (daysAhead == 0) daysAhead = 7 // schedule next week if same day mentioned
                cal.add(Calendar.DATE, daysAhead)

                var hour = 9; var minute = 0
                if (!timePart.isNullOrBlank()) {
                    val t = parseTimeStringToHourMinute(timePart)
                    if (t != null) { hour = t.first; minute = t.second }
                }

                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, minute)
                cal.set(Calendar.SECOND, 0)
                val ts = cal.timeInMillis
                if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
            }

            // Pattern: explicit time without date -> schedule next occurrence of that time
            val timeOnlyPattern = Regex("\\b(\\d{1,2}(:\\d{2})?\\s?(?:am|pm))\\b", RegexOption.IGNORE_CASE)
            timeOnlyPattern.findAll(text).forEach { m ->
                val timePart = m.groupValues[1]
                val parsed = parseTimeStringToHourMinute(timePart)
                if (parsed != null) {
                    val cal = Calendar.getInstance()
                    cal.set(Calendar.HOUR_OF_DAY, parsed.first)
                    cal.set(Calendar.MINUTE, parsed.second)
                    cal.set(Calendar.SECOND, 0)
                    if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.DATE, 1)
                    val ts = cal.timeInMillis
                    reminders.add(buildReminder(ts, m.value.trim()))
                }
            }

            // Pattern: 'at 5' or 'at 17' without am/pm -> schedule next occurrence of that hour
            val atHourPattern = Regex("\\bat\\s+(\\d{1,2})(?::(\\d{2}))?\\b(?!\\s*(?:am|pm))", RegexOption.IGNORE_CASE)
            atHourPattern.findAll(text).forEach { m ->
                val hourStr = m.groupValues[1]
                val minStr = m.groupValues.getOrNull(2)
                val hour = hourStr.toIntOrNull() ?: return@forEach
                val minute = minStr?.toIntOrNull() ?: 0
                if (hour in 0..23 && minute in 0..59) {
                    val cal = Calendar.getInstance()
                    cal.set(Calendar.HOUR_OF_DAY, hour)
                    cal.set(Calendar.MINUTE, minute)
                    cal.set(Calendar.SECOND, 0)
                    if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.DATE, 1)
                    reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
                }
            }

            // Pattern: 'in X hours' or 'in X minutes'
            val inHoursPattern = Regex("\\bin\\s+(\\d{1,3})\\s+hours?\\b", RegexOption.IGNORE_CASE)
            inHoursPattern.findAll(text).forEach { m ->
                val n = m.groupValues[1].toIntOrNull() ?: return@forEach
                val cal = Calendar.getInstance()
                cal.add(Calendar.HOUR_OF_DAY, n)
                cal.set(Calendar.SECOND, 0)
                reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }
            val inMinutesPattern = Regex("\\bin\\s+(\\d{1,3})\\s+minutes?\\b", RegexOption.IGNORE_CASE)
            inMinutesPattern.findAll(text).forEach { m ->
                val n = m.groupValues[1].toIntOrNull() ?: return@forEach
                val cal = Calendar.getInstance()
                cal.add(Calendar.MINUTE, n)
                cal.set(Calendar.SECOND, 0)
                reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }

            // Pattern: numeric date like 05/09 or 5-9 or 2025-09-05 -> try MM/DD or DD/MM where reasonable
            val numericDatePattern = Regex("\\b(\\d{1,4})[/-](\\d{1,2})(?:[/-](\\d{2,4}))?\\b")
            numericDatePattern.findAll(text).forEach { m ->
                if (!isLikelyNumericDateMatch(text, m)) return@forEach
                try {
                    val p1 = m.groupValues[1].toIntOrNull() ?: return@forEach
                    val p2 = m.groupValues[2].toIntOrNull() ?: return@forEach
                    val p3 = m.groupValues.getOrNull(3)?.toIntOrNull()
                    val cal = Calendar.getInstance()
                    if (p1 > 31) {
                        // treat as year-month-day or year-month-day
                        // p1 = year, p2 = month
                        val year = p1
                        val month = (p2 - 1).coerceIn(0,11)
                        val day = p3 ?: cal.get(Calendar.DAY_OF_MONTH)
                        cal.set(Calendar.YEAR, year)
                        cal.set(Calendar.MONTH, month)
                        cal.set(Calendar.DAY_OF_MONTH, day)
                    } else {
                        // ambiguous: assume MM/DD if first <=12, else DD/MM
                        val month = if (p1 in 1..12) p1 - 1 else p2 - 1
                        val day = if (p1 in 1..12) p2 else p1
                        cal.set(Calendar.MONTH, month.coerceIn(0,11))
                        cal.set(Calendar.DAY_OF_MONTH, day.coerceIn(1,31))
                        // if year present, set it, else default this year, roll over if passed
                        if (p3 != null) {
                            val year = if (p3 < 100) 2000 + p3 else p3
                            cal.set(Calendar.YEAR, year)
                        }
                        if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.YEAR, 1)
                    }
                    // default time
                    cal.set(Calendar.HOUR_OF_DAY, 9)
                    cal.set(Calendar.MINUTE, 0)
                    cal.set(Calendar.SECOND, 0)
                    if (cal.timeInMillis > System.currentTimeMillis()) reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
                } catch (_: Exception) {
                    // ignore
                }
            }

             // Pattern: Month name + day (e.g., Jan 5 or January 5)
             val monthNames = mapOf(
                 "jan" to 0, "feb" to 1, "mar" to 2, "apr" to 3, "may" to 4, "jun" to 5,
                 "jul" to 6, "aug" to 7, "sep" to 8, "oct" to 9, "nov" to 10, "dec" to 11
             )
             val monthPattern = Regex("\\b(jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec|january|february|march|april|may|june|july|august|september|october|november|december)\\s+(\\d{1,2})(?:\\s+at\\s+(\\d{1,2}(:\\d{2})?\\s?(?:am|pm)?))?",
                 RegexOption.IGNORE_CASE)
             monthPattern.findAll(text).forEach { m ->
                 val mon = m.groupValues[1].lowercase().take(3)
                 val day = m.groupValues[2].toIntOrNull() ?: return@forEach
                 val timePart = m.groupValues.getOrNull(3)
                 val cal = Calendar.getInstance()
                 val monthIdx = monthNames[mon] ?: return@forEach
                 cal.set(Calendar.MONTH, monthIdx)
                 cal.set(Calendar.DAY_OF_MONTH, day)
                 // if month-day already passed this year, set next year
                 if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.YEAR, 1)

                 var hour = 9; var minute = 0
                 if (!timePart.isNullOrBlank()) {
                     val t = parseTimeStringToHourMinute(timePart)
                     if (t != null) { hour = t.first; minute = t.second }
                 }
                 cal.set(Calendar.HOUR_OF_DAY, hour)
                 cal.set(Calendar.MINUTE, minute)
                 cal.set(Calendar.SECOND, 0)
                 val ts = cal.timeInMillis
                 if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
             }

        } catch (ex: Exception) {
            Log.e(TAG, "❌ Error in regexFallbackForReminders", ex)
        }

        return reminders.distinctBy { it.reminderDateTime }.sortedBy { it.reminderDateTime }
    }

    private fun isLikelyNumericDateMatch(text: String, match: MatchResult): Boolean {
        val first = match.groupValues[1].toIntOrNull() ?: return false
        val second = match.groupValues[2].toIntOrNull() ?: return false
        val third = match.groupValues.getOrNull(3).orEmpty()

        if (third.isNotBlank()) return true

        val contextStart = (match.range.first - 20).coerceAtLeast(0)
        val contextEnd = (match.range.last + 21).coerceAtMost(text.length)
        val context = text.substring(contextStart, contextEnd)

        val dateCuePattern = Regex(
            "\\b(?:on|by|due|before|after|until|till|from|starting|schedule(?:d)?|appointment|meeting|deadline|birthday|anniversary|flight|exam|doctor|dentist|visit|renew|renewal|submit|pay|bill)\\b",
            RegexOption.IGNORE_CASE
        )

        return when {
            first > 12 || second > 12 -> true
            else -> dateCuePattern.containsMatchIn(context)
        }
    }

    // Parse time strings like "10am", "10:30 pm", "7:15PM" into hour and minute
    private fun parseTimeStringToHourMinute(timeStr: String): Pair<Int, Int>? {
        try {
            var s = timeStr.lowercase().trim()
            val ampm = when {
                s.endsWith("am") -> "am"
                s.endsWith("pm") -> "pm"
                else -> null
            }
            s = s.replace("am", "").replace("pm", "").trim()
            val parts = s.split(":")
            var hour = parts[0].toIntOrNull() ?: return null
            val minute = if (parts.size > 1) parts[1].toIntOrNull() ?: 0 else 0
            if (ampm != null) {
                if (ampm == "pm" && hour < 12) hour += 12
                if (ampm == "am" && hour == 12) hour = 0
            }
            if (hour in 0..23 && minute in 0..59) return Pair(hour, minute)
        } catch (_: Exception) {
            // ignore
        }
        return null
    }

    /**
     * Phase 2: Detect recurrence patterns from text.
     * Recognizes English and Hinglish phrases like "every day", "daily", "weekly",
     * "every Monday", "har hafte", "roz", etc.
     *
     * @return DetectedRecurrence if a recurrence pattern is found with confidence >= 0.7, null otherwise
     */
    fun detectRecurrence(text: String): DetectedRecurrence? {

        // "every day" / "daily" / "roz" / "har din" / "har roz"
        val dailyPatterns = listOf(
            Regex("\\bevery\\s+day\\b", RegexOption.IGNORE_CASE),
            Regex("\\bdaily\\b", RegexOption.IGNORE_CASE),
            Regex("\\broz\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+din\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+roz\\b", RegexOption.IGNORE_CASE),
            Regex("\\bdaily\\s+at\\b", RegexOption.IGNORE_CASE),
            Regex("\\beveryday\\b", RegexOption.IGNORE_CASE)
        )
        if (dailyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "DAILY", interval = 1)
        }

        // "every N days"
        val everyNDays = Regex("\\bevery\\s+(\\d+)\\s+days?\\b", RegexOption.IGNORE_CASE)
        everyNDays.find(text)?.let { m ->
            val n = m.groupValues[1].toIntOrNull() ?: 1
            return DetectedRecurrence(type = "DAILY", interval = n)
        }

        // Specific weekday recurrence: "every Monday", "every mon/wed/fri", "har Monday"
        val weekdays = mapOf(
            "sunday" to 1, "sun" to 1,
            "monday" to 2, "mon" to 2,
            "tuesday" to 3, "tue" to 3,
            "wednesday" to 4, "wed" to 4,
            "thursday" to 5, "thu" to 5,
            "friday" to 6, "fri" to 6,
            "saturday" to 7, "sat" to 7
        )
        val weekdayNames = weekdays.keys.joinToString("|")
        val everyWeekdayPattern = Regex(
            "\\b(?:every|har)\\s+($weekdayNames)(?:\\s*(?:,|and|aur|&)\\s*($weekdayNames))*\\b",
            RegexOption.IGNORE_CASE
        )
        everyWeekdayPattern.find(text)?.let { m ->
            // Extract all mentioned days from the matched region
            val matchedText = m.value.lowercase()
            val days = weekdays.filter { matchedText.contains(it.key) }.values.toSortedSet()
            if (days.isNotEmpty()) {
                return DetectedRecurrence(
                    type = "WEEKLY",
                    interval = 1,
                    daysOfWeek = days.joinToString(",")
                )
            }
        }

        // "weekdays" / "weekday" / "on weekdays"
        val weekdaysPattern = Regex("\\b(?:every\\s+)?weekdays?\\b", RegexOption.IGNORE_CASE)
        if (weekdaysPattern.containsMatchIn(text)) {
            return DetectedRecurrence(type = "WEEKLY", interval = 1, daysOfWeek = "2,3,4,5,6") // Mon-Fri
        }

        // "weekly" / "every week" / "har hafte" / "har hafta"
        val weeklyPatterns = listOf(
            Regex("\\bweekly\\b", RegexOption.IGNORE_CASE),
            Regex("\\bevery\\s+week\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+haft[ea]\\b", RegexOption.IGNORE_CASE)
        )
        if (weeklyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "WEEKLY", interval = 1)
        }

        // "every N weeks"
        val everyNWeeks = Regex("\\bevery\\s+(\\d+)\\s+weeks?\\b", RegexOption.IGNORE_CASE)
        everyNWeeks.find(text)?.let { m ->
            val n = m.groupValues[1].toIntOrNull() ?: 1
            return DetectedRecurrence(type = "WEEKLY", interval = n)
        }

        // "monthly" / "every month" / "har mahine" / "har mahiney"
        val monthlyPatterns = listOf(
            Regex("\\bmonthly\\b", RegexOption.IGNORE_CASE),
            Regex("\\bevery\\s+month\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+mahin[ey]+\\b", RegexOption.IGNORE_CASE)
        )
        if (monthlyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "MONTHLY", interval = 1)
        }

        // "every N months"
        val everyNMonths = Regex("\\bevery\\s+(\\d+)\\s+months?\\b", RegexOption.IGNORE_CASE)
        everyNMonths.find(text)?.let { m ->
            val n = m.groupValues[1].toIntOrNull() ?: 1
            return DetectedRecurrence(type = "MONTHLY", interval = n)
        }

        // "yearly" / "every year" / "annually" / "har saal"
        val yearlyPatterns = listOf(
            Regex("\\byearly\\b", RegexOption.IGNORE_CASE),
            Regex("\\bevery\\s+year\\b", RegexOption.IGNORE_CASE),
            Regex("\\bannually\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+saal\\b", RegexOption.IGNORE_CASE)
        )
        if (yearlyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "YEARLY", interval = 1)
        }

        return null
    }

}

/**
 * Data class representing a detected reminder
 */
data class DetectedReminder(
    val id: String,
    val title: String,
    val description: String,
    val extractedText: String,
    val reminderDateTime: Long,
    val confidence: Float,
    val entityType: String,
    val originalNoteTitle: String,
    val isConfirmed: Boolean = false,
    // Phase 2: Detected recurrence info from AI
    val detectedRecurrence: DetectedRecurrence? = null
)

/**
 * Phase 2: Data class representing detected recurrence from text analysis.
 * Returned alongside a DetectedReminder when patterns like "every day", "daily", "weekly" etc. are found.
 */
data class DetectedRecurrence(
    val type: String,       // RecurrenceType constant: DAILY, WEEKLY, MONTHLY, YEARLY
    val interval: Int = 1,  // e.g., "every 2 weeks" → 2
    val daysOfWeek: String? = null  // CSV for specific days, e.g. "2,3,4,5,6" for weekdays
)

package com.amvarpvtltd.swiftNote.ai

import android.annotation.SuppressLint
import android.content.Context
import android.util.Log
import com.google.mlkit.nl.entityextraction.DateTimeEntity
import com.google.mlkit.nl.entityextraction.EntityAnnotation
import com.google.mlkit.nl.entityextraction.EntityExtraction
import com.google.mlkit.nl.entityextraction.EntityExtractor
import com.google.mlkit.nl.entityextraction.EntityExtractorOptions
import com.amvarpvtltd.swiftNote.richtext.RichTextBridge
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Date
import java.util.Locale
import java.util.UUID
import kotlin.coroutines.resume

class SmartReminderAI(private val context: Context) {
    private val TAG = "SmartReminderAI"

    private lateinit var entityExtractor: EntityExtractor
    private var isInitialized = false

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: SmartReminderAI? = null

        fun getInstance(context: Context): SmartReminderAI {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: SmartReminderAI(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    /**
     * Initialize ML Kit Entity Extractor
     */
    suspend fun initialize(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            suspendCancellableCoroutine<Result<String>> { continuation ->
                val options = EntityExtractorOptions.Builder(EntityExtractorOptions.ENGLISH)
                    .build()

                entityExtractor = EntityExtraction.getClient(options)

                entityExtractor.downloadModelIfNeeded()
                    .addOnSuccessListener {
                        Log.d(TAG, "✅ ML Kit Entity Extractor initialized successfully")
                        isInitialized = true
                        continuation.resume(Result.success("AI initialized successfully"))
                    }
                    .addOnFailureListener { exception ->
                        Log.e(TAG, "❌ Failed to initialize ML Kit Entity Extractor", exception)
                        continuation.resume(Result.failure(exception))
                    }

                continuation.invokeOnCancellation {
                    Log.d(TAG, " Entity Extractor initialization cancelled")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error initializing Entity Extractor", e)
            Result.failure(e)
        }
    }

    /**
     * Analyze text for date/time entities and return detected reminders.
     *
     * Pipeline (smartest → fastest):
     *   1. AI (cloud, ~1-2s) — tried first if available (user has API key, Gemini or Groq)
     *   2. ML Kit Entity Extraction (on-device, instant) — fallback if AI fails/unavailable
     *   3. Regex fallback (on-device, instant, handles Hinglish) — last resort
     */
    suspend fun analyzeTextForReminders(
        text: String,
        noteTitle: String = "Untitled"
    ): Result<List<DetectedReminder>> = withContext(Dispatchers.IO) {
        // ───────────────────────────────────────────────────────────────
        // LLM-first path (multilingual).
        // When the user has configured an API key, bypass the English/Hinglish-only
        // ReminderIntentAnalyzer keyword gate and send the raw text directly to the
        // LLM. The LLM can natively understand any language it supports (Spanish,
        // French, German, Japanese, Arabic, Chinese, Portuguese, Russian, Bengali,
        // Tamil, Marathi, Gujarati, Punjabi, etc.) and will respond with
        // hasReminder=false when no intent is present, so this is safe.
        // ───────────────────────────────────────────────────────────────
        val geminiAvailable = try {
            GeminiReminderParser.getInstance(context).isAvailable()
        } catch (_: Exception) { false }

        if (geminiAvailable) {
            // Defensive HTML strip in case caller passed rich-text content.
            val plain = try { RichTextBridge.stripHtmlToPlainText(text) } catch (_: Exception) { text }
            val llmInput = plain.trim().ifBlank { text.trim() }

            if (llmInput.isNotBlank()) {
                Log.d(TAG, " AI available — routing text directly to LLM (multilingual mode)")
                val geminiResults = tryGeminiParsing(llmInput, noteTitle)
                if (geminiResults.isNotEmpty()) {
                    Log.d(TAG, "AI returned ${geminiResults.size} reminder(s) - using AI response")
                    return@withContext Result.success(geminiResults)
                }
                Log.d(TAG, "AI returned no results - falling back to on-device methods")
            }
        }

        // ───────────────────────────────────────────────────────────────
        // On-device fallback (ML Kit + regex) — keyword-gated, English/Hinglish only.
        // ───────────────────────────────────────────────────────────────
        val analysisText = ReminderIntentAnalyzer.buildAnalysisText(
            noteBody = text,
            noteTitle = noteTitle
        )

        if (analysisText.isNullOrBlank()) {
            Log.d(TAG, "No sentence-level reminder intent found, skipping analysis")
            return@withContext Result.success(emptyList())
        }

        Log.d(TAG, "Analyzing reminder-focused text: ${analysisText.take(100)}...")


        if (!isInitialized) {
            Log.w(TAG, "Entity Extractor not initialized, attempting to initialize...")
            val initResult = initialize()
            if (initResult.isFailure) {
                Log.w(TAG, "ML Kit init failed, using regex fallback: ${initResult.exceptionOrNull()?.message}")
                val regexResults = try {
                    regexFallbackForReminders(analysisText, noteTitle)
                } catch (_: Exception) {
                    emptyList()
                }
                return@withContext Result.success(regexResults)
            }
        }

        return@withContext try {
            suspendCancellableCoroutine<Result<List<DetectedReminder>>> { continuation ->
                entityExtractor.annotate(analysisText)
                    .addOnSuccessListener { entityAnnotations ->
                        val detectedReminders = processEntityAnnotations(
                            entityAnnotations,
                            analysisText,
                            noteTitle
                        )

                        val finalResults = detectedReminders.ifEmpty {
                            val fallback = regexFallbackForReminders(analysisText, noteTitle)
                            if (fallback.isNotEmpty()) {
                                Log.d(TAG, "Regex fallback detected ${fallback.size} reminder(s)")
                            }
                            fallback
                        }

                        Log.d(TAG, "Found ${finalResults.size} potential reminders (on-device)")
                        continuation.resume(Result.success(finalResults))
                    }
                    .addOnFailureListener { exception ->
                        Log.e(TAG, "ML Kit annotation failed, using regex fallback", exception)

                        val fallback = regexFallbackForReminders(analysisText, noteTitle)
                        if (fallback.isNotEmpty()) {
                            Log.d(TAG, "Regex fallback detected ${fallback.size} reminder(s) after ML Kit failure")
                        }
                        continuation.resume(Result.success(fallback))
                    }

                continuation.invokeOnCancellation {
                    Log.d(TAG, "Text analysis cancelled")
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error in analyzeTextForReminders - falling back to regex", e)
            val regexResults = try {
                regexFallbackForReminders(analysisText, noteTitle)
            } catch (_: Exception) {
                emptyList()
            }
            return@withContext Result.success(regexResults)
        }
    }

    /**
     * Try parsing with AI (Gemini or Groq). Returns empty list on failure (never throws).
     * This is the intelligent fallback for when on-device methods can't parse the text.
     */
    private suspend fun tryGeminiParsing(text: String, noteTitle: String): List<DetectedReminder> {
        return try {
            val gemini = GeminiReminderParser.getInstance(context)
            val parsed = gemini.parseReminderIntent(text, noteTitle)
            if (parsed != null) {
                val results = gemini.toDetectedReminders(parsed, noteTitle)
                Log.d(TAG, " AI detected ${results.size} reminder(s)")
                results
            } else {
                Log.d(TAG, " AI found no reminder intent")
                emptyList()
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ AI parsing failed silently: ${e.message}")
            emptyList()
        }
    }

    /**
     * Explicitly analyze text using AI (bypasses ML Kit + regex).
     * Use this when:
     * - User taps "Analyze with AI" button
     * - On-device methods returned no results but user insists there's a reminder
     * - Text is in a language that regex/ML Kit can't handle well
     *
     * @return Result with list of detected reminders, or failure if AI is unavailable
     */
    suspend fun analyzeWithGemini(
        text: String,
        noteTitle: String = "Untitled"
    ): Result<List<DetectedReminder>> = withContext(Dispatchers.IO) {
        return@withContext try {
            val gemini = GeminiReminderParser.getInstance(context)
            val parsed = gemini.parseReminderIntent(text, noteTitle)
            if (parsed != null) {
                val results = gemini.toDetectedReminders(parsed, noteTitle)
                Log.d(TAG, " AI explicit analysis: ${results.size} reminder(s)")
                Result.success(results)
            } else {
                Result.success(emptyList())
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Gemini explicit analysis failed: ${e.message}", e)
            Result.failure(e)
        }
    }

    /**
     * Process ML Kit entity annotations to extract date/time information
     */
    private fun processEntityAnnotations(
        annotations: List<EntityAnnotation>,
        originalText: String,
        noteTitle: String
    ): List<DetectedReminder> {
        val reminders = mutableListOf<DetectedReminder>()
        val currentTime = System.currentTimeMillis()

        annotations.forEach { annotation ->
            annotation.entities.forEach { entity ->
                when (entity) {
                    is DateTimeEntity -> {
                        val reminderDateTime = processDateTimeEntity(entity)

                        if (reminderDateTime != null && reminderDateTime > currentTime) {
                            val extractedText = originalText.substring(
                                annotation.start,
                                annotation.end.coerceAtMost(originalText.length)
                            )

                            val reminder = DetectedReminder(
                                id = UUID.randomUUID().toString(),
                                title = generateReminderTitle(extractedText, noteTitle),
                                description = generateReminderDescription(extractedText, originalText),
                                extractedText = extractedText,
                                reminderDateTime = reminderDateTime,
                                confidence = calculateConfidence(entity, extractedText),
                                entityType = "DateTime",
                                originalNoteTitle = noteTitle
                            )

                            reminders.add(reminder)
                            Log.d(TAG, " Detected reminder: ${reminder.title} at ${formatDateTime(reminderDateTime)}")
                        }
                    }
                }
            }
        }

        return reminders.distinctBy { it.reminderDateTime }.sortedBy { it.reminderDateTime }
    }
    private fun processDateTimeEntity(entity: DateTimeEntity): Long? {
        return try {
            val calendar = Calendar.getInstance()

            when (entity.dateTimeGranularity) {
                DateTimeEntity.GRANULARITY_DAY -> {
                    val timestamp = entity.timestampMillis
                    calendar.timeInMillis = timestamp
                    // Set to 9 AM if only date is specified
                    calendar.set(Calendar.HOUR_OF_DAY, 9)
                    calendar.set(Calendar.MINUTE, 0)
                    calendar.set(Calendar.SECOND, 0)
                    calendar.timeInMillis
                }
                DateTimeEntity.GRANULARITY_HOUR -> entity.timestampMillis
                DateTimeEntity.GRANULARITY_MINUTE -> entity.timestampMillis
                else -> entity.timestampMillis
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error processing DateTimeEntity", e)
            null
        }
    }

    /**
     * Generate a meaningful reminder title
     */
    private fun generateReminderTitle(extractedText: String, noteTitle: String): String {
        return when {
            extractedText.contains("appointment", ignoreCase = true) -> " Appointment Reminder"
            extractedText.contains("meeting", ignoreCase = true) -> " Meeting Reminder"
            extractedText.contains("call", ignoreCase = true) -> " Call Reminder"
            extractedText.contains("deadline", ignoreCase = true) -> "⏰ Deadline Reminder"
            extractedText.contains("reminder", ignoreCase = true) -> " Personal Reminder"
            noteTitle.isNotBlank() && noteTitle != "Untitled" -> " $noteTitle"
            else -> " Smart Reminder"
        }
    }

    /**
     * Generate reminder description from context
     */
    private fun generateReminderDescription(extractedText: String, fullText: String): String {
        // Find the sentence containing the extracted text
        val sentences = fullText.split(Regex("[.!?]+"))
        val relevantSentence = sentences.find { it.contains(extractedText, ignoreCase = true) }

        return relevantSentence?.trim()?.takeIf { it.isNotBlank() }
            ?: extractedText.trim().takeIf { it.isNotBlank() }
            ?: "Reminder from your note"
    }

    /**
     * Format date/time for display
     */
    private fun formatDateTime(timestamp: Long): String {
        val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
        return formatter.format(Date(timestamp))
    }

    /**
     * Check if text contains potential reminder keywords
     */
    fun hasReminderKeywords(text: String): Boolean {
        return ReminderIntentAnalyzer.hasReminderIntent(noteBody = text)
    }

    /**
     * Calculate confidence for the detected reminder based on entity characteristics
     */
    private fun calculateConfidence(entity: DateTimeEntity, extractedText: String): Float {

        var confidence = 0.7f // Base confidence

        // Higher confidence for more specific time granularity
        when (entity.dateTimeGranularity) {
            DateTimeEntity.GRANULARITY_MINUTE -> confidence += 0.2f
            DateTimeEntity.GRANULARITY_HOUR -> confidence += 0.15f
            DateTimeEntity.GRANULARITY_DAY -> confidence += 0.1f
            else -> confidence += 0.05f
        }

        // Higher confidence for explicit reminder keywords
        val reminderKeywords = listOf("remind", "appointment", "meeting", "deadline", "alarm")
        if (reminderKeywords.any { extractedText.contains(it, ignoreCase = true) }) {
            confidence += 0.1f
        }

        // Ensure confidence is between 0.0 and 1.0
        return confidence.coerceIn(0.0f, 1.0f)
    }

    private fun regexFallbackForReminders(text: String, noteTitle: String): List<DetectedReminder> {
        val reminders = mutableListOf<DetectedReminder>()
        try {
             // Phase 2: Detect recurrence from the full text (applied to all reminders found)
             val recurrence = detectRecurrence(text)

             // Helper to build DetectedReminder from a timestamp and matched snippet
             fun buildReminder(timestamp: Long, snippet: String): DetectedReminder {
                 return DetectedReminder(
                     id = UUID.randomUUID().toString(),
                     title = generateReminderTitle(snippet, noteTitle),
                     description = generateReminderDescription(snippet, text),
                     extractedText = snippet,
                     reminderDateTime = timestamp,
                     confidence = if (recurrence != null) 0.85f else 0.7f,
                     entityType = "RegexFallback",
                     originalNoteTitle = noteTitle,
                     detectedRecurrence = recurrence
                 )
             }

            // Pattern: numeric minutes in English/Hinglish (e.g., "5 min", "5 mins", "5 minm", "5 min mein", "5 min mai")
            val minuteVariants = Regex("\\b(\\d{1,3})\\s*(?:min|mins|minm|minute|minutes)\\s*(?:mai|mein)?\\b", RegexOption.IGNORE_CASE)
            minuteVariants.findAll(text).forEach { m ->
                val n = m.groupValues[1].toIntOrNull() ?: return@forEach
                val cal = Calendar.getInstance()
                cal.add(Calendar.MINUTE, n)
                cal.set(Calendar.SECOND, 0)
                // Only add future times
                if (cal.timeInMillis > System.currentTimeMillis()) reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }

             // Pattern: (today|tomorrow|tonight)( at)? TIME?
             val relativePattern = Regex("\\b(today|tomorrow|tonight)\\b(?:\\s+at)?\\s*(\\d{1,2}(:\\d{2})?\\s?(?:am|pm)?)?",
                 RegexOption.IGNORE_CASE)
            // Check once whether the full text already has a relative-duration expression
            // ("in X min/hours" or "N min"). If so, bare day words are context only — skip them.
            val textHasRelativeDuration = Regex(
                "\\bin\\s+\\d+\\s*(?:min|mins|minute|minutes|hour|hours)\\b|\\b\\d+\\s*(?:min|mins|minm|minute|minutes)\\s*(?:mai|mein)?\\b",
                RegexOption.IGNORE_CASE
            ).containsMatchIn(text)
            relativePattern.findAll(text).forEach { m ->
                val whenWord = m.groupValues[1].lowercase()
                val timePart = m.groupValues.getOrNull(2)
                // If no explicit time was captured and the text already has a "in X min/hours"
                // duration expression, this day word is only providing event context — skip it.
                if (timePart.isNullOrBlank() && textHasRelativeDuration) return@forEach
                val cal = Calendar.getInstance()
                when (whenWord) {
                    "today", "tonight" -> { /* keep today */ }
                    "tomorrow" -> cal.add(Calendar.DATE, 1)
                }

                // default time for 'tonight' = 20:00, for others if missing = 09:00
                var hour = 9; var minute = 0
                if (whenWord == "tonight") { hour = 20 }

                if (!timePart.isNullOrBlank()) {
                    val t = parseTimeStringToHourMinute(timePart)
                    if (t != null) { hour = t.first; minute = t.second }
                }

                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, minute)
                cal.set(Calendar.SECOND, 0)
                val ts = cal.timeInMillis
                if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
            }

            // Pattern: Hinglish relative day (kal/aaj/parso) + optional time
            // Handles: "kal 5 baje", "aaj subah", "kal morning", "kal 8 bje subah"
            val hinglishDayPattern = Regex(
                "\\b(kal|aaj|parso)\\b(?:\\s+(?:ko|ke))?(?:\\s+(\\d{1,2})\\s*(?:baje|bje|bjey|bajke))?(?:\\s*(?:subah|subh|morning|shaam|evening|raat|night|dopahar|afternoon))?",
                RegexOption.IGNORE_CASE
            )
            hinglishDayPattern.findAll(text).forEach { m ->
                val whenWord = m.groupValues[1].lowercase()
                val hourStr = m.groupValues.getOrNull(2)
                val cal = Calendar.getInstance()
                when (whenWord) {
                    "kal" -> cal.add(Calendar.DATE, 1)
                    "parso" -> cal.add(Calendar.DATE, 2)
                    "aaj" -> { /* today */ }
                }

                // Try extracting hour from "N baje/bje" pattern
                var hour = 9
                val minute = 0
                if (!hourStr.isNullOrBlank()) {
                    val h = hourStr.toIntOrNull()
                    if (h != null && h in 1..12) {
                        // Determine AM/PM from context: subah/morning = AM, shaam/evening/raat/night = PM
                        val fullMatch = m.value.lowercase()
                        hour = if (fullMatch.contains("subah") || fullMatch.contains("subh") || fullMatch.contains("morning")) {
                            if (h == 12) 0 else h
                        } else if (fullMatch.contains("shaam") || fullMatch.contains("evening") || fullMatch.contains("raat") || fullMatch.contains("night")) {
                            if (h == 12) 12 else h + 12
                        } else {
                            // Ambiguous — if <= 6, assume PM; if > 6, assume AM (common Indian usage for daily tasks)
                            if (h in 1..6) h + 12 else h
                        }
                    }
                } else {
                    // No explicit time — check for time-of-day words in wider context
                    val fullMatch = m.value.lowercase()
                    hour = when {
                        fullMatch.contains("subah") || fullMatch.contains("subh") || fullMatch.contains("morning") -> 7
                        fullMatch.contains("dopahar") || fullMatch.contains("afternoon") -> 14
                        fullMatch.contains("shaam") || fullMatch.contains("evening") -> 18
                        fullMatch.contains("raat") || fullMatch.contains("night") -> 21
                        else -> 9 // default
                    }
                }

                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, minute)
                cal.set(Calendar.SECOND, 0)
                val ts = cal.timeInMillis
                if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
            }

            // Pattern: N baje/bje/bjey (standalone Hinglish o'clock without day context)
            // Handles: "5 baje", "5 bje subah", "8 baje shaam"
            val bajePattern = Regex(
                "\\b(\\d{1,2})\\s*(?:baje|bje|bjey|bajke)\\s*((?:subah|subh|morning|shaam|evening|raat|night|dopahar|afternoon))?",
                RegexOption.IGNORE_CASE
            )
            bajePattern.findAll(text).forEach { m ->
                val hourNum = m.groupValues[1].toIntOrNull() ?: return@forEach
                val timeOfDay = m.groupValues.getOrNull(2)?.lowercase()?.takeIf { it.isNotBlank() }
                if (hourNum !in 1..12) return@forEach

                val hour = when {
                    timeOfDay != null && (timeOfDay.startsWith("sub") || timeOfDay == "morning") -> {
                        if (hourNum == 12) 0 else hourNum
                    }
                    timeOfDay != null && (timeOfDay.startsWith("sha") || timeOfDay == "evening" || timeOfDay.startsWith("raa") || timeOfDay == "night") -> {
                        if (hourNum == 12) 12 else hourNum + 12
                    }
                    else -> {
                        // Check nearby context for subah/shaam
                        val contextLower = text.lowercase()
                        if (contextLower.contains("subah") || contextLower.contains("subh") || contextLower.contains("morning")) {
                            if (hourNum == 12) 0 else hourNum
                        } else if (contextLower.contains("shaam") || contextLower.contains("evening") || contextLower.contains("raat") || contextLower.contains("night")) {
                            if (hourNum == 12) 12 else hourNum + 12
                        } else {
                            if (hourNum in 1..6) hourNum + 12 else hourNum
                        }
                    }
                }

                val cal = Calendar.getInstance()
                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, 0)
                cal.set(Calendar.SECOND, 0)
                // If time already passed today, schedule for tomorrow
                if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.DATE, 1)
                reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }

            // Pattern: Weekday (next)? (at)? TIME?
            val weekdays = listOf("monday","tuesday","wednesday","thursday","friday","saturday","sunday")
            val weekdayPattern = Regex("\\b(?:next\\s+)?(${weekdays.joinToString("|")})\\b(?:\\s+at)?\\s*(\\d{1,2}(:\\d{2})?\\s?(?:am|pm)?)?",
                RegexOption.IGNORE_CASE)
            weekdayPattern.findAll(text).forEach { m ->
                val dayName = m.groupValues[1].lowercase()
                val timePart = m.groupValues.getOrNull(2)
                val targetDow = weekdays.indexOf(dayName) + 1 // Calendar.SUNDAY=1
                val cal = Calendar.getInstance()
                val todayDow = cal.get(Calendar.DAY_OF_WEEK)
                var daysAhead = (targetDow - todayDow + 7) % 7
                if (daysAhead == 0) daysAhead = 7 // schedule next week if same day mentioned
                cal.add(Calendar.DATE, daysAhead)

                var hour = 9; var minute = 0
                if (!timePart.isNullOrBlank()) {
                    val t = parseTimeStringToHourMinute(timePart)
                    if (t != null) { hour = t.first; minute = t.second }
                }

                cal.set(Calendar.HOUR_OF_DAY, hour)
                cal.set(Calendar.MINUTE, minute)
                cal.set(Calendar.SECOND, 0)
                val ts = cal.timeInMillis
                if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
            }

            // Pattern: explicit time without date -> schedule next occurrence of that time
            val timeOnlyPattern = Regex("\\b(\\d{1,2}(:\\d{2})?\\s?(?:am|pm))\\b", RegexOption.IGNORE_CASE)
            timeOnlyPattern.findAll(text).forEach { m ->
                val timePart = m.groupValues[1]
                val parsed = parseTimeStringToHourMinute(timePart)
                if (parsed != null) {
                    val cal = Calendar.getInstance()
                    cal.set(Calendar.HOUR_OF_DAY, parsed.first)
                    cal.set(Calendar.MINUTE, parsed.second)
                    cal.set(Calendar.SECOND, 0)
                    if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.DATE, 1)
                    val ts = cal.timeInMillis
                    reminders.add(buildReminder(ts, m.value.trim()))
                }
            }

            // Pattern: 'at 5' or 'at 17' without am/pm -> schedule next occurrence of that hour
            val atHourPattern = Regex("\\bat\\s+(\\d{1,2})(?::(\\d{2}))?\\b(?!\\s*(?:am|pm))", RegexOption.IGNORE_CASE)
            atHourPattern.findAll(text).forEach { m ->
                val hourStr = m.groupValues[1]
                val minStr = m.groupValues.getOrNull(2)
                val hour = hourStr.toIntOrNull() ?: return@forEach
                val minute = minStr?.toIntOrNull() ?: 0
                if (hour in 0..23 && minute in 0..59) {
                    val cal = Calendar.getInstance()
                    cal.set(Calendar.HOUR_OF_DAY, hour)
                    cal.set(Calendar.MINUTE, minute)
                    cal.set(Calendar.SECOND, 0)
                    if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.DATE, 1)
                    reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
                }
            }

            // Pattern: 'in X hours' or 'in X minutes'
            val inHoursPattern = Regex("\\bin\\s+(\\d{1,3})\\s+hours?\\b", RegexOption.IGNORE_CASE)
            inHoursPattern.findAll(text).forEach { m ->
                val n = m.groupValues[1].toIntOrNull() ?: return@forEach
                val cal = Calendar.getInstance()
                cal.add(Calendar.HOUR_OF_DAY, n)
                cal.set(Calendar.SECOND, 0)
                reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }
            val inMinutesPattern = Regex("\\bin\\s+(\\d{1,3})\\s+minutes?\\b", RegexOption.IGNORE_CASE)
            inMinutesPattern.findAll(text).forEach { m ->
                val n = m.groupValues[1].toIntOrNull() ?: return@forEach
                val cal = Calendar.getInstance()
                cal.add(Calendar.MINUTE, n)
                cal.set(Calendar.SECOND, 0)
                reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
            }

            // Pattern: numeric date like 05/09 or 5-9 or 2025-09-05 -> try MM/DD or DD/MM where reasonable
            val numericDatePattern = Regex("\\b(\\d{1,4})[/-](\\d{1,2})(?:[/-](\\d{2,4}))?\\b")
            numericDatePattern.findAll(text).forEach { m ->
                if (!isLikelyNumericDateMatch(text, m)) return@forEach
                try {
                    val p1 = m.groupValues[1].toIntOrNull() ?: return@forEach
                    val p2 = m.groupValues[2].toIntOrNull() ?: return@forEach
                    val p3 = m.groupValues.getOrNull(3)?.toIntOrNull()
                    val cal = Calendar.getInstance()
                    if (p1 > 31) {
                        // treat as year-month-day or year-month-day
                        // p1 = year, p2 = month
                        val year = p1
                        val month = (p2 - 1).coerceIn(0,11)
                        val day = p3 ?: cal.get(Calendar.DAY_OF_MONTH)
                        cal.set(Calendar.YEAR, year)
                        cal.set(Calendar.MONTH, month)
                        cal.set(Calendar.DAY_OF_MONTH, day)
                    } else {
                        // ambiguous: assume MM/DD if first <=12, else DD/MM
                        val month = if (p1 in 1..12) p1 - 1 else p2 - 1
                        val day = if (p1 in 1..12) p2 else p1
                        cal.set(Calendar.MONTH, month.coerceIn(0,11))
                        cal.set(Calendar.DAY_OF_MONTH, day.coerceIn(1,31))
                        // if year present, set it, else default this year, roll over if passed
                        if (p3 != null) {
                            val year = if (p3 < 100) 2000 + p3 else p3
                            cal.set(Calendar.YEAR, year)
                        }
                        if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.YEAR, 1)
                    }
                    // default time
                    cal.set(Calendar.HOUR_OF_DAY, 9)
                    cal.set(Calendar.MINUTE, 0)
                    cal.set(Calendar.SECOND, 0)
                    if (cal.timeInMillis > System.currentTimeMillis()) reminders.add(buildReminder(cal.timeInMillis, m.value.trim()))
                } catch (_: Exception) {
                    // ignore
                }
            }

             // Pattern: Month name + day (e.g., Jan 5 or January 5)
             val monthNames = mapOf(
                 "jan" to 0, "feb" to 1, "mar" to 2, "apr" to 3, "may" to 4, "jun" to 5,
                 "jul" to 6, "aug" to 7, "sep" to 8, "oct" to 9, "nov" to 10, "dec" to 11
             )
             val monthPattern = Regex("\\b(jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec|january|february|march|april|may|june|july|august|september|october|november|december)\\s+(\\d{1,2})(?:\\s+at\\s+(\\d{1,2}(:\\d{2})?\\s?(?:am|pm)?))?",
                 RegexOption.IGNORE_CASE)
             monthPattern.findAll(text).forEach { m ->
                 val mon = m.groupValues[1].lowercase().take(3)
                 val day = m.groupValues[2].toIntOrNull() ?: return@forEach
                 val timePart = m.groupValues.getOrNull(3)
                 val cal = Calendar.getInstance()
                 val monthIdx = monthNames[mon] ?: return@forEach
                 cal.set(Calendar.MONTH, monthIdx)
                 cal.set(Calendar.DAY_OF_MONTH, day)
                 // if month-day already passed this year, set next year
                 if (cal.timeInMillis <= System.currentTimeMillis()) cal.add(Calendar.YEAR, 1)

                 var hour = 9; var minute = 0
                 if (!timePart.isNullOrBlank()) {
                     val t = parseTimeStringToHourMinute(timePart)
                     if (t != null) { hour = t.first; minute = t.second }
                 }
                 cal.set(Calendar.HOUR_OF_DAY, hour)
                 cal.set(Calendar.MINUTE, minute)
                 cal.set(Calendar.SECOND, 0)
                 val ts = cal.timeInMillis
                 if (ts > System.currentTimeMillis()) reminders.add(buildReminder(ts, m.value.trim()))
             }

        } catch (ex: Exception) {
            Log.e(TAG, "❌ Error in regexFallbackForReminders", ex)
        }

        return reminders.distinctBy { it.reminderDateTime }.sortedBy { it.reminderDateTime }
    }

    private fun isLikelyNumericDateMatch(text: String, match: MatchResult): Boolean {
        val first = match.groupValues[1].toIntOrNull() ?: return false
        val second = match.groupValues[2].toIntOrNull() ?: return false
        val third = match.groupValues.getOrNull(3).orEmpty()

        if (third.isNotBlank()) return true

        val contextStart = (match.range.first - 20).coerceAtLeast(0)
        val contextEnd = (match.range.last + 21).coerceAtMost(text.length)
        val context = text.substring(contextStart, contextEnd)

        val dateCuePattern = Regex(
            "\\b(?:on|by|due|before|after|until|till|from|starting|scheduled?|appointment|meeting|deadline|birthday|anniversary|flight|exam|doctor|dentist|visit|renew|renewal|submit|pay|bill)\\b",
            RegexOption.IGNORE_CASE
        )

        return when {
            first > 12 || second > 12 -> true
            else -> dateCuePattern.containsMatchIn(context)
        }
    }

    // Parse time strings like "10am", "10:30 pm", "7:15PM" into hour and minute
    private fun parseTimeStringToHourMinute(timeStr: String): Pair<Int, Int>? {
        try {
            var s = timeStr.lowercase().trim()
            val ampm = when {
                s.endsWith("am") -> "am"
                s.endsWith("pm") -> "pm"
                else -> null
            }
            s = s.replace("am", "").replace("pm", "").trim()
            val parts = s.split(":")
            var hour = parts[0].toIntOrNull() ?: return null
            val minute = if (parts.size > 1) parts[1].toIntOrNull() ?: 0 else 0
            if (ampm != null) {
                if (ampm == "pm" && hour < 12) hour += 12
                if (ampm == "am" && hour == 12) hour = 0
            }
            if (hour in 0..23 && minute in 0..59) return Pair(hour, minute)
        } catch (_: Exception) {
            // ignore
        }
        return null
    }

    /**
     * Phase 2: Detect recurrence patterns from text.
     * Recognizes English and Hinglish phrases like "every day", "daily", "weekly",
     * "every Monday", "har hafte", "roz", etc.
     *
     * @return DetectedRecurrence if a recurrence pattern is found with confidence >= 0.7, null otherwise
     */
    fun detectRecurrence(text: String): DetectedRecurrence? {

        // "every day" / "daily" / "roz" / "har din" / "har roz"
        val dailyPatterns = listOf(
            Regex("\\bevery\\s+day\\b", RegexOption.IGNORE_CASE),
            Regex("\\bdaily\\b", RegexOption.IGNORE_CASE),
            Regex("\\broz\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+din\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+roz\\b", RegexOption.IGNORE_CASE),
            Regex("\\bdaily\\s+at\\b", RegexOption.IGNORE_CASE),
            Regex("\\beveryday\\b", RegexOption.IGNORE_CASE)
        )
        if (dailyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "DAILY", interval = 1)
        }

        // "every N days"
        val everyNDays = Regex("\\bevery\\s+(\\d+)\\s+days?\\b", RegexOption.IGNORE_CASE)
        everyNDays.find(text)?.let { m ->
            val n = m.groupValues[1].toIntOrNull() ?: 1
            return DetectedRecurrence(type = "DAILY", interval = n)
        }

        // Specific weekday recurrence: "every Monday", "every mon/wed/fri", "har Monday"
        val weekdays = mapOf(
            "sunday" to 1, "sun" to 1,
            "monday" to 2, "mon" to 2,
            "tuesday" to 3, "tue" to 3,
            "wednesday" to 4, "wed" to 4,
            "thursday" to 5, "thu" to 5,
            "friday" to 6, "fri" to 6,
            "saturday" to 7, "sat" to 7
        )
        val weekdayNames = weekdays.keys.joinToString("|")
        val everyWeekdayPattern = Regex(
            "\\b(?:every|har)\\s+($weekdayNames)(?:\\s*(?:,|and|aur|&)\\s*($weekdayNames))*\\b",
            RegexOption.IGNORE_CASE
        )
        everyWeekdayPattern.find(text)?.let { m ->
            // Extract all mentioned days from the matched region
            val matchedText = m.value.lowercase()
            val days = weekdays.filter { matchedText.contains(it.key) }.values.toSortedSet()
            if (days.isNotEmpty()) {
                return DetectedRecurrence(
                    type = "WEEKLY",
                    interval = 1,
                    daysOfWeek = days.joinToString(",")
                )
            }
        }

        // "weekdays" / "weekday" / "on weekdays"
        val weekdaysPattern = Regex("\\b(?:every\\s+)?weekdays?\\b", RegexOption.IGNORE_CASE)
        if (weekdaysPattern.containsMatchIn(text)) {
            return DetectedRecurrence(type = "WEEKLY", interval = 1, daysOfWeek = "2,3,4,5,6") // Mon-Fri
        }

        // "weekly" / "every week" / "har hafte" / "har hafta"
        val weeklyPatterns = listOf(
            Regex("\\bweekly\\b", RegexOption.IGNORE_CASE),
            Regex("\\bevery\\s+week\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+haft[ea]\\b", RegexOption.IGNORE_CASE)
        )
        if (weeklyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "WEEKLY", interval = 1)
        }

        // "every N weeks"
        val everyNWeeks = Regex("\\bevery\\s+(\\d+)\\s+weeks?\\b", RegexOption.IGNORE_CASE)
        everyNWeeks.find(text)?.let { m ->
            val n = m.groupValues[1].toIntOrNull() ?: 1
            return DetectedRecurrence(type = "WEEKLY", interval = n)
        }

        // "monthly" / "every month" / "har mahine" / "har mahiney"
        val monthlyPatterns = listOf(
            Regex("\\bmonthly\\b", RegexOption.IGNORE_CASE),
            Regex("\\bevery\\s+month\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+mahin[ey]+\\b", RegexOption.IGNORE_CASE)
        )
        if (monthlyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "MONTHLY", interval = 1)
        }

        // "every N months"
        val everyNMonths = Regex("\\bevery\\s+(\\d+)\\s+months?\\b", RegexOption.IGNORE_CASE)
        everyNMonths.find(text)?.let { m ->
            val n = m.groupValues[1].toIntOrNull() ?: 1
            return DetectedRecurrence(type = "MONTHLY", interval = n)
        }

        // "yearly" / "every year" / "annually" / "har saal"
        val yearlyPatterns = listOf(
            Regex("\\byearly\\b", RegexOption.IGNORE_CASE),
            Regex("\\bevery\\s+year\\b", RegexOption.IGNORE_CASE),
            Regex("\\bannually\\b", RegexOption.IGNORE_CASE),
            Regex("\\bhar\\s+saal\\b", RegexOption.IGNORE_CASE)
        )
        if (yearlyPatterns.any { it.containsMatchIn(text) }) {
            return DetectedRecurrence(type = "YEARLY", interval = 1)
        }

        return null
    }

}

/**
 * Data class representing a detected reminder
 */
data class DetectedReminder(
    val id: String,
    val title: String,
    val description: String,
    val extractedText: String,
    val reminderDateTime: Long,
    val confidence: Float,
    val entityType: String,
    val originalNoteTitle: String,
    val isConfirmed: Boolean = false,
    // Phase 2: Detected recurrence info from AI
    val detectedRecurrence: DetectedRecurrence? = null
)

/**
 * Phase 2: Data class representing detected recurrence from text analysis.
 * Returned alongside a DetectedReminder when patterns like "every day", "daily", "weekly" etc. are found.
 */
data class DetectedRecurrence(
    val type: String,       // RecurrenceType constant: DAILY, WEEKLY, MONTHLY, YEARLY
    val interval: Int = 1,  // e.g., "every 2 weeks" → 2
    val daysOfWeek: String? = null  // CSV for specific days, e.g. "2,3,4,5,6" for weekdays
)

package com.amvarpvtltd.swiftNote.sync

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.isBlank
import com.amvarpvtltd.swiftNote.isDecryptFailed
import com.amvarpvtltd.swiftNote.reminders.ReminderEntity
import com.amvarpvtltd.swiftNote.reminders.isDecryptFailed
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import com.amvarpvtltd.swiftNote.security.EncryptionUtil
import com.amvarpvtltd.swiftNote.myGlobalMobileDeviceId
import com.google.firebase.database.FirebaseDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext

object SyncManager {
    private const val TAG = "SyncManager"

    // Mutex to prevent concurrent sync operations — ensures only one sync runs at a time
    private val syncMutex = Mutex()
    // Separate mutex for upload operations
    private val uploadMutex = Mutex()

    /**
     * Sync data from another device's passphrase to current device.
     * This is a one-time copy operation, not continuous sync.
     * Protected by syncMutex to prevent concurrent syncs causing data races.
     *
     * @param cleanTargetBeforeUpload When true and source != current, the destination
     *   Firebase path (users/{currentPassphrase}/notes + /reminders) is wiped before
     *   re-uploading the restored notes. Pass true from the Restore flow to guarantee
     *   the destination starts clean (belt-and-suspenders on top of the local+remote
     *   wipe already performed by DataCleanupManager.wipeLocalAndPreviousRemoteNotes).
     */
    suspend fun syncDataFromPassphrase(
        context: Context,
        sourcePassphrase: String,
        currentPassphrase: String,
        cleanTargetBeforeUpload: Boolean = false
    ): Result<SyncResult> = withContext(Dispatchers.IO) {
        // Acquire mutex — if another sync is running, this coroutine suspends until it finishes
        syncMutex.withLock {
            // Ensure app is authenticated before accessing Firebase
            val authResult = PassphraseManager.ensureAuthenticated()
            if (authResult.isFailure) {
                val ex = authResult.exceptionOrNull()
                Log.e(TAG, "Auth failed before sync: ${ex?.message}")
                return@withContext Result.failure(Exception("Authentication failed: ${ex?.message ?: "unknown"}"))
            }

            return@withContext try {
                val database = FirebaseDatabase.getInstance()
                val sourceRef = database.getReference("users").child(sourcePassphrase)

                // Fetch all notes from source device
                val notesSnapshot = sourceRef.child("notes").get().await()
                val remindersSnapshot = sourceRef.child("reminders").get().await()

                val syncedNotes = mutableListOf<dataclass>()

                // Get local database
                val db = AppDatabase.getInstance(context)
                val noteDao = db.noteDao()
                val reminderDao = db.reminderDao()

                // Helper to attempt decryption with candidate keys
                fun tryDecryptWithCandidates(encrypted: dataclass, candidates: List<String>): dataclass? {
                    // Reject blank-content nodes outright — these are stale/corrupted entries
                    // (root cause of "many blank notes appearing after sync"). Don't import them.
                    if (encrypted.isBlank()) {
                        Log.w(TAG, "Skipping blank remote note ${encrypted.id}")
                        return null
                    }

                    // If the title/description don't look encrypted, treat as plaintext
                    val looksEncrypted = EncryptionUtil.isPotentiallyEncrypted(encrypted.title) || EncryptionUtil.isPotentiallyEncrypted(encrypted.description)

                    if (!looksEncrypted) {
                        return dataclass(
                            title = encrypted.title,
                            description = encrypted.description,
                            id = encrypted.id,
                            mymobiledeviceid = encrypted.mymobiledeviceid,
                            timestamp = encrypted.timestamp
                        )
                    }

                    for (key in candidates) {
                        try {
                            val t = EncryptionUtil.decrypt(encrypted.title, key)
                            val d = EncryptionUtil.decrypt(encrypted.description, key)
                            if (t != null && d != null) {
                                Log.d(TAG, "Decryption successful for note ${encrypted.id}")
                                return dataclass(title = t, description = d, id = encrypted.id, mymobiledeviceid = encrypted.mymobiledeviceid, timestamp = encrypted.timestamp)
                            }
                        } catch (e: Exception) {
                            // Don't log key details — security sensitive
                            Log.d(TAG, "Candidate key decryption failed for note ${encrypted.id}")
                        }
                    }

                    for (rawKey in candidates) {
                        if (rawKey.isBlank()) continue
                        val vset = mutableSetOf<String>()
                        val k = rawKey.trim()
                        vset.add(k)
                        vset.add(k.lowercase())
                        vset.add(k.uppercase())
                        vset.add(k.replace("-", ""))
                        vset.add(k.replace(Regex("[^A-Za-z0-9]"), ""))

                        val cleaned = k.replace(Regex("[^A-Za-z0-9]"), "")
                        listOf(16, 20, 32).forEach { n -> if (cleaned.length >= n) vset.add(cleaned.substring(0, n)) }

                        try { vset.add(java.net.URLDecoder.decode(k, "UTF-8").trim()) } catch (_: Exception) {}

                        try {
                            if (k.matches(Regex("^[A-Za-z0-9+/=]+$") )) {
                                val decoded = String(java.util.Base64.getDecoder().decode(k))
                                vset.add(decoded)
                            }
                        } catch (_: Exception) {}

                        for (variant in vset) {
                            try {
                                val t = EncryptionUtil.decrypt(encrypted.title, variant)
                                val d = EncryptionUtil.decrypt(encrypted.description, variant)
                                if (t != null && d != null) {
                                    Log.d(TAG, "Decryption successful for note ${encrypted.id} using key variant")
                                    return dataclass(title = t, description = d, id = encrypted.id, mymobiledeviceid = encrypted.mymobiledeviceid, timestamp = encrypted.timestamp)
                                }
                            } catch (e: Exception) {
                                // Don't log exception details — may contain key material
                                Log.d(TAG, "Decryption variant attempt failed for note ${encrypted.id}")
                            }
                        }
                    }

                    Log.e(TAG, "All decryption attempts failed for note ${encrypted.id}")
                    return null
                }

                // Process notes
                if (notesSnapshot.exists()) {
                    for (firstLevelChild in notesSnapshot.children) {
                        try {
                            if (firstLevelChild.child("title").exists() || firstLevelChild.child("description").exists()) {
                                val noteData = firstLevelChild.getValue(dataclass::class.java)
                                if (noteData != null) {
                                    val candidates = listOfNotNull(currentPassphrase, noteData.mymobiledeviceid, sourcePassphrase, myGlobalMobileDeviceId).distinct()
                                    val decrypted = tryDecryptWithCandidates(noteData, candidates)
                                    if (decrypted == null) {
                                        Log.w(TAG, "Skipping note ${noteData.id} because decryption failed for all keys")
                                    } else if (decrypted.isBlank() || decrypted.isDecryptFailed()) {
                                        Log.w(TAG, "Skipping note ${noteData.id} — blank or failed-decrypt after decode")
                                    } else {
                                        val localNote = decrypted.copy(mymobiledeviceid = currentPassphrase, timestamp = decrypted.timestamp)
                                        // Preserve local pin/archive/category if note already exists locally
                                        val existingEntity = noteDao.getNoteById(localNote.id)
                                        val mergedNote = if (existingEntity != null) {
                                            localNote.copy(
                                                isPinned = existingEntity.isPinned,
                                                isArchived = existingEntity.isArchived,
                                                category = existingEntity.category.ifBlank { localNote.category },
                                                colorKey = existingEntity.colorKey ?: localNote.colorKey
                                            )
                                        } else {
                                            localNote
                                        }
                                        val entity = NoteEntityMapper.toEntity(mergedNote, synced = false)
                                        noteDao.insert(entity)
                                        syncedNotes.add(mergedNote)
                                        Log.d(TAG, "Synced note: ${mergedNote.title}")
                                    }
                                }
                            } else {
                                for (noteChild in firstLevelChild.children) {
                                    try {
                                        val noteData = noteChild.getValue(dataclass::class.java)
                                        if (noteData != null) {
                                            val candidates = listOfNotNull(currentPassphrase, noteData.mymobiledeviceid, sourcePassphrase, myGlobalMobileDeviceId).distinct()
                                            val decrypted = tryDecryptWithCandidates(noteData, candidates)
                                            if (decrypted == null) {
                                                Log.w(TAG, "Skipping nested note ${noteData.id} because decryption failed for all keys")
                                            } else if (decrypted.isBlank() || decrypted.isDecryptFailed()) {
                                                Log.w(TAG, "Skipping nested note ${noteData.id} — blank or failed-decrypt after decode")
                                            } else {
                                                val localNote = decrypted.copy(mymobiledeviceid = currentPassphrase, timestamp = decrypted.timestamp)
                                                // Preserve local pin/archive/category if note already exists locally
                                                val existingEntity = noteDao.getNoteById(localNote.id)
                                                val mergedNote = if (existingEntity != null) {
                                                    localNote.copy(
                                                        isPinned = existingEntity.isPinned,
                                                        isArchived = existingEntity.isArchived,
                                                        category = existingEntity.category.ifBlank { localNote.category },
                                                        colorKey = existingEntity.colorKey ?: localNote.colorKey
                                                    )
                                                } else {
                                                    localNote
                                                }
                                                val entity = NoteEntityMapper.toEntity(mergedNote, synced = false)
                                                noteDao.insert(entity)
                                                syncedNotes.add(mergedNote)
                                                Log.d(TAG, "Synced note: ${mergedNote.title}")
                                            }
                                        }
                                    } catch (ie: Exception) {
                                        Log.w(TAG, "Failed to sync nested note: ${noteChild.key}", ie)
                                    }
                                }
                            }
                        } catch (e: Exception) {
                            Log.w(TAG, "Failed to sync note node: ${firstLevelChild.key}", e)
                        }
                    }
                }

                // Process reminders (nested: reminders/{deviceId}/{reminderId}; falls back to legacy flat reminders/{reminderId})
                if (remindersSnapshot.exists()) {
                    val reminderKeyCandidates = listOfNotNull(
                        currentPassphrase,
                        sourcePassphrase,
                        myGlobalMobileDeviceId
                    ).filter { it.isNotEmpty() }.distinct()

                    suspend fun processRemoteReminder(raw: ReminderEntity?, keyForLog: String?) {
                        if (raw == null) return
                        try {
                            val decryptedReminder = ReminderEntity.fromEncryptedData(raw, reminderKeyCandidates)
                            if (decryptedReminder.isDecryptFailed()) {
                                Log.w(TAG, "Skipping reminder ${raw.id} — decryption failed for all keys")
                            } else {
                                reminderDao.insertReminder(decryptedReminder)
                                Log.d(TAG, "Synced reminder: ${decryptedReminder.noteTitle}")
                            }
                        } catch (e: Exception) {
                            Log.w(TAG, "Failed to sync reminder: $keyForLog", e)
                        }
                    }

                    for (firstLevel in remindersSnapshot.children) {
                        // Detect legacy flat layout: leaf has reminder fields directly.
                        val asReminder = try { firstLevel.getValue(ReminderEntity::class.java) } catch (_: Exception) { null }
                        if (asReminder != null && asReminder.id.isNotEmpty()) {
                            processRemoteReminder(asReminder, firstLevel.key)
                            continue
                        }
                        // Otherwise nested: iterate reminder children under this deviceId.
                        for (reminderChild in firstLevel.children) {
                            val r = try { reminderChild.getValue(ReminderEntity::class.java) } catch (_: Exception) { null }
                            processRemoteReminder(r, reminderChild.key)
                        }
                    }
                }

                // Belt-and-suspenders: clean destination path before re-uploading
                // restored notes so no stale data from a previous identity mixes in.
                // Only applies when the caller opted in AND source != current identity
                // (self-sync on reinstall doesn't need this).
                if (cleanTargetBeforeUpload && sourcePassphrase != currentPassphrase) {
                    try {
                        val destRef = database.getReference("users").child(currentPassphrase)
                        destRef.child("notes").removeValue().await()
                        destRef.child("reminders").removeValue().await()
                        Log.d(TAG, "Cleaned destination path before restore upload")
                    } catch (e: Exception) {
                        Log.w(TAG, "Failed to clean destination path (non-fatal): ${e.message}")
                    }
                }

                // Now upload the synced data to current device's Firebase node
                uploadLocalDataToFirebase(context, currentPassphrase)

                val result = SyncResult(
                    syncedNotesCount = syncedNotes.size,
                    sourcePassphrase = sourcePassphrase,
                    targetPassphrase = currentPassphrase
                )

                Log.d(TAG, "Sync completed: $result")
                Result.success(result)

            } catch (e: Exception) {
                Log.e(TAG, "Sync failed", e)
                Result.failure(e)
            }
        }
    }

    /**
     * Upload all local data to Firebase under current device's passphrase.
     * Protected by uploadMutex to prevent concurrent uploads corrupting remote state.
     */
    suspend fun uploadLocalDataToFirebase(
        context: Context,
        passphrase: String
    ): Result<Unit> = withContext(Dispatchers.IO) {
        uploadMutex.withLock {
            // Ensure app is authenticated before uploading
            val authResult = PassphraseManager.ensureAuthenticated()
            if (authResult.isFailure) {
                val ex = authResult.exceptionOrNull()
                Log.e(TAG, "Auth failed before upload: ${ex?.message}")
                return@withContext Result.failure(Exception("Authentication failed: ${ex?.message ?: "unknown"}"))
            }

            return@withContext try {
                val database = FirebaseDatabase.getInstance()
                val userRef = database.getReference("users").child(passphrase)

                val db = AppDatabase.getInstance(context)
                val noteDao = db.noteDao()
                val reminderDao = db.reminderDao()

                val localNotes = noteDao.getAllNotes()
                val localReminders = reminderDao.getAllReminders()

                val notesRef = userRef.child("notes")
                var uploadedCount = 0
                var skippedBlankCount = 0
                for (noteEntity in localNotes) {
                    val note = NoteEntityMapper.toDomain(noteEntity)
                    if (note.isBlank() || note.isDecryptFailed()) {
                        // Defence: never upload blank/failed notes. Also remove any stale
                        // blank already at this path so the cycle of spreading blanks stops.
                        skippedBlankCount++
                        try {
                            val deviceId = if (note.mymobiledeviceid.isNotEmpty()) note.mymobiledeviceid else passphrase
                            notesRef.child(deviceId).child(note.id).removeValue().await()
                        } catch (_: Exception) { /* best-effort cleanup */ }
                        continue
                    }
                    val encryptedNote = note.toEncryptedData()
                    val deviceId = if (encryptedNote.mymobiledeviceid.isNotEmpty()) encryptedNote.mymobiledeviceid else passphrase
                    notesRef.child(deviceId).child(note.id).setValue(encryptedNote).await()
                    uploadedCount++
                }
                if (skippedBlankCount > 0) {
                    Log.w(TAG, "Skipped uploading $skippedBlankCount blank/failed local notes (and purged from Firebase)")
                }

                val remindersRef = userRef.child("reminders")
                val uploadDeviceId = com.amvarpvtltd.swiftNote.auth.DeviceManager.getOrCreateDeviceId(context)
                for (reminder in localReminders) {
                    val encryptedReminder = try {
                        reminder.toEncryptedData(passphrase)
                    } catch (e: IllegalArgumentException) {
                        Log.w(TAG, "Skipping reminder ${reminder.id}: ${e.message}")
                        continue
                    } catch (e: Exception) {
                        Log.w(TAG, "Failed to encrypt reminder ${reminder.id}, skipping upload", e)
                        continue
                    }
                    // Mirror notes layout: users/{accountId}/reminders/{deviceId}/{reminderId}
                    remindersRef.child(uploadDeviceId).child(reminder.id).setValue(encryptedReminder).await()
                }

                userRef.child("lastSyncAt").setValue(System.currentTimeMillis()).await()
                userRef.child("totalNotes").setValue(uploadedCount).await()

                Log.d(TAG, "Uploaded $uploadedCount notes and ${localReminders.size} reminders to Firebase")
                Result.success(Unit)

            } catch (e: Exception) {
                Log.e(TAG, "Failed to upload data to Firebase", e)
                Result.failure(e)
            }
        }
    }

    /**
     * Get sync statistics for a passphrase
     */
    suspend fun getSyncStats(passphrase: String): Result<SyncStats> = withContext(Dispatchers.IO) {
        // Ensure app is authenticated before fetching stats
        val authResult = PassphraseManager.ensureAuthenticated()
        if (authResult.isFailure) {
            val ex = authResult.exceptionOrNull()
            Log.e(TAG, "Auth failed before getSyncStats: ${ex?.message}")
            return@withContext Result.failure(Exception("Authentication failed: ${ex?.message ?: "unknown"}"))
        }

        return@withContext try {
            val database = FirebaseDatabase.getInstance()
            val userRef = database.getReference("users").child(passphrase)

            val snapshot = userRef.get().await()

            if (snapshot.exists()) {
                val totalNotes = snapshot.child("totalNotes").getValue(Int::class.java) ?: 0
                val lastSyncAt = snapshot.child("lastSyncAt").getValue(Long::class.java) ?: 0L
                val createdAt = snapshot.child("createdAt").getValue(Long::class.java) ?: 0L

                val stats = SyncStats(
                    totalNotes = totalNotes,
                    lastSyncAt = lastSyncAt,
                    createdAt = createdAt
                )

                Result.success(stats)
            } else {
                Result.success(SyncStats())
            }

        } catch (e: Exception) {
            Log.e(TAG, "Failed to get sync stats", e)
            Result.failure(e)
        }
    }
}

data class SyncResult(
    val syncedNotesCount: Int,
    val sourcePassphrase: String,
    val targetPassphrase: String
)

data class SyncStats(
    val totalNotes: Int = 0,
    val lastSyncAt: Long = 0L,
    val createdAt: Long = 0L
)

package com.amvarpvtltd.swiftNote.sync

import android.content.Context
import android.util.Log
import com.amvarpvtltd.swiftNote.auth.PassphraseManager
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.isBlank
import com.amvarpvtltd.swiftNote.isDecryptFailed
import com.amvarpvtltd.swiftNote.reminders.ReminderEntity
import com.amvarpvtltd.swiftNote.reminders.isDecryptFailed
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import com.amvarpvtltd.swiftNote.security.EncryptionUtil
import com.amvarpvtltd.swiftNote.myGlobalMobileDeviceId
import com.google.firebase.database.FirebaseDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext

object SyncManager {
    private const val TAG = "SyncManager"

    // Mutex to prevent concurrent sync operations — ensures only one sync runs at a time
    private val syncMutex = Mutex()
    // Separate mutex for upload operations
    private val uploadMutex = Mutex()

    /**
     * Sync data from another device's passphrase to current device.
     * This is a one-time copy operation, not continuous sync.
     * Protected by syncMutex to prevent concurrent syncs causing data races.
     *
     * @param cleanTargetBeforeUpload When true and source != current, the destination
     *   Firebase path (users/{currentPassphrase}/notes + /reminders) is wiped before
     *   re-uploading the restored notes. Pass true from the Restore flow to guarantee
     *   the destination starts clean (belt-and-suspenders on top of the local+remote
     *   wipe already performed by DataCleanupManager.wipeLocalAndPreviousRemoteNotes).
     */
    suspend fun syncDataFromPassphrase(
        context: Context,
        sourcePassphrase: String,
        currentPassphrase: String,
        cleanTargetBeforeUpload: Boolean = false
    ): Result<SyncResult> = withContext(Dispatchers.IO) {
        // Acquire mutex — if another sync is running, this coroutine suspends until it finishes
        syncMutex.withLock {
            // Ensure app is authenticated before accessing Firebase
            val authResult = PassphraseManager.ensureAuthenticated()
            if (authResult.isFailure) {
                val ex = authResult.exceptionOrNull()
                Log.e(TAG, "Auth failed before sync: ${ex?.message}")
                return@withContext Result.failure(Exception("Authentication failed: ${ex?.message ?: "unknown"}"))
            }

            return@withContext try {
                val database = FirebaseDatabase.getInstance()
                val sourceRef = database.getReference("users").child(sourcePassphrase)

                // Fetch all notes from source device
                val notesSnapshot = sourceRef.child("notes").get().await()
                val remindersSnapshot = sourceRef.child("reminders").get().await()

                val syncedNotes = mutableListOf<dataclass>()

                // Get local database
                val db = AppDatabase.getInstance(context)
                val noteDao = db.noteDao()
                val reminderDao = db.reminderDao()

                // Helper to attempt decryption with candidate keys
                fun tryDecryptWithCandidates(encrypted: dataclass, candidates: List<String>): dataclass? {
                    // Reject blank-content nodes outright — these are stale/corrupted entries
                    // (root cause of "many blank notes appearing after sync"). Don't import them.
                    if (encrypted.isBlank()) {
                        Log.w(TAG, "Skipping blank remote note ${encrypted.id}")
                        return null
                    }

                    // If the title/description don't look encrypted, treat as plaintext
                    val looksEncrypted = EncryptionUtil.isPotentiallyEncrypted(encrypted.title) || EncryptionUtil.isPotentiallyEncrypted(encrypted.description)

                    if (!looksEncrypted) {
                        return dataclass(
                            title = encrypted.title,
                            description = encrypted.description,
                            id = encrypted.id,
                            mymobiledeviceid = encrypted.mymobiledeviceid,
                            timestamp = encrypted.timestamp
                        )
                    }

                    for (key in candidates) {
                        try {
                            val t = EncryptionUtil.decrypt(encrypted.title, key)
                            val d = EncryptionUtil.decrypt(encrypted.description, key)
                            if (t != null && d != null) {
                                Log.d(TAG, "Decryption successful for note ${encrypted.id}")
                                return dataclass(title = t, description = d, id = encrypted.id, mymobiledeviceid = encrypted.mymobiledeviceid, timestamp = encrypted.timestamp)
                            }
                        } catch (e: Exception) {
                            // Don't log key details — security sensitive
                            Log.d(TAG, "Candidate key decryption failed for note ${encrypted.id}")
                        }
                    }

                    for (rawKey in candidates) {
                        if (rawKey.isBlank()) continue
                        val vset = mutableSetOf<String>()
                        val k = rawKey.trim()
                        vset.add(k)
                        vset.add(k.lowercase())
                        vset.add(k.uppercase())
                        vset.add(k.replace("-", ""))
                        vset.add(k.replace(Regex("[^A-Za-z0-9]"), ""))

                        val cleaned = k.replace(Regex("[^A-Za-z0-9]"), "")
                        listOf(16, 20, 32).forEach { n -> if (cleaned.length >= n) vset.add(cleaned.substring(0, n)) }

                        try { vset.add(java.net.URLDecoder.decode(k, "UTF-8").trim()) } catch (_: Exception) {}

                        try {
                            if (k.matches(Regex("^[A-Za-z0-9+/=]+$") )) {
                                val decoded = String(java.util.Base64.getDecoder().decode(k))
                                vset.add(decoded)
                            }
                        } catch (_: Exception) {}

                        for (variant in vset) {
                            try {
                                val t = EncryptionUtil.decrypt(encrypted.title, variant)
                                val d = EncryptionUtil.decrypt(encrypted.description, variant)
                                if (t != null && d != null) {
                                    Log.d(TAG, "Decryption successful for note ${encrypted.id} using key variant")
                                    return dataclass(title = t, description = d, id = encrypted.id, mymobiledeviceid = encrypted.mymobiledeviceid, timestamp = encrypted.timestamp)
                                }
                            } catch (e: Exception) {
                                // Don't log exception details — may contain key material
                                Log.d(TAG, "Decryption variant attempt failed for note ${encrypted.id}")
                            }
                        }
                    }

                    Log.e(TAG, "All decryption attempts failed for note ${encrypted.id}")
                    return null
                }

                // Process notes
                if (notesSnapshot.exists()) {
                    for (firstLevelChild in notesSnapshot.children) {
                        try {
                            if (firstLevelChild.child("title").exists() || firstLevelChild.child("description").exists()) {
                                val noteData = firstLevelChild.getValue(dataclass::class.java)
                                if (noteData != null) {
                                    val candidates = listOfNotNull(currentPassphrase, noteData.mymobiledeviceid, sourcePassphrase, myGlobalMobileDeviceId).distinct()
                                    val decrypted = tryDecryptWithCandidates(noteData, candidates)
                                    if (decrypted == null) {
                                        Log.w(TAG, "Skipping note ${noteData.id} because decryption failed for all keys")
                                    } else if (decrypted.isBlank() || decrypted.isDecryptFailed()) {
                                        Log.w(TAG, "Skipping note ${noteData.id} — blank or failed-decrypt after decode")
                                    } else {
                                        val localNote = decrypted.copy(mymobiledeviceid = currentPassphrase, timestamp = decrypted.timestamp)
                                        // Preserve local pin/archive/category if note already exists locally
                                        val existingEntity = noteDao.getNoteById(localNote.id)
                                        val mergedNote = if (existingEntity != null) {
                                            localNote.copy(
                                                isPinned = existingEntity.isPinned,
                                                isArchived = existingEntity.isArchived,
                                                category = existingEntity.category.ifBlank { localNote.category },
                                                colorKey = existingEntity.colorKey ?: localNote.colorKey
                                            )
                                        } else {
                                            localNote
                                        }
                                        val entity = NoteEntityMapper.toEntity(mergedNote, synced = false)
                                        noteDao.insert(entity)
                                        syncedNotes.add(mergedNote)
                                        Log.d(TAG, "Synced note: ${mergedNote.title}")
                                    }
                                }
                            } else {
                                for (noteChild in firstLevelChild.children) {
                                    try {
                                        val noteData = noteChild.getValue(dataclass::class.java)
                                        if (noteData != null) {
                                            val candidates = listOfNotNull(currentPassphrase, noteData.mymobiledeviceid, sourcePassphrase, myGlobalMobileDeviceId).distinct()
                                            val decrypted = tryDecryptWithCandidates(noteData, candidates)
                                            if (decrypted == null) {
                                                Log.w(TAG, "Skipping nested note ${noteData.id} because decryption failed for all keys")
                                            } else if (decrypted.isBlank() || decrypted.isDecryptFailed()) {
                                                Log.w(TAG, "Skipping nested note ${noteData.id} — blank or failed-decrypt after decode")
                                            } else {
                                                val localNote = decrypted.copy(mymobiledeviceid = currentPassphrase, timestamp = decrypted.timestamp)
                                                // Preserve local pin/archive/category if note already exists locally
                                                val existingEntity = noteDao.getNoteById(localNote.id)
                                                val mergedNote = if (existingEntity != null) {
                                                    localNote.copy(
                                                        isPinned = existingEntity.isPinned,
                                                        isArchived = existingEntity.isArchived,
                                                        category = existingEntity.category.ifBlank { localNote.category },
                                                        colorKey = existingEntity.colorKey ?: localNote.colorKey
                                                    )
                                                } else {
                                                    localNote
                                                }
                                                val entity = NoteEntityMapper.toEntity(mergedNote, synced = false)
                                                noteDao.insert(entity)
                                                syncedNotes.add(mergedNote)
                                                Log.d(TAG, "Synced note: ${mergedNote.title}")
                                            }
                                        }
                                    } catch (ie: Exception) {
                                        Log.w(TAG, "Failed to sync nested note: ${noteChild.key}", ie)
                                    }
                                }
                            }
                        } catch (e: Exception) {
                            Log.w(TAG, "Failed to sync note node: ${firstLevelChild.key}", e)
                        }
                    }
                }

                // Process reminders (nested: reminders/{deviceId}/{reminderId}; falls back to legacy flat reminders/{reminderId})
                if (remindersSnapshot.exists()) {
                    val reminderKeyCandidates = listOfNotNull(
                        currentPassphrase,
                        sourcePassphrase,
                        myGlobalMobileDeviceId
                    ).filter { it.isNotEmpty() }.distinct()

                    suspend fun processRemoteReminder(raw: ReminderEntity?, keyForLog: String?) {
                        if (raw == null) return
                        try {
                            val decryptedReminder = ReminderEntity.fromEncryptedData(raw, reminderKeyCandidates)
                            if (decryptedReminder.isDecryptFailed()) {
                                Log.w(TAG, "Skipping reminder ${raw.id} — decryption failed for all keys")
                            } else {
                                reminderDao.insertReminder(decryptedReminder)
                                Log.d(TAG, "Synced reminder ${decryptedReminder.id}")
                            }
                        } catch (e: Exception) {
                            Log.w(TAG, "Failed to sync reminder: $keyForLog", e)
                        }
                    }

                    for (firstLevel in remindersSnapshot.children) {
                        // Detect legacy flat layout: leaf has reminder fields directly.
                        val asReminder = try { firstLevel.getValue(ReminderEntity::class.java) } catch (_: Exception) { null }
                        if (asReminder != null && asReminder.id.isNotEmpty()) {
                            processRemoteReminder(asReminder, firstLevel.key)
                            continue
                        }
                        // Otherwise nested: iterate reminder children under this deviceId.
                        for (reminderChild in firstLevel.children) {
                            val r = try { reminderChild.getValue(ReminderEntity::class.java) } catch (_: Exception) { null }
                            processRemoteReminder(r, reminderChild.key)
                        }
                    }
                }

                // Belt-and-suspenders: clean destination path before re-uploading
                // restored notes so no stale data from a previous identity mixes in.
                // Only applies when the caller opted in AND source != current identity
                // (self-sync on reinstall doesn't need this).
                if (cleanTargetBeforeUpload && sourcePassphrase != currentPassphrase) {
                    try {
                        val destRef = database.getReference("users").child(currentPassphrase)
                        destRef.child("notes").removeValue().await()
                        destRef.child("reminders").removeValue().await()
                        Log.d(TAG, "Cleaned destination path before restore upload")
                    } catch (e: Exception) {
                        Log.w(TAG, "Failed to clean destination path (non-fatal): ${e.message}")
                    }
                }

                // Now upload the synced data to current device's Firebase node
                uploadLocalDataToFirebase(context, currentPassphrase)

                val result = SyncResult(
                    syncedNotesCount = syncedNotes.size,
                    sourcePassphrase = sourcePassphrase,
                    targetPassphrase = currentPassphrase
                )

                Log.d(TAG, "Sync completed: $result")
                Result.success(result)

            } catch (e: Exception) {
                Log.e(TAG, "Sync failed", e)
                Result.failure(e)
            }
        }
    }

    /**
     * Upload all local data to Firebase under current device's passphrase.
     * Protected by uploadMutex to prevent concurrent uploads corrupting remote state.
     */
    suspend fun uploadLocalDataToFirebase(
        context: Context,
        passphrase: String
    ): Result<Unit> = withContext(Dispatchers.IO) {
        uploadMutex.withLock {
            // Ensure app is authenticated before uploading
            val authResult = PassphraseManager.ensureAuthenticated()
            if (authResult.isFailure) {
                val ex = authResult.exceptionOrNull()
                Log.e(TAG, "Auth failed before upload: ${ex?.message}")
                return@withContext Result.failure(Exception("Authentication failed: ${ex?.message ?: "unknown"}"))
            }

            return@withContext try {
                val database = FirebaseDatabase.getInstance()
                val userRef = database.getReference("users").child(passphrase)

                val db = AppDatabase.getInstance(context)
                val noteDao = db.noteDao()
                val reminderDao = db.reminderDao()

                val localNotes = noteDao.getAllNotes()
                val localReminders = reminderDao.getAllReminders()

                val notesRef = userRef.child("notes")
                var uploadedCount = 0
                var skippedBlankCount = 0
                for (noteEntity in localNotes) {
                    val note = NoteEntityMapper.toDomain(noteEntity)
                    if (note.isBlank() || note.isDecryptFailed()) {
                        // Defence: never upload blank/failed notes. Also remove any stale
                        // blank already at this path so the cycle of spreading blanks stops.
                        skippedBlankCount++
                        try {
                            val deviceId = if (note.mymobiledeviceid.isNotEmpty()) note.mymobiledeviceid else passphrase
                            notesRef.child(deviceId).child(note.id).removeValue().await()
                        } catch (_: Exception) { /* best-effort cleanup */ }
                        continue
                    }
                    val encryptedNote = note.toEncryptedData()
                    val deviceId = if (encryptedNote.mymobiledeviceid.isNotEmpty()) encryptedNote.mymobiledeviceid else passphrase
                    notesRef.child(deviceId).child(note.id).setValue(encryptedNote).await()
                    uploadedCount++
                }
                if (skippedBlankCount > 0) {
                    Log.w(TAG, "Skipped uploading $skippedBlankCount blank/failed local notes (and purged from Firebase)")
                }

                val remindersRef = userRef.child("reminders")
                val uploadDeviceId = com.amvarpvtltd.swiftNote.auth.DeviceManager.getOrCreateDeviceId(context)
                for (reminder in localReminders) {
                    val encryptedReminder = try {
                        reminder.toEncryptedData(passphrase)
                    } catch (e: IllegalArgumentException) {
                        Log.w(TAG, "Skipping reminder ${reminder.id}: ${e.message}")
                        continue
                    } catch (e: Exception) {
                        Log.w(TAG, "Failed to encrypt reminder ${reminder.id}, skipping upload", e)
                        continue
                    }
                    // Mirror notes layout: users/{accountId}/reminders/{deviceId}/{reminderId}
                    remindersRef.child(uploadDeviceId).child(reminder.id).setValue(encryptedReminder).await()
                }

                userRef.child("lastSyncAt").setValue(System.currentTimeMillis()).await()
                userRef.child("totalNotes").setValue(uploadedCount).await()

                Log.d(TAG, "Uploaded $uploadedCount notes and ${localReminders.size} reminders to Firebase")
                Result.success(Unit)

            } catch (e: Exception) {
                Log.e(TAG, "Failed to upload data to Firebase", e)
                Result.failure(e)
            }
        }
    }

    /**
     * Get sync statistics for a passphrase
     */
    suspend fun getSyncStats(passphrase: String): Result<SyncStats> = withContext(Dispatchers.IO) {
        // Ensure app is authenticated before fetching stats
        val authResult = PassphraseManager.ensureAuthenticated()
        if (authResult.isFailure) {
            val ex = authResult.exceptionOrNull()
            Log.e(TAG, "Auth failed before getSyncStats: ${ex?.message}")
            return@withContext Result.failure(Exception("Authentication failed: ${ex?.message ?: "unknown"}"))
        }

        return@withContext try {
            val database = FirebaseDatabase.getInstance()
            val userRef = database.getReference("users").child(passphrase)

            val snapshot = userRef.get().await()

            if (snapshot.exists()) {
                val totalNotes = snapshot.child("totalNotes").getValue(Int::class.java) ?: 0
                val lastSyncAt = snapshot.child("lastSyncAt").getValue(Long::class.java) ?: 0L
                val createdAt = snapshot.child("createdAt").getValue(Long::class.java) ?: 0L

                val stats = SyncStats(
                    totalNotes = totalNotes,
                    lastSyncAt = lastSyncAt,
                    createdAt = createdAt
                )

                Result.success(stats)
            } else {
                Result.success(SyncStats())
            }

        } catch (e: Exception) {
            Log.e(TAG, "Failed to get sync stats", e)
            Result.failure(e)
        }
    }
}

data class SyncResult(
    val syncedNotesCount: Int,
    val sourcePassphrase: String,
    val targetPassphrase: String
)

data class SyncStats(
    val totalNotes: Int = 0,
    val lastSyncAt: Long = 0L,
    val createdAt: Long = 0L
)

package com.amvarpvtltd.swiftNote.notifications

import android.Manifest
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.graphics.Bitmap
import android.graphics.Canvas
import android.os.Build
import androidx.core.app.ActivityCompat
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.core.content.ContextCompat
import com.amvarpvtltd.swiftNote.MainActivity
import com.amvarpvtltd.swiftNote.R
import com.amvarpvtltd.swiftNote.checklist.ChecklistParser
import com.amvarpvtltd.swiftNote.richtext.RichTextBridge

/**
 * Helper class for managing system-level Android notifications
 * (This is different from the in-app NotificationHelper which handles UI notifications)
 */
class SystemNotificationHelper(private val context: Context) {

    companion object {
        const val CHANNEL_ID = "note_reminders"
        const val CHANNEL_NAME = "Note Reminders"
        const val CHANNEL_DESCRIPTION = "Notifications for note reminders"
        const val NOTIFICATION_ID_BASE = 1000
    }

    init {
        createNotificationChannel()
    }

    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            CHANNEL_ID,
            CHANNEL_NAME,
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            description = CHANNEL_DESCRIPTION
            enableVibration(true)
            enableLights(true)
            lightColor = ContextCompat.getColor(context, R.color.primary)
            setShowBadge(true)
        }

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.createNotificationChannel(channel)
    }

    /**
     * Show a unified reminder notification that opens the specific note when clicked
     */
    fun showReminderNotification(
        reminderId: String,
        noteId: String,
        noteTitle: String,
        noteDescription: String,
        isSmartReminder: Boolean = false
    ) {
        if (!hasNotificationPermission()) {
            return
        }

        // Strip HTML tags and decode HTML entities so the notification body
        // shows clean readable text (e.g. no "<p>…&period;</p>")
        val rawDescription = RichTextBridge.stripHtmlToPlainText(noteDescription).trim()

        // Format checklist content into readable text for notification display
        val displayDescription = if (ChecklistParser.isChecklistContent(noteDescription)) {
            val (checked, total) = ChecklistParser.progress(noteDescription)
            val items = ChecklistParser.parseItems(noteDescription)
            val unchecked = items.filter { !it.isChecked }.take(3)
            if (unchecked.isEmpty()) {
                "✓ All $total items completed!"
            } else {
                "Checklist ($checked/$total done): " + unchecked.joinToString(", ") { it.text }
            }
        } else {
            rawDescription.ifEmpty { "Tap to open your note" }
        }

        // Create an intent that will open the specific note when clicked
        val intent = Intent(context, MainActivity::class.java).apply {
            putExtra("noteId", noteId)
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            noteId.hashCode(),
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // Action: Mark as Done
        val markDoneIntent = Intent(context, NotificationActionReceiver::class.java).apply {
            action = "MARK_DONE"
            putExtra("reminderId", reminderId)
            putExtra("noteId", noteId)
            putExtra("noteTitle", noteTitle)
        }
        val markDonePendingIntent = PendingIntent.getBroadcast(
            context,
            (reminderId + "_done").hashCode(),
            markDoneIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // Action: Snooze 10 min
        val snoozeIntent = Intent(context, NotificationActionReceiver::class.java).apply {
            action = "SNOOZE"
            putExtra("reminderId", reminderId)
            putExtra("noteId", noteId)
            putExtra("noteTitle", noteTitle)
            putExtra("noteDescription", noteDescription)
        }
        val snoozePendingIntent = PendingIntent.getBroadcast(
            context,
            (reminderId + "_snooze").hashCode(),
            snoozeIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // Clean, context-aware title with a single bell emoji
        val displayTitle = when {
            noteTitle.contains("appointment", ignoreCase = true) -> " $noteTitle"
            noteTitle.contains("meeting", ignoreCase = true)     -> " $noteTitle"
            noteTitle.contains("call", ignoreCase = true)        -> " $noteTitle"
            noteTitle.contains("deadline", ignoreCase = true)    -> "⏰ $noteTitle"
            isSmartReminder -> " $noteTitle"
            else -> " $noteTitle"
        }

        // App logo as large icon for rich notification appearance
        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            // Small monochrome icon (shown in status bar)
            .setSmallIcon(R.drawable.logo)
            // Round app logo as the large icon in the notification drawer.
            // Uses getAppIconBitmap() which correctly handles adaptive icon XML on API 26+.
            .setLargeIcon(getAppIconBitmap())
            .setContentTitle(displayTitle)
            .setContentText(displayDescription)
            // BigTextStyle expands the notification to show the full note preview
            .setStyle(
                NotificationCompat.BigTextStyle()
                    .bigText(displayDescription)
                    .setBigContentTitle(displayTitle)
                    .setSummaryText(if (isSmartReminder) "SwiftNote · Smart Reminder" else "SwiftNote · Reminder")
            )
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            // Brand teal color tints the small icon and accent strip
            .setColor(ContextCompat.getColor(context, R.color.primary))
            .setColorized(false)          // let system handle background; colorized can look busy
            .setContentIntent(pendingIntent)
            .setAutoCancel(true)
            .setCategory(NotificationCompat.CATEGORY_REMINDER)
            // Named action buttons (system icons are monochrome; labels are what users see)
            .addAction(
                NotificationCompat.Action.Builder(
                    android.R.drawable.ic_menu_close_clear_cancel,
                    "✓  Done",
                    markDonePendingIntent
                ).build()
            )
            .addAction(
                NotificationCompat.Action.Builder(
                    android.R.drawable.ic_popup_reminder,
                    "⏱  Snooze 10 min",
                    snoozePendingIntent
                ).build()
            )
            .setOngoing(false)
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
            .build()

        val notificationId = NOTIFICATION_ID_BASE + reminderId.hashCode()

        try {
            NotificationManagerCompat.from(context).notify(notificationId, notification)
        } catch (e: SecurityException) {
            android.util.Log.e("SystemNotificationHelper", "Permission denied for notifications", e)
            com.amvarpvtltd.swiftNote.components.NotificationHelper.showError(
                title = "Permission Required",
                message = "Notification permission required for reminders"
            )
        }
    }

    fun cancelNotification(reminderId: String) {
        val notificationId = NOTIFICATION_ID_BASE + reminderId.hashCode()
        NotificationManagerCompat.from(context).cancel(notificationId)
    }

    /**
     * Renders the app launcher icon to a Bitmap suitable for [NotificationCompat.Builder.setLargeIcon].
     *
     * Problem: On Android 8+ (API 26+) R.mipmap.ic_launcher_round is an AdaptiveIconDrawable (XML),
     * not a raw PNG, so BitmapFactory.decodeResource() returns null on those devices.
     * This helper uses ContextCompat.getDrawable() + Canvas to rasterize ANY drawable type.
     * Falls back to R.drawable.logo4 (plain PNG) if the launcher icon can't be decoded.
     */
    private fun getAppIconBitmap(): Bitmap? {
        return try {
            val size = 192
            val drawable = ContextCompat.getDrawable(context, R.mipmap.ic_launcher_round)
                ?: ContextCompat.getDrawable(context, R.drawable.logo)
                ?: return null
            val bitmap = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
            val canvas = Canvas(bitmap)
            drawable.setBounds(0, 0, size, size)
            drawable.draw(canvas)
            bitmap
        } catch (e: Exception) {
            android.util.Log.w("SystemNotificationHelper", "Failed to render app icon, using fallback", e)
            try {
                android.graphics.BitmapFactory.decodeResource(context.resources, R.drawable.logo)
            } catch (_: Exception) {
                null
            }
        }
    }

    private fun hasNotificationPermission(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            ActivityCompat.checkSelfPermission(
                context,
                Manifest.permission.POST_NOTIFICATIONS
            ) == PackageManager.PERMISSION_GRANTED
        } else {
            true
        }
    }
}

